--
-- Name: audit_retention_batches; Type: TABLE; Schema: public; Owner: -
--

/* public.audit_retention_batches
 * Kết quả immutable của từng batch audit purge, commit cùng DELETE audit; batch ID là khóa replay để
 * retry không xóa thêm hoặc trả count giả. Không chứa nội dung audit đã xóa.
 */
-- Bảng audit_retention_batches: Kết quả immutable của từng batch audit purge, commit cùng DELETE audit; batch ID
-- là khóa replay để retry không xóa thêm hoặc trả count giả. Không chứa nội dung audit đã xóa.
CREATE TABLE public.audit_retention_batches (
    -- Identity UUID không nil của intent batch, primary key không NULL/không trùng; retry cùng ID phải giữ run và
    -- batch limit gốc.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành audit_retention_batches_batch_id_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((batch_id <> '00000000-0000-0000-0000-000000000000'::uuid))
    -- Ràng buộc hiện hành audit_retention_batches_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (batch_id)
    batch_id uuid NOT NULL,

    -- Run/cutoff mà batch tham chiếu bằng khóa ngoại; không cascade xóa result và không sao chép cutoff vào từng batch
    -- gây lặp phụ thuộc hàm.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành audit_retention_batches_run_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id
    -- giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (run_id) REFERENCES audit_retention_runs(run_id)
    run_id uuid NOT NULL,

    -- Số audit tối đa một transaction được xóa, bắt buộc trong1…1000 để giới hạn lock/runtime; là một phần body
    -- identity của batch replay.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_audit_retention_batch_count: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((removed_count >= 0) AND (removed_count <= batch_limit)))
    -- Ràng buộc hiện hành ck_audit_retention_batch_limit: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((batch_limit >= 1) AND (batch_limit <= 1000)))
    batch_limit integer NOT NULL,

    -- Số audit thực đã xóa cùng commit với result, trong0…batch_limit;0 không chứng nhận run drain nếu audit đang bị
    -- transaction khác khóa.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_audit_retention_batch_count: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((removed_count >= 0) AND (removed_count <= batch_limit)))
    removed_count integer NOT NULL,

    -- Thời điểm server ghi batch result đã hoàn tất; row chỉ xuất hiện sau commit DELETE cùng metadata, không dùng làm
    -- cutoff retention của audit.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT statement_timestamp(): giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và
    -- không tự áp lại khi UPDATE.
    completed_at timestamp with time zone DEFAULT statement_timestamp() NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT audit_retention_batches_batch_id_check CHECK ((batch_id <> '00000000-0000-0000-0000-000000000000'::uuid)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_audit_retention_batch_count CHECK (((removed_count >= 0) AND (removed_count <= batch_limit))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_audit_retention_batch_limit CHECK (((batch_limit >= 1) AND (batch_limit <= 1000)))
);


--
-- Name: TABLE audit_retention_batches; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.audit_retention_batches IS 'Kết quả immutable của từng batch audit purge, commit cùng DELETE audit; batch ID là khóa replay để retry không xóa thêm hoặc trả count giả. Không chứa nội dung audit đã xóa.';


--
-- Name: COLUMN audit_retention_batches.batch_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_batches.batch_id IS 'Identity UUID không nil của intent batch, primary key không NULL/không trùng; retry cùng ID phải giữ run và batch limit gốc.';


--
-- Name: COLUMN audit_retention_batches.run_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_batches.run_id IS 'Run/cutoff mà batch tham chiếu bằng khóa ngoại; không cascade xóa result và không sao chép cutoff vào từng batch gây lặp phụ thuộc hàm.';


--
-- Name: COLUMN audit_retention_batches.batch_limit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_batches.batch_limit IS 'Số audit tối đa một transaction được xóa, bắt buộc trong1…1000 để giới hạn lock/runtime; là một phần body identity của batch replay.';


--
-- Name: COLUMN audit_retention_batches.removed_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_batches.removed_count IS 'Số audit thực đã xóa cùng commit với result, trong0…batch_limit;0 không chứng nhận run drain nếu audit đang bị transaction khác khóa.';


--
-- Name: COLUMN audit_retention_batches.completed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_batches.completed_at IS 'Thời điểm server ghi batch result đã hoàn tất; row chỉ xuất hiện sau commit DELETE cùng metadata, không dùng làm cutoff retention của audit.';


--
-- Name: audit_retention_runs; Type: TABLE; Schema: public; Owner: -
--

/* public.audit_retention_runs
 * Run nội bộ của audit retention; mỗi run giữ cutoff UTC đã đóng để restart/retry không làm thay đổi
 * phạm vi xóa. Không chứa audit payload hoặc quyền của user request.
 */
-- Bảng audit_retention_runs: Run nội bộ của audit retention; mỗi run giữ cutoff UTC đã đóng để restart/retry không
-- làm thay đổi phạm vi xóa. Không chứa audit payload hoặc quyền của user request.
CREATE TABLE public.audit_retention_runs (
    -- Identity UUID không nil của một run retention do coordinator cấp; primary key không NULL và không trùng, dùng
    -- giữ cutoff cố định qua restart.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành audit_retention_runs_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (run_id)
    -- Ràng buộc hiện hành audit_retention_runs_run_id_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((run_id <> '00000000-0000-0000-0000-000000000000'::uuid))
    run_id uuid NOT NULL,

    -- Cutoff ingestion UTC đã đóng cho run; mặc định serverNow trừ720 giờ, chỉ audit có created_at nhỏ hơn cutoff mới
    -- đủ điều kiện purge; đúng cutoff vẫn giữ.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT (statement_timestamp() - '720:00:00'::interval): giá trị dùng khi INSERT bỏ qua cột; không thay NULL
    -- được truyền tường minh và không tự áp lại khi UPDATE.
    -- Ràng buộc hiện hành ck_audit_retention_cutoff: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((cutoff <= (statement_timestamp() - '720:00:00'::interval)))
    cutoff timestamp with time zone DEFAULT (statement_timestamp() - '720:00:00'::interval) NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT audit_retention_runs_run_id_check CHECK ((run_id <> '00000000-0000-0000-0000-000000000000'::uuid)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_audit_retention_cutoff CHECK ((cutoff <= (statement_timestamp() - '720:00:00'::interval)))
);


--
-- Name: TABLE audit_retention_runs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.audit_retention_runs IS 'Run nội bộ của audit retention; mỗi run giữ cutoff UTC đã đóng để restart/retry không làm thay đổi phạm vi xóa. Không chứa audit payload hoặc quyền của user request.';


--
-- Name: COLUMN audit_retention_runs.run_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_runs.run_id IS 'Identity UUID không nil của một run retention do coordinator cấp; primary key không NULL và không trùng, dùng giữ cutoff cố định qua restart.';


--
-- Name: COLUMN audit_retention_runs.cutoff; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.audit_retention_runs.cutoff IS 'Cutoff ingestion UTC đã đóng cho run; mặc định serverNow trừ720 giờ, chỉ audit có created_at nhỏ hơn cutoff mới đủ điều kiện purge; đúng cutoff vẫn giữ.';


--
-- Name: command_evidence; Type: TABLE; Schema: public; Owner: -
--

/* public.command_evidence
 * Bằng chứng quan sát muộn hoặc mâu thuẫn của command. Ghi bổ sung vào timeline thay vì sửa terminal
 * outcome hoặc tự phát lại thao tác vật lý.
 */
-- Bảng command_evidence: Bằng chứng quan sát muộn hoặc mâu thuẫn của command. Ghi bổ sung vào timeline thay vì sửa
-- terminal outcome hoặc tự phát lại thao tác vật lý.
CREATE TABLE public.command_evidence (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_evidence_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_evidence_id)
    -- Ràng buộc hiện hành command_evidence_workspace_id_command_id_command_evidence_i_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, command_evidence_id)
    -- Ràng buộc hiện hành command_evidence_workspace_id_command_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, command_id) REFERENCES commands(workspace_id, command_id)
    workspace_id uuid NOT NULL,

    -- Identity một bằng chứng command bổ sung để liên kết resolution và timeline quan sát.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_evidence_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_evidence_id)
    -- Ràng buộc hiện hành command_evidence_workspace_id_command_id_command_evidence_i_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, command_evidence_id)
    command_evidence_id uuid NOT NULL,

    -- Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_evidence_workspace_id_command_id_command_evidence_i_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, command_evidence_id)
    -- Ràng buộc hiện hành command_evidence_workspace_id_command_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, command_id) REFERENCES commands(workspace_id, command_id)
    command_id uuid NOT NULL,

    -- Loại bằng chứng command LATE_RESULT/CONFLICTING_RESULT/DEVICE_OBSERVATION để không nhầm quan sát với terminal
    -- truth.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_evidence_evidence_type_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((evidence_type = ANY (ARRAY['LATE_RESULT'::text, 'CONFLICTING_RESULT'::text,
    -- 'DEVICE_OBSERVATION'::text])))
    evidence_type text NOT NULL,

    -- Thời điểm server nhận gói dữ liệu/kết quả; phân biệt với observed_at do thiết bị hoặc nguồn sự kiện cung cấp.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    received_at timestamp with time zone NOT NULL,

    -- SHA-256 32 byte của payload đã chấp nhận, phục vụ dedupe và phát hiện cùng identity nhưng body mâu thuẫn.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_evidence_payload_digest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(payload_digest) = 32))
    payload_digest bytea NOT NULL,

    -- Payload quan sát đã được producer loại trường nhạy cảm, dùng audit/đối soát; SQL JSON type không tự làm
    -- redaction.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    sanitized_payload jsonb NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT command_evidence_evidence_type_check CHECK ((evidence_type = ANY (ARRAY['LATE_RESULT'::text, 'CONFLICTING_RESULT'::text, 'DEVICE_OBSERVATION'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT command_evidence_payload_digest_check CHECK ((octet_length(payload_digest) = 32))
);


