COMMENT ON COLUMN public.command_resolutions.command_id IS 'Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.';


--
-- Name: COLUMN command_resolutions.resolution_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_resolutions.resolution_status IS 'Tình trạng đối soát UNKNOWN: UNRESOLVED/ACKNOWLEDGED_UNKNOWN/DEVICE_CONFIRMED_LATE, độc lập command outcome.';


--
-- Name: COLUMN command_resolutions.resolved_by_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_resolutions.resolved_by_user_id IS 'Thành viên thực hiện đối soát hoặc xác nhận thủ công; NULL khi chưa có người xử lý theo nhánh resolution.';


--
-- Name: COLUMN command_resolutions.resolved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_resolutions.resolved_at IS 'Mốc ghi nhận resolution ACK/late device proof; không viết lại terminal_at hoặc outcome của command gốc.';


--
-- Name: COLUMN command_resolutions.manual_observation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_resolutions.manual_observation IS 'Quan sát do người dùng khai lúc ACK UNKNOWN; không được ghi đè reported value từ thiết bị hoặc coi là device proof.';


--
-- Name: COLUMN command_resolutions.device_evidence_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_resolutions.device_evidence_id IS 'Bằng chứng thuộc chính command được dùng cho DEVICE_CONFIRMED_LATE; không nhận evidence của command khác.';


--
-- Name: COLUMN command_resolutions.reason_code; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_resolutions.reason_code IS 'Mã nguyên nhân ổn định để giải thích kết quả/transition; phải là nội dung an toàn, không chứa raw lỗi/secret.';


--
-- Name: command_result_receipts; Type: TABLE; Schema: public; Owner: -
--

/* public.command_result_receipts
 * Kết quả MQTT từng phase của command đã được xác minh theo device/boot/credential. Khóa phase và
 * digest phục vụ nhận trùng, không ghi đè kết quả đã chấp nhận.
 */
-- Bảng command_result_receipts: Kết quả MQTT từng phase của command đã được xác minh theo device/boot/credential.
-- Khóa phase và digest phục vụ nhận trùng, không ghi đè kết quả đã chấp nhận.
CREATE TABLE public.command_result_receipts (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_id, result_phase)
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_command_id_device_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, command_id, device_id) REFERENCES commands(workspace_id, command_id, device_id)
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_device_id_boot_id_cre_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, boot_id, credential_generation) REFERENCES
    -- device_boot_sessions(workspace_id, device_id, boot_id, credential_generation)
    workspace_id uuid NOT NULL,

    -- Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_id, result_phase)
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_command_id_device_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, command_id, device_id) REFERENCES commands(workspace_id, command_id, device_id)
    command_id uuid NOT NULL,

    -- Phase result ACCEPTED/SUCCEEDED/FAILED của command; ACCEPTED không phải kết quả vật lý thành công.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_id, result_phase)
    -- Ràng buộc hiện hành command_result_receipts_result_phase_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((result_phase = ANY (ARRAY['ACCEPTED'::text, 'SUCCEEDED'::text, 'FAILED'::text])))
    result_phase text NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_command_id_device_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, command_id, device_id) REFERENCES commands(workspace_id, command_id, device_id)
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_device_id_boot_id_cre_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, boot_id, credential_generation) REFERENCES
    -- device_boot_sessions(workspace_id, device_id, boot_id, credential_generation)
    device_id uuid NOT NULL,

    -- Identity boot của thiết bị theo wire dạng text, không suy UUID; chỉ chấp nhận khi gắn với credential/connection
    -- đã xác minh.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_device_id_boot_id_cre_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, boot_id, credential_generation) REFERENCES
    -- device_boot_sessions(workspace_id, device_id, boot_id, credential_generation)
    boot_id text NOT NULL,

    -- Thế hệ credential MQTT của thiết bị, phân biệt lần cấp mới với credential cũ đã thu hồi.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_workspace_id_device_id_boot_id_cre_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, boot_id, credential_generation) REFERENCES
    -- device_boot_sessions(workspace_id, device_id, boot_id, credential_generation)
    credential_generation bigint NOT NULL,

    -- SHA-256 32 byte của payload đã chấp nhận, phục vụ dedupe và phát hiện cùng identity nhưng body mâu thuẫn.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành command_result_receipts_payload_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(payload_digest) = 32))
    payload_digest bytea NOT NULL,

    -- Thời điểm server nhận gói dữ liệu/kết quả; phân biệt với observed_at do thiết bị hoặc nguồn sự kiện cung cấp.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    received_at timestamp with time zone NOT NULL,

    -- Snapshot result đã xác thực và redact, dùng dedupe/đối soát; không thay quyền hiện hành khi hiển thị.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    result_snapshot jsonb NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT command_result_receipts_payload_digest_check CHECK ((octet_length(payload_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT command_result_receipts_result_phase_check CHECK ((result_phase = ANY (ARRAY['ACCEPTED'::text, 'SUCCEEDED'::text, 'FAILED'::text])))
);


--
-- Name: TABLE command_result_receipts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.command_result_receipts IS 'Kết quả MQTT từng phase của command đã được xác minh theo device/boot/credential. Khóa phase và digest phục vụ nhận trùng, không ghi đè kết quả đã chấp nhận.';


--
-- Name: COLUMN command_result_receipts.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN command_result_receipts.command_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.command_id IS 'Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.';


--
-- Name: COLUMN command_result_receipts.result_phase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.result_phase IS 'Phase result ACCEPTED/SUCCEEDED/FAILED của command; ACCEPTED không phải kết quả vật lý thành công.';


--
-- Name: COLUMN command_result_receipts.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN command_result_receipts.boot_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.boot_id IS 'Identity boot của thiết bị theo wire dạng text, không suy UUID; chỉ chấp nhận khi gắn với credential/connection đã xác minh.';


--
-- Name: COLUMN command_result_receipts.credential_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.credential_generation IS 'Thế hệ credential MQTT của thiết bị, phân biệt lần cấp mới với credential cũ đã thu hồi.';


--
-- Name: COLUMN command_result_receipts.payload_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.payload_digest IS 'SHA-256 32 byte của payload đã chấp nhận, phục vụ dedupe và phát hiện cùng identity nhưng body mâu thuẫn.';


--
-- Name: COLUMN command_result_receipts.received_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.received_at IS 'Thời điểm server nhận gói dữ liệu/kết quả; phân biệt với observed_at do thiết bị hoặc nguồn sự kiện cung cấp.';


--
-- Name: COLUMN command_result_receipts.result_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.command_result_receipts.result_snapshot IS 'Snapshot result đã xác thực và redact, dùng dedupe/đối soát; không thay quyền hiện hành khi hiển thị.';


--
-- Name: commands; Type: TABLE; Schema: public; Owner: -
--

/* public.commands
 * Ledger mỗi lần nhận yêu cầu điều khiển: nguồn lệnh, giá trị đích, deadline và kết quả vật lý. Tách
 * admission/dispatch khỏi terminal outcome; UNKNOWN không được biến thành thành công chỉ vì có ACK thủ
 * công.
 */
-- Bảng commands: Ledger mỗi lần nhận yêu cầu điều khiển: nguồn lệnh, giá trị đích, deadline và kết quả vật lý.
-- Tách admission/dispatch khỏi terminal outcome; UNKNOWN không được biến thành thành công chỉ vì có ACK thủ công.
CREATE TABLE public.commands (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng
    -- cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_id)
    -- Ràng buộc hiện hành commands_workspace_id_action_execution_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, action_execution_id) REFERENCES action_executions(workspace_id, action_execution_id)
    -- Ràng buộc hiện hành commands_workspace_id_actor_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, actor_user_id) REFERENCES memberships(workspace_id, user_id)
    -- Ràng buộc hiện hành commands_workspace_id_command_id_action_execution_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, action_execution_id)
    -- Ràng buộc hiện hành commands_workspace_id_command_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, device_id)
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_command_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, stream_key, command_id)
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, stream_key) REFERENCES actuator_states(workspace_id, device_id,
    -- stream_key)
    -- Ràng buộc hiện hành fk_commands_api_key: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan hệ
    -- trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, api_key_id) REFERENCES api_keys(workspace_id, api_key_id)
    workspace_id uuid NOT NULL,

    -- Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng
    -- cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, command_id)
    -- Ràng buộc hiện hành commands_workspace_id_command_id_action_execution_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, action_execution_id)
    -- Ràng buộc hiện hành commands_workspace_id_command_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, device_id)
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_command_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, stream_key, command_id)
    command_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_workspace_id_command_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, command_id, device_id)
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_command_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, stream_key, command_id)
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, stream_key) REFERENCES actuator_states(workspace_id, device_id,
    -- stream_key)
    device_id uuid NOT NULL,

    -- Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_command_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, stream_key, command_id)
    -- Ràng buộc hiện hành commands_workspace_id_device_id_stream_key_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, stream_key) REFERENCES actuator_states(workspace_id, device_id,
    -- stream_key)
    stream_key text NOT NULL,

    -- Nguồn command MANUAL/AUTOMATION/INTEGRATION, quyết định actor/user, action execution hoặc API key phải có.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_command_origin: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((origin_type = 'MANUAL'::text) AND (actor_user_id IS NOT NULL) AND (api_key_id IS NULL) AND
    -- (action_execution_id IS NULL)) OR ((origin_type = 'AUTOMATION'::text) AND (action_execution_id IS NOT NULL) AND
    -- (actor_user_id IS NULL) AND (api_key_id IS NULL)) OR ((origin_type = 'INTEGRATION'::text) AND (api_key_id IS NOT
    -- NULL) AND (actor_user_id IS NULL) AND (action_execution_id IS NULL))))
    -- Ràng buộc hiện hành commands_origin_type_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((origin_type = ANY (ARRAY['MANUAL'::text, 'AUTOMATION'::text, 'INTEGRATION'::text])))
    origin_type text NOT NULL,

    -- Người phát lệnh MANUAL; phải NULL cho AUTOMATION/INTEGRATION vì hai nguồn đó có principal typed riêng.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_origin: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((origin_type = 'MANUAL'::text) AND (actor_user_id IS NOT NULL) AND (api_key_id IS NULL) AND
    -- (action_execution_id IS NULL)) OR ((origin_type = 'AUTOMATION'::text) AND (action_execution_id IS NOT NULL) AND
    -- (actor_user_id IS NULL) AND (api_key_id IS NULL)) OR ((origin_type = 'INTEGRATION'::text) AND (api_key_id IS NOT
    -- NULL) AND (actor_user_id IS NULL) AND (action_execution_id IS NULL))))
    -- Ràng buộc hiện hành commands_workspace_id_actor_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, actor_user_id) REFERENCES memberships(workspace_id, user_id)
    actor_user_id uuid,

    -- Identity principal API key toàn cục, dùng resolve workspace trước kiểm quyền; không chứa raw key secret.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_origin: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((origin_type = 'MANUAL'::text) AND (actor_user_id IS NOT NULL) AND (api_key_id IS NULL) AND
    -- (action_execution_id IS NULL)) OR ((origin_type = 'AUTOMATION'::text) AND (action_execution_id IS NOT NULL) AND
    -- (actor_user_id IS NULL) AND (api_key_id IS NULL)) OR ((origin_type = 'INTEGRATION'::text) AND (api_key_id IS NOT
    -- NULL) AND (actor_user_id IS NULL) AND (action_execution_id IS NULL))))
    -- Ràng buộc hiện hành fk_commands_api_key: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan hệ
    -- trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm khi có thành phần NULL;
    -- CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, api_key_id) REFERENCES api_keys(workspace_id, api_key_id)
    api_key_id uuid,

    -- Identity ổn định của một action runtime; unique command theo identity này ngăn retry tạo lệnh vật lý thứ hai.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_origin: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((origin_type = 'MANUAL'::text) AND (actor_user_id IS NOT NULL) AND (api_key_id IS NULL) AND
    -- (action_execution_id IS NULL)) OR ((origin_type = 'AUTOMATION'::text) AND (action_execution_id IS NOT NULL) AND
    -- (actor_user_id IS NULL) AND (api_key_id IS NULL)) OR ((origin_type = 'INTEGRATION'::text) AND (api_key_id IS NOT
    -- NULL) AND (actor_user_id IS NULL) AND (action_execution_id IS NULL))))
    -- Ràng buộc hiện hành commands_workspace_id_action_execution_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, action_execution_id) REFERENCES action_executions(workspace_id, action_execution_id)
    -- Ràng buộc hiện hành commands_workspace_id_command_id_action_execution_id_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột. UNIQUE mặc định không coi các giá trị NULL là trùng
    -- nhau.
    -- UNIQUE (workspace_id, command_id, action_execution_id)
    action_execution_id uuid,

    -- Nhánh kiểu dữ liệu của giá trị được lưu; XOR chọn đúng cột numeric/boolean/text và phải khớp pinned definition.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_command_value: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((num_nonnulls(numeric_value, boolean_value, text_value) = 1) AND (((value_type = 'NUMBER'::text) AND
    -- (numeric_value IS NOT NULL)) OR ((value_type = 'BOOLEAN'::text) AND (boolean_value IS NOT NULL)) OR ((value_type
    -- = 'ENUM'::text) AND ((numeric_value IS NOT NULL) OR (text_value IS NOT NULL))))))
    -- Ràng buộc hiện hành commands_value_type_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((value_type = ANY (ARRAY['NUMBER'::text, 'BOOLEAN'::text, 'ENUM'::text])))
    value_type text NOT NULL,

    -- Giá trị số hữu hạn của nhánh NUMBER hoặc ENUM số; NULL khi dùng nhánh giá trị khác hoặc quality NULL.
    -- double precision: số thực dấu phẩy động 64 bit, có sai số biểu diễn; kiểm finite/range theo CHECK và validator.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_value: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((num_nonnulls(numeric_value, boolean_value, text_value) = 1) AND (((value_type = 'NUMBER'::text) AND
    -- (numeric_value IS NOT NULL)) OR ((value_type = 'BOOLEAN'::text) AND (boolean_value IS NOT NULL)) OR ((value_type
    -- = 'ENUM'::text) AND ((numeric_value IS NOT NULL) OR (text_value IS NOT NULL))))))
    -- Ràng buộc hiện hành commands_numeric_value_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((numeric_value IS NULL) OR ((numeric_value > '-Infinity'::double precision) AND (numeric_value <
    -- 'Infinity'::double precision))))
    numeric_value double precision,

    -- Giá trị boolean của nhánh BOOLEAN; false là dữ liệu thật, không tương đương NULL/missing.
    -- boolean: cờ logic true/false; NULL là trạng thái riêng nếu cột cho phép.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_value: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((num_nonnulls(numeric_value, boolean_value, text_value) = 1) AND (((value_type = 'NUMBER'::text) AND
    -- (numeric_value IS NOT NULL)) OR ((value_type = 'BOOLEAN'::text) AND (boolean_value IS NOT NULL)) OR ((value_type
    -- = 'ENUM'::text) AND ((numeric_value IS NOT NULL) OR (text_value IS NOT NULL))))))
    boolean_value boolean,

    -- Giá trị chuỗi của nhánh STRING hoặc ENUM chuỗi; không chuyển mọi datatype thành text để bỏ kiểm kiểu.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_value: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((num_nonnulls(numeric_value, boolean_value, text_value) = 1) AND (((value_type = 'NUMBER'::text) AND
    -- (numeric_value IS NOT NULL)) OR ((value_type = 'BOOLEAN'::text) AND (boolean_value IS NOT NULL)) OR ((value_type
    -- = 'ENUM'::text) AND ((numeric_value IS NOT NULL) OR (text_value IS NOT NULL))))))
    text_value text,

    -- Tiến trình command từ ADMITTED qua dispatch tới terminal; transition được guard, không nhảy thẳng admission
    -- thành success.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'ADMITTED'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự
    -- áp lại khi UPDATE.
    -- Ràng buộc hiện hành ck_command_state_outcome: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((state = ANY (ARRAY['ADMITTED'::text, 'DISPATCHING'::text, 'DISPATCHED'::text, 'ACCEPTED'::text])) AND
    -- (outcome = 'PENDING'::text) AND (terminal_at IS NULL)) OR ((state = 'SUCCEEDED'::text) AND (outcome =
    -- 'SUCCEEDED'::text) AND (terminal_at IS NOT NULL)) OR ((state = ANY (ARRAY['FAILED'::text,
    -- 'EXPIRED_BEFORE_DISPATCH'::text, 'CANCELLED'::text])) AND (outcome = 'FAILED'::text) AND (terminal_at IS NOT
    -- NULL)) OR ((state = 'TIMED_OUT'::text) AND (outcome = 'UNKNOWN'::text) AND (terminal_at IS NOT NULL))))
    -- Ràng buộc hiện hành commands_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['ADMITTED'::text, 'DISPATCHING'::text, 'DISPATCHED'::text, 'ACCEPTED'::text,
    -- 'SUCCEEDED'::text, 'FAILED'::text, 'TIMED_OUT'::text, 'EXPIRED_BEFORE_DISPATCH'::text, 'CANCELLED'::text])))
    state text DEFAULT 'ADMITTED'::text NOT NULL,

    -- Kết quả vật lý PENDING/SUCCEEDED/FAILED/UNKNOWN; TIMED_OUT giữ UNKNOWN kể cả sau ACK thủ công hoặc thêm late
    -- evidence.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'PENDING'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự
    -- áp lại khi UPDATE.
    -- Ràng buộc hiện hành ck_command_state_outcome: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((state = ANY (ARRAY['ADMITTED'::text, 'DISPATCHING'::text, 'DISPATCHED'::text, 'ACCEPTED'::text])) AND
    -- (outcome = 'PENDING'::text) AND (terminal_at IS NULL)) OR ((state = 'SUCCEEDED'::text) AND (outcome =
    -- 'SUCCEEDED'::text) AND (terminal_at IS NOT NULL)) OR ((state = ANY (ARRAY['FAILED'::text,
    -- 'EXPIRED_BEFORE_DISPATCH'::text, 'CANCELLED'::text])) AND (outcome = 'FAILED'::text) AND (terminal_at IS NOT
    -- NULL)) OR ((state = 'TIMED_OUT'::text) AND (outcome = 'UNKNOWN'::text) AND (terminal_at IS NOT NULL))))
    -- Ràng buộc hiện hành commands_outcome_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((outcome = ANY (ARRAY['PENDING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'UNKNOWN'::text])))
    outcome text DEFAULT 'PENDING'::text NOT NULL,

    -- Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((deadline_at = (admitted_at + '00:00:10'::interval)))
    admitted_at timestamp with time zone NOT NULL,

    -- Deadline cố định admitted_at + 10 giây; command đã có khả năng dispatch mà hết hạn không được blind retry.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((deadline_at = (admitted_at + '00:00:10'::interval)))
    deadline_at timestamp with time zone NOT NULL,

    -- Thời điểm lưu ý định dispatch command trước network; dùng phân biệt chưa gửi với đã có khả năng tác động vật lý.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    dispatch_intent_at timestamp with time zone,

    -- Thời điểm quan sát trạng thái kết thúc của command/delivery; không thay gốc expiry hoặc gốc retention.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_command_state_outcome: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((state = ANY (ARRAY['ADMITTED'::text, 'DISPATCHING'::text, 'DISPATCHED'::text, 'ACCEPTED'::text])) AND
    -- (outcome = 'PENDING'::text) AND (terminal_at IS NULL)) OR ((state = 'SUCCEEDED'::text) AND (outcome =
    -- 'SUCCEEDED'::text) AND (terminal_at IS NOT NULL)) OR ((state = ANY (ARRAY['FAILED'::text,
    -- 'EXPIRED_BEFORE_DISPATCH'::text, 'CANCELLED'::text])) AND (outcome = 'FAILED'::text) AND (terminal_at IS NOT
    -- NULL)) OR ((state = 'TIMED_OUT'::text) AND (outcome = 'UNKNOWN'::text) AND (terminal_at IS NOT NULL))))
    terminal_at timestamp with time zone,

    -- Manual epoch chụp khi command admission, để kiểm command/automation không dựa vào quyền điều khiển đã lỗi thời.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành commands_manual_epoch_snapshot_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((manual_epoch_snapshot >= 0))
    manual_epoch_snapshot bigint NOT NULL,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành commands_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_command_origin CHECK ((((origin_type = 'MANUAL'::text) AND (actor_user_id IS NOT NULL) AND (api_key_id IS NULL) AND (action_execution_id IS NULL)) OR ((origin_type = 'AUTOMATION'::text) AND (action_execution_id IS NOT NULL) AND (actor_user_id IS NULL) AND (api_key_id IS NULL)) OR ((origin_type = 'INTEGRATION'::text) AND (api_key_id IS NOT NULL) AND (actor_user_id IS NULL) AND (action_execution_id IS NULL)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_command_state_outcome CHECK ((((state = ANY (ARRAY['ADMITTED'::text, 'DISPATCHING'::text, 'DISPATCHED'::text, 'ACCEPTED'::text])) AND (outcome = 'PENDING'::text) AND (terminal_at IS NULL)) OR ((state = 'SUCCEEDED'::text) AND (outcome = 'SUCCEEDED'::text) AND (terminal_at IS NOT NULL)) OR ((state = ANY (ARRAY['FAILED'::text, 'EXPIRED_BEFORE_DISPATCH'::text, 'CANCELLED'::text])) AND (outcome = 'FAILED'::text) AND (terminal_at IS NOT NULL)) OR ((state = 'TIMED_OUT'::text) AND (outcome = 'UNKNOWN'::text) AND (terminal_at IS NOT NULL)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_command_value CHECK (((num_nonnulls(numeric_value, boolean_value, text_value) = 1) AND (((value_type = 'NUMBER'::text) AND (numeric_value IS NOT NULL)) OR ((value_type = 'BOOLEAN'::text) AND (boolean_value IS NOT NULL)) OR ((value_type = 'ENUM'::text) AND ((numeric_value IS NOT NULL) OR (text_value IS NOT NULL)))))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_check CHECK ((deadline_at = (admitted_at + '00:00:10'::interval))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_manual_epoch_snapshot_check CHECK ((manual_epoch_snapshot >= 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_numeric_value_check CHECK (((numeric_value IS NULL) OR ((numeric_value > '-Infinity'::double precision) AND (numeric_value < 'Infinity'::double precision)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_origin_type_check CHECK ((origin_type = ANY (ARRAY['MANUAL'::text, 'AUTOMATION'::text, 'INTEGRATION'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_outcome_check CHECK ((outcome = ANY (ARRAY['PENDING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'UNKNOWN'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_revision_check CHECK ((revision > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_state_check CHECK ((state = ANY (ARRAY['ADMITTED'::text, 'DISPATCHING'::text, 'DISPATCHED'::text, 'ACCEPTED'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'TIMED_OUT'::text, 'EXPIRED_BEFORE_DISPATCH'::text, 'CANCELLED'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT commands_value_type_check CHECK ((value_type = ANY (ARRAY['NUMBER'::text, 'BOOLEAN'::text, 'ENUM'::text])))
);


--
-- Name: TABLE commands; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.commands IS 'Ledger mỗi lần nhận yêu cầu điều khiển: nguồn lệnh, giá trị đích, deadline và kết quả vật lý. Tách admission/dispatch khỏi terminal outcome; UNKNOWN không được biến thành thành công chỉ vì có ACK thủ công.';


--
-- Name: COLUMN commands.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN commands.command_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.command_id IS 'Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.';


--
-- Name: COLUMN commands.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN commands.stream_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.stream_key IS 'Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.';


--
-- Name: COLUMN commands.origin_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.origin_type IS 'Nguồn command MANUAL/AUTOMATION/INTEGRATION, quyết định actor/user, action execution hoặc API key phải có.';


--
-- Name: COLUMN commands.actor_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.actor_user_id IS 'Người phát lệnh MANUAL; phải NULL cho AUTOMATION/INTEGRATION vì hai nguồn đó có principal typed riêng.';


--
-- Name: COLUMN commands.api_key_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.api_key_id IS 'Identity principal API key toàn cục, dùng resolve workspace trước kiểm quyền; không chứa raw key secret.';


--
-- Name: COLUMN commands.action_execution_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.action_execution_id IS 'Identity ổn định của một action runtime; unique command theo identity này ngăn retry tạo lệnh vật lý thứ hai.';


--
-- Name: COLUMN commands.value_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.value_type IS 'Nhánh kiểu dữ liệu của giá trị được lưu; XOR chọn đúng cột numeric/boolean/text và phải khớp pinned definition.';


--
-- Name: COLUMN commands.numeric_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.numeric_value IS 'Giá trị số hữu hạn của nhánh NUMBER hoặc ENUM số; NULL khi dùng nhánh giá trị khác hoặc quality NULL.';


--
-- Name: COLUMN commands.boolean_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.boolean_value IS 'Giá trị boolean của nhánh BOOLEAN; false là dữ liệu thật, không tương đương NULL/missing.';


--
-- Name: COLUMN commands.text_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.text_value IS 'Giá trị chuỗi của nhánh STRING hoặc ENUM chuỗi; không chuyển mọi datatype thành text để bỏ kiểm kiểu.';


--
-- Name: COLUMN commands.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.state IS 'Tiến trình command từ ADMITTED qua dispatch tới terminal; transition được guard, không nhảy thẳng admission thành success.';


--
-- Name: COLUMN commands.outcome; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.outcome IS 'Kết quả vật lý PENDING/SUCCEEDED/FAILED/UNKNOWN; TIMED_OUT giữ UNKNOWN kể cả sau ACK thủ công hoặc thêm late evidence.';


--
-- Name: COLUMN commands.admitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.admitted_at IS 'Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.';


--
-- Name: COLUMN commands.deadline_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.deadline_at IS 'Deadline cố định admitted_at + 10 giây; command đã có khả năng dispatch mà hết hạn không được blind retry.';


--
-- Name: COLUMN commands.dispatch_intent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.dispatch_intent_at IS 'Thời điểm lưu ý định dispatch command trước network; dùng phân biệt chưa gửi với đã có khả năng tác động vật lý.';


--
-- Name: COLUMN commands.terminal_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.terminal_at IS 'Thời điểm quan sát trạng thái kết thúc của command/delivery; không thay gốc expiry hoặc gốc retention.';


--
-- Name: COLUMN commands.manual_epoch_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.manual_epoch_snapshot IS 'Manual epoch chụp khi command admission, để kiểm command/automation không dựa vào quyền điều khiển đã lỗi thời.';


--
-- Name: COLUMN commands.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.commands.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: connectivity_transitions; Type: TABLE; Schema: public; Owner: -
--

/* public.connectivity_transitions
 * Nhật ký từng chuyển trạng thái kết nối thực sự của thiết bị. Sequence ổn định giúp rule và webhook
 * chống tạo sự kiện trùng từ heartbeat hoặc hello lặp.
 */
-- Bảng connectivity_transitions: Nhật ký từng chuyển trạng thái kết nối thực sự của thiết bị. Sequence ổn định
-- giúp rule và webhook chống tạo sự kiện trùng từ heartbeat hoặc hello lặp.
CREATE TABLE public.connectivity_transitions (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành connectivity_transitions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id, transition_sequence)
    -- Ràng buộc hiện hành connectivity_transitions_workspace_id_device_id_boot_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, boot_id) REFERENCES device_boot_sessions(workspace_id, device_id, boot_id)
    -- Ràng buộc hiện hành connectivity_transitions_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    workspace_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành connectivity_transitions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id, transition_sequence)
    -- Ràng buộc hiện hành connectivity_transitions_workspace_id_device_id_boot_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, boot_id) REFERENCES device_boot_sessions(workspace_id, device_id, boot_id)
    -- Ràng buộc hiện hành connectivity_transitions_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    device_id uuid NOT NULL,

    -- Số thứ tự chuyển presence thực sự của thiết bị, bắt đầu lớn hơn 0; heartbeat trùng không tạo transition mới.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành connectivity_transitions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id, transition_sequence)
    -- Ràng buộc hiện hành connectivity_transitions_transition_sequence_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((transition_sequence > 0))
    transition_sequence bigint NOT NULL,

    -- Thế hệ kết nối đã xác minh của device, dùng loại sự kiện/reply từ kết nối cũ.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành connectivity_transitions_connection_generation_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((connection_generation > 0))
    connection_generation bigint NOT NULL,

    -- Trạng thái presence trước chuyển đổi, dùng đối chiếu edge thực tế và giải thích trigger connectivity.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành connectivity_transitions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((from_state <> to_state))
    -- Ràng buộc hiện hành connectivity_transitions_from_state_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((from_state = ANY (ARRAY['ONLINE'::text, 'OFFLINE'::text])))
    from_state text NOT NULL,

    -- Trạng thái presence sau chuyển đổi, phải khác from_state; không tự thay lifecycle ACTIVE/SUSPENDED.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành connectivity_transitions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((from_state <> to_state))
    -- Ràng buộc hiện hành connectivity_transitions_to_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((to_state = ANY (ARRAY['ONLINE'::text, 'OFFLINE'::text])))
    to_state text NOT NULL,

    -- Thời điểm quan sát được dữ liệu/kết quả; nguồn và ý nghĩa được quy định theo bảng, không mặc định là thời gian
    -- commit.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    observed_at timestamp with time zone NOT NULL,

    -- Identity boot của thiết bị theo wire dạng text, không suy UUID; chỉ chấp nhận khi gắn với credential/connection
    -- đã xác minh.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành connectivity_transitions_workspace_id_device_id_boot_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, device_id, boot_id) REFERENCES device_boot_sessions(workspace_id, device_id, boot_id)
    boot_id text,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT connectivity_transitions_check CHECK ((from_state <> to_state)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT connectivity_transitions_connection_generation_check CHECK ((connection_generation > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT connectivity_transitions_from_state_check CHECK ((from_state = ANY (ARRAY['ONLINE'::text, 'OFFLINE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT connectivity_transitions_to_state_check CHECK ((to_state = ANY (ARRAY['ONLINE'::text, 'OFFLINE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT connectivity_transitions_transition_sequence_check CHECK ((transition_sequence > 0))
);


--
-- Name: TABLE connectivity_transitions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.connectivity_transitions IS 'Nhật ký từng chuyển trạng thái kết nối thực sự của thiết bị. Sequence ổn định giúp rule và webhook chống tạo sự kiện trùng từ heartbeat hoặc hello lặp.';


--
-- Name: COLUMN connectivity_transitions.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN connectivity_transitions.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN connectivity_transitions.transition_sequence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.transition_sequence IS 'Số thứ tự chuyển presence thực sự của thiết bị, bắt đầu lớn hơn 0; heartbeat trùng không tạo transition mới.';


--
-- Name: COLUMN connectivity_transitions.connection_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.connection_generation IS 'Thế hệ kết nối đã xác minh của device, dùng loại sự kiện/reply từ kết nối cũ.';


--
-- Name: COLUMN connectivity_transitions.from_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.from_state IS 'Trạng thái presence trước chuyển đổi, dùng đối chiếu edge thực tế và giải thích trigger connectivity.';


--
-- Name: COLUMN connectivity_transitions.to_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.to_state IS 'Trạng thái presence sau chuyển đổi, phải khác from_state; không tự thay lifecycle ACTIVE/SUSPENDED.';


--
-- Name: COLUMN connectivity_transitions.observed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.observed_at IS 'Thời điểm quan sát được dữ liệu/kết quả; nguồn và ý nghĩa được quy định theo bảng, không mặc định là thời gian commit.';


--
-- Name: COLUMN connectivity_transitions.boot_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.connectivity_transitions.boot_id IS 'Identity boot của thiết bị theo wire dạng text, không suy UUID; chỉ chấp nhận khi gắn với credential/connection đã xác minh.';


--
-- Name: dashboard_widget_bindings; Type: TABLE; Schema: public; Owner: -
--

/* public.dashboard_widget_bindings
 * Liên kết từng slot widget với thiết bị và kênh đã pin. Presence binding có thể không có stream; FK
 * và shape bảo vệ tham chiếu trong đúng workspace/version.
 */
-- Bảng dashboard_widget_bindings: Liên kết từng slot widget với thiết bị và kênh đã pin. Presence binding có thể
-- không có stream; FK và shape bảo vệ tham chiếu trong đúng workspace/version.
CREATE TABLE public.dashboard_widget_bindings (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widget_bindings_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id, binding_slot)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_dashboard_id_widget_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, dashboard_id, widget_id) REFERENCES dashboard_widgets(workspace_id, dashboard_id,
    -- widget_id)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_device_id_template__fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, template_version_id) REFERENCES devices(workspace_id, device_id,
    -- template_version_id)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_template_version_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_version_id, stream_key) REFERENCES datastream_definitions(workspace_id,
    -- template_version_id, stream_key)
    workspace_id uuid NOT NULL,

    -- Identity dashboard trong workspace, dùng nhóm widget và kiểm owner/revision khi lưu cấu hình.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widget_bindings_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id, binding_slot)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_dashboard_id_widget_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, dashboard_id, widget_id) REFERENCES dashboard_widgets(workspace_id, dashboard_id,
    -- widget_id)
    dashboard_id uuid NOT NULL,

    -- Identity widget trong dashboard, giữ binding đúng thành phần dù thay layout hoặc thứ tự mobile.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widget_bindings_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id, binding_slot)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_dashboard_id_widget_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, dashboard_id, widget_id) REFERENCES dashboard_widgets(workspace_id, dashboard_id,
    -- widget_id)
    widget_id uuid NOT NULL,

    -- Tên slot dữ liệu/điều khiển của widget, để một widget có thể liên kết từng nhu cầu với resource đúng scope.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widget_bindings_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id, binding_slot)
    binding_slot text NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_device_id_template__fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, template_version_id) REFERENCES devices(workspace_id, device_id,
    -- template_version_id)
    device_id uuid NOT NULL,

    -- Pin version cho stream binding; cùng NULL với stream_key khi binding là presence của device.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành dashboard_widget_bindings_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((template_version_id IS NULL) = (stream_key IS NULL)))
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_device_id_template__fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, device_id, template_version_id) REFERENCES devices(workspace_id, device_id,
    -- template_version_id)
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_template_version_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, template_version_id, stream_key) REFERENCES datastream_definitions(workspace_id,
    -- template_version_id, stream_key)
    template_version_id uuid,

    -- Kênh pinned của stream binding; cùng NULL với template_version_id khi slot dùng presence, device_id vẫn bắt
    -- buộc.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành dashboard_widget_bindings_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((template_version_id IS NULL) = (stream_key IS NULL)))
    -- Ràng buộc hiện hành dashboard_widget_bindings_workspace_id_template_version_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, template_version_id, stream_key) REFERENCES datastream_definitions(workspace_id,
    -- template_version_id, stream_key)
    stream_key text,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widget_bindings_check CHECK (((template_version_id IS NULL) = (stream_key IS NULL)))
);


--
-- Name: TABLE dashboard_widget_bindings; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.dashboard_widget_bindings IS 'Liên kết từng slot widget với thiết bị và kênh đã pin. Presence binding có thể không có stream; FK và shape bảo vệ tham chiếu trong đúng workspace/version.';


--
-- Name: COLUMN dashboard_widget_bindings.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN dashboard_widget_bindings.dashboard_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.dashboard_id IS 'Identity dashboard trong workspace, dùng nhóm widget và kiểm owner/revision khi lưu cấu hình.';


--
-- Name: COLUMN dashboard_widget_bindings.widget_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.widget_id IS 'Identity widget trong dashboard, giữ binding đúng thành phần dù thay layout hoặc thứ tự mobile.';


--
-- Name: COLUMN dashboard_widget_bindings.binding_slot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.binding_slot IS 'Tên slot dữ liệu/điều khiển của widget, để một widget có thể liên kết từng nhu cầu với resource đúng scope.';


--
-- Name: COLUMN dashboard_widget_bindings.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN dashboard_widget_bindings.template_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.template_version_id IS 'Pin version cho stream binding; cùng NULL với stream_key khi binding là presence của device.';


--
-- Name: COLUMN dashboard_widget_bindings.stream_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.dashboard_widget_bindings.stream_key IS 'Kênh pinned của stream binding; cùng NULL với template_version_id khi slot dùng presence, device_id vẫn bắt buộc.';


--
-- Name: dashboard_widgets; Type: TABLE; Schema: public; Owner: -
--

/* public.dashboard_widgets
 * Từng widget trong dashboard: loại hiển thị/điều khiển, thứ tự trên mobile và bố cục grid.
 * Presentation giữ cấu hình của loại widget, không là nơi lưu credential hoặc script tùy ý.
 */
-- Bảng dashboard_widgets: Từng widget trong dashboard: loại hiển thị/điều khiển, thứ tự trên mobile và bố cục
-- grid. Presentation giữ cấu hình của loại widget, không là nơi lưu credential hoặc script tùy ý.
CREATE TABLE public.dashboard_widgets (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id)
    -- Ràng buộc hiện hành dashboard_widgets_workspace_id_dashboard_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, dashboard_id) REFERENCES dashboards(workspace_id, dashboard_id)
    -- Ràng buộc hiện hành dashboard_widgets_workspace_id_dashboard_id_position_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, dashboard_id, "position")
    workspace_id uuid NOT NULL,

    -- Identity dashboard trong workspace, dùng nhóm widget và kiểm owner/revision khi lưu cấu hình.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id)
    -- Ràng buộc hiện hành dashboard_widgets_workspace_id_dashboard_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, dashboard_id) REFERENCES dashboards(workspace_id, dashboard_id)
    -- Ràng buộc hiện hành dashboard_widgets_workspace_id_dashboard_id_position_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, dashboard_id, "position")
    dashboard_id uuid NOT NULL,

    -- Identity widget trong dashboard, giữ binding đúng thành phần dù thay layout hoặc thứ tự mobile.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, dashboard_id, widget_id)
    widget_id uuid NOT NULL,

    -- Loại widget VALUE/GAUGE/STATUS/SWITCH/BUTTON/CHART; backend còn phải kiểm tương thích datatype/capability và
    -- config.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_widget_type_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((widget_type = ANY (ARRAY['VALUE'::text, 'GAUGE'::text, 'STATUS'::text, 'SWITCH'::text, 'BUTTON'::text,
    -- 'CHART'::text])))
    widget_type text NOT NULL,

    -- Thứ tự widget trên mobile, từ 0 đến 19 và duy nhất trong dashboard; khác tọa độ layout grid Web.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_position_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((("position" >= 0) AND ("position" <= 19)))
    -- Ràng buộc hiện hành dashboard_widgets_workspace_id_dashboard_id_position_key: không trùng tổ hợp giá trị được
    -- nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, dashboard_id, "position")
    "position" integer NOT NULL,

    -- Cấu hình hiển thị theo loại widget dưới dạng JSON object; không phải nơi lưu resource authority, secret hoặc
    -- script tùy ý.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT '{}'::jsonb: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp
    -- lại khi UPDATE.
    -- Ràng buộc hiện hành dashboard_widgets_presentation_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((jsonb_typeof(presentation) = 'object'::text))
    presentation jsonb DEFAULT '{}'::jsonb NOT NULL,

    -- Tọa độ cột bắt đầu trong grid Web 12 cột, từ 0 đến 11; phải cộng width không vượt 12.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((layout_x + layout_width) <= 12))
    -- Ràng buộc hiện hành dashboard_widgets_layout_x_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((layout_x >= 0) AND (layout_x <= 11)))
    layout_x integer NOT NULL,

    -- Tọa độ hàng bắt đầu của widget trong grid Web, không âm; khác mobile order.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_layout_y_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((layout_y >= 0))
    layout_y integer NOT NULL,

    -- Số cột grid mà widget chiếm, lớn hơn 0; tổng với layout_x phải nằm trong 12 cột.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((layout_x + layout_width) <= 12))
    -- Ràng buộc hiện hành dashboard_widgets_layout_width_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((layout_width > 0))
    layout_width integer NOT NULL,

    -- Số đơn vị hàng grid mà widget chiếm, lớn hơn 0; không phải pixel hoặc số mẫu lịch sử.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành dashboard_widgets_layout_height_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((layout_height > 0))
    layout_height integer NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_check CHECK (((layout_x + layout_width) <= 12)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_layout_height_check CHECK ((layout_height > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_layout_width_check CHECK ((layout_width > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_layout_x_check CHECK (((layout_x >= 0) AND (layout_x <= 11))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_layout_y_check CHECK ((layout_y >= 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_position_check CHECK ((("position" >= 0) AND ("position" <= 19))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_presentation_check CHECK ((jsonb_typeof(presentation) = 'object'::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT dashboard_widgets_widget_type_check CHECK ((widget_type = ANY (ARRAY['VALUE'::text, 'GAUGE'::text, 'STATUS'::text, 'SWITCH'::text, 'BUTTON'::text, 'CHART'::text])))
);


