--
-- Name: device_credentials; Type: TABLE; Schema: public; Owner: -
--

/* public.device_credentials
 * Các generation credential MQTT của thiết bị và trạng thái cấp/thu hồi. Chỉ lưu bộ kiểm chứng, không
 * giữ raw credential để đọc lại.
 */
-- Bảng device_credentials: Các generation credential MQTT của thiết bị và trạng thái cấp/thu hồi. Chỉ lưu bộ kiểm
-- chứng, không giữ raw credential để đọc lại.
CREATE TABLE public.device_credentials (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_credentials_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id, credential_generation)
    -- Ràng buộc hiện hành device_credentials_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    workspace_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_credentials_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id, credential_generation)
    -- Ràng buộc hiện hành device_credentials_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    device_id uuid NOT NULL,

    -- Thế hệ credential MQTT của thiết bị, phân biệt lần cấp mới với credential cũ đã thu hồi.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_credentials_credential_generation_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((credential_generation > 0))
    -- Ràng buộc hiện hành device_credentials_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id, credential_generation)
    credential_generation bigint NOT NULL,

    -- Định danh credential/client phía broker, duy nhất toàn cục; không phải raw password MQTT.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_credentials_credential_identifier_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (credential_identifier)
    credential_identifier text NOT NULL,

    -- Bộ kiểm chứng mật 32 byte dùng xác thực credential/API key theo protected-verifier contract; không là raw secret
    -- và không trả client/log.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_credentials_verifier_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(verifier_digest) = 32))
    verifier_digest bytea NOT NULL,

    -- Tiến trình credential PROVISIONING/ACTIVE/REVOCATION_PENDING/REVOKED; chỉ báo đã revoke khi có xác nhận phù hợp.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_device_credential_state: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((credential_state = ANY (ARRAY['PROVISIONING'::text, 'ACTIVE'::text, 'REVOCATION_PENDING'::text,
    -- 'REVOKED'::text])))
    credential_state text NOT NULL,

    -- Thời điểm phát hành phiên/grant/credential/ticket, làm gốc tính TTL theo loại bản ghi.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    issued_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Thời điểm thu hồi quyền/credential; NULL nghĩa chưa ghi nhận thu hồi, không đồng nghĩa mọi điều kiện xác thực
    -- khác còn hợp lệ.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    revoked_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_device_credential_state CHECK ((credential_state = ANY (ARRAY['PROVISIONING'::text, 'ACTIVE'::text, 'REVOCATION_PENDING'::text, 'REVOKED'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT device_credentials_credential_generation_check CHECK ((credential_generation > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT device_credentials_verifier_digest_check CHECK ((octet_length(verifier_digest) = 32))
);


--
-- Name: TABLE device_credentials; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.device_credentials IS 'Các generation credential MQTT của thiết bị và trạng thái cấp/thu hồi. Chỉ lưu bộ kiểm chứng, không giữ raw credential để đọc lại.';


--
-- Name: COLUMN device_credentials.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN device_credentials.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN device_credentials.credential_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.credential_generation IS 'Thế hệ credential MQTT của thiết bị, phân biệt lần cấp mới với credential cũ đã thu hồi.';


--
-- Name: COLUMN device_credentials.credential_identifier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.credential_identifier IS 'Định danh credential/client phía broker, duy nhất toàn cục; không phải raw password MQTT.';


--
-- Name: COLUMN device_credentials.verifier_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.verifier_digest IS 'Bộ kiểm chứng mật 32 byte dùng xác thực credential/API key theo protected-verifier contract; không là raw secret và không trả client/log.';


--
-- Name: COLUMN device_credentials.credential_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.credential_state IS 'Tiến trình credential PROVISIONING/ACTIVE/REVOCATION_PENDING/REVOKED; chỉ báo đã revoke khi có xác nhận phù hợp.';


--
-- Name: COLUMN device_credentials.issued_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.issued_at IS 'Thời điểm phát hành phiên/grant/credential/ticket, làm gốc tính TTL theo loại bản ghi.';


--
-- Name: COLUMN device_credentials.revoked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_credentials.revoked_at IS 'Thời điểm thu hồi quyền/credential; NULL nghĩa chưa ghi nhận thu hồi, không đồng nghĩa mọi điều kiện xác thực khác còn hợp lệ.';


--
-- Name: device_enrollment_guards; Type: TABLE; Schema: public; Owner: -
--

/* public.device_enrollment_guards
 * Khóa nghiệp vụ giữ một thiết bị cho enrollment đang chưa giải quyết. Guard chỉ được nhả khi hoàn tất
 * hoặc cleanup có proof, không chỉ vì session đã hết hạn.
 */
-- Bảng device_enrollment_guards: Khóa nghiệp vụ giữ một thiết bị cho enrollment đang chưa giải quyết. Guard chỉ
-- được nhả khi hoàn tất hoặc cleanup có proof, không chỉ vì session đã hết hạn.
CREATE TABLE public.device_enrollment_guards (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_enrollment_guards_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id)
    -- Ràng buộc hiện hành device_enrollment_guards_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành device_enrollment_guards_workspace_id_enrollment_session_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, enrollment_session_id, device_id) REFERENCES enrollment_sessions(workspace_id,
    -- enrollment_session_id, device_id)
    workspace_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_enrollment_guards_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id)
    -- Ràng buộc hiện hành device_enrollment_guards_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành device_enrollment_guards_workspace_id_enrollment_session_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, enrollment_session_id, device_id) REFERENCES enrollment_sessions(workspace_id,
    -- enrollment_session_id, device_id)
    device_id uuid NOT NULL,

    -- Identity ý định onboarding/đổi Wi-Fi, dùng polling, proof binding và liên kết cleanup/guard.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_enrollment_guards_workspace_id_enrollment_session_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, enrollment_session_id, device_id) REFERENCES enrollment_sessions(workspace_id,
    -- enrollment_session_id, device_id)
    enrollment_session_id uuid NOT NULL,

    -- Thời điểm device enrollment guard được giữ, giúp chẩn đoán thời gian chiếm thiết bị khi session đã hết hạn.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    acquired_at timestamp with time zone NOT NULL
);


--
-- Name: TABLE device_enrollment_guards; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.device_enrollment_guards IS 'Khóa nghiệp vụ giữ một thiết bị cho enrollment đang chưa giải quyết. Guard chỉ được nhả khi hoàn tất hoặc cleanup có proof, không chỉ vì session đã hết hạn.';


