--
-- Name: device_runtime; Type: TABLE; Schema: public; Owner: -
--

/* public.device_runtime
 * Trạng thái vận hành thay đổi thường xuyên của thiết bị: presence, boot hiện hành, bộ đếm ingest và
 * epoch bảo trì. Tách khỏi metadata để telemetry không làm tăng revision chỉnh sửa thiết bị.
 */
-- Bảng device_runtime: Trạng thái vận hành thay đổi thường xuyên của thiết bị: presence, boot hiện hành, bộ đếm
-- ingest và epoch bảo trì. Tách khỏi metadata để telemetry không làm tăng revision chỉnh sửa thiết bị.
CREATE TABLE public.device_runtime (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_runtime_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id)
    -- Ràng buộc hiện hành device_runtime_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành fk_device_runtime_boot: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan hệ
    -- trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, current_boot_id) REFERENCES device_boot_sessions(workspace_id, device_id,
    -- boot_id)
    workspace_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành device_runtime_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, device_id)
    -- Ràng buộc hiện hành device_runtime_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành fk_device_runtime_boot: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan hệ
    -- trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, current_boot_id) REFERENCES device_boot_sessions(workspace_id, device_id,
    -- boot_id)
    device_id uuid NOT NULL,

    -- Bộ đếm server đã tiếp nhận cho device, ban đầu 0; tăng theo ingest commit, không lấy wire seq thay thế.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 0: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành device_runtime_ingestion_sequence_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((ingestion_sequence >= 0))
    ingestion_sequence bigint DEFAULT 0 NOT NULL,

    -- Thế hệ kết nối đã xác minh của device, dùng loại sự kiện/reply từ kết nối cũ.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 0: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành device_runtime_connection_generation_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((connection_generation >= 0))
    connection_generation bigint DEFAULT 0 NOT NULL,

    -- Thế hệ khóa bảo trì, dùng phân biệt OTA/dispatch đang hiện hành với callback cũ; không reset do reconnect.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 0: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành device_runtime_maintenance_epoch_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((maintenance_epoch >= 0))
    maintenance_epoch bigint DEFAULT 0 NOT NULL,

    -- Chế độ vận hành NONE/OTA của thiết bị, dùng chặn command/automation khi đang bảo trì.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'NONE'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp
    -- lại khi UPDATE.
    -- Ràng buộc hiện hành device_runtime_maintenance_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((maintenance = ANY (ARRAY['NONE'::text, 'OTA'::text])))
    maintenance text DEFAULT 'NONE'::text NOT NULL,

    -- Thời điểm hoạt động hợp lệ gần nhất từ thiết bị, dùng phát hiện mất kết nối theo policy presence.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    last_seen_at timestamp with time zone,

    -- Trạng thái kết nối UNKNOWN/ONLINE/OFFLINE, độc lập với lifecycle và maintenance của thiết bị.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'UNKNOWN'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự
    -- áp lại khi UPDATE.
    -- Ràng buộc hiện hành ck_device_presence: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((presence_state = ANY (ARRAY['UNKNOWN'::text, 'ONLINE'::text, 'OFFLINE'::text])))
    presence_state text DEFAULT 'UNKNOWN'::text NOT NULL,

    -- Boot đang hiện hành của thiết bị; NULL khi chưa có boot đáng tin cậy, không hồi sinh boot cũ từ hello trùng.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành fk_device_runtime_boot: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan hệ
    -- trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm khi có thành phần NULL;
    -- CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, device_id, current_boot_id) REFERENCES device_boot_sessions(workspace_id, device_id,
    -- boot_id)
    current_boot_id text,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_device_presence CHECK ((presence_state = ANY (ARRAY['UNKNOWN'::text, 'ONLINE'::text, 'OFFLINE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT device_runtime_connection_generation_check CHECK ((connection_generation >= 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT device_runtime_ingestion_sequence_check CHECK ((ingestion_sequence >= 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT device_runtime_maintenance_check CHECK ((maintenance = ANY (ARRAY['NONE'::text, 'OTA'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT device_runtime_maintenance_epoch_check CHECK ((maintenance_epoch >= 0))
);


--
-- Name: TABLE device_runtime; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.device_runtime IS 'Trạng thái vận hành thay đổi thường xuyên của thiết bị: presence, boot hiện hành, bộ đếm ingest và epoch bảo trì. Tách khỏi metadata để telemetry không làm tăng revision chỉnh sửa thiết bị.';


--
-- Name: COLUMN device_runtime.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN device_runtime.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN device_runtime.ingestion_sequence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.ingestion_sequence IS 'Bộ đếm server đã tiếp nhận cho device, ban đầu 0; tăng theo ingest commit, không lấy wire seq thay thế.';


--
-- Name: COLUMN device_runtime.connection_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.connection_generation IS 'Thế hệ kết nối đã xác minh của device, dùng loại sự kiện/reply từ kết nối cũ.';


--
-- Name: COLUMN device_runtime.maintenance_epoch; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.maintenance_epoch IS 'Thế hệ khóa bảo trì, dùng phân biệt OTA/dispatch đang hiện hành với callback cũ; không reset do reconnect.';


--
-- Name: COLUMN device_runtime.maintenance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.maintenance IS 'Chế độ vận hành NONE/OTA của thiết bị, dùng chặn command/automation khi đang bảo trì.';


--
-- Name: COLUMN device_runtime.last_seen_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.last_seen_at IS 'Thời điểm hoạt động hợp lệ gần nhất từ thiết bị, dùng phát hiện mất kết nối theo policy presence.';


--
-- Name: COLUMN device_runtime.presence_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.presence_state IS 'Trạng thái kết nối UNKNOWN/ONLINE/OFFLINE, độc lập với lifecycle và maintenance của thiết bị.';


--
-- Name: COLUMN device_runtime.current_boot_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.device_runtime.current_boot_id IS 'Boot đang hiện hành của thiết bị; NULL khi chưa có boot đáng tin cậy, không hồi sinh boot cũ từ hello trùng.';


--
-- Name: devices; Type: TABLE; Schema: public; Owner: -
--

/* public.devices
 * Registry thiết bị: identity MQTT toàn cục, serial, workspace, owner và template version đã pin. Quản
 * lý lifecycle/metadata; trạng thái kết nối và bộ đếm runtime tách sang device_runtime.
 */
-- Bảng devices: Registry thiết bị: identity MQTT toàn cục, serial, workspace, owner và template version đã pin.
-- Quản lý lifecycle/metadata; trạng thái kết nối và bộ đếm runtime tách sang device_runtime.
CREATE TABLE public.devices (
    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành devices_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng
    -- cho cả tổ hợp.
    -- PRIMARY KEY (device_id)
    -- Ràng buộc hiện hành devices_workspace_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột riêng lẻ
    -- vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id)
    -- Ràng buộc hiện hành devices_workspace_id_device_id_template_version_id_key: không trùng tổ hợp giá trị được nêu;
    -- các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, template_version_id)
    device_id uuid NOT NULL,

    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành devices_workspace_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột riêng lẻ
    -- vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id)
    -- Ràng buộc hiện hành devices_workspace_id_device_id_template_version_id_key: không trùng tổ hợp giá trị được nêu;
    -- các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, template_version_id)
    -- Ràng buộc hiện hành devices_workspace_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan
    -- hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id) REFERENCES workspaces(workspace_id)
    -- Ràng buộc hiện hành devices_workspace_id_owner_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, owner_user_id) REFERENCES memberships(workspace_id, user_id)
    -- Ràng buộc hiện hành devices_workspace_id_template_version_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_version_id) REFERENCES template_versions(workspace_id, template_version_id)
    workspace_id uuid NOT NULL,

    -- Serial phần cứng duy nhất toàn cục, phân biệt hoa/thường theo contract registry; dùng lookup đăng ký/onboarding.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_device_serial: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((serial_number ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$'::text))
    -- Ràng buộc hiện hành devices_serial_number_key: không trùng tổ hợp giá trị được nêu; các cột riêng lẻ vẫn có thể
    -- lặp khi khóa có nhiều cột.
    -- UNIQUE (serial_number)
    serial_number text NOT NULL,

    -- Identity snapshot template cụ thể, dùng pin schema và kiểm đúng definition trong workspace.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành devices_workspace_id_device_id_template_version_id_key: không trùng tổ hợp giá trị được nêu;
    -- các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, device_id, template_version_id)
    -- Ràng buộc hiện hành devices_workspace_id_template_version_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_version_id) REFERENCES template_versions(workspace_id, template_version_id)
    template_version_id uuid NOT NULL,

    -- Tài khoản sở hữu tài nguyên trong workspace; backend phải kiểm membership và quyền hiện hành khi đọc/ghi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành devices_workspace_id_owner_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, owner_user_id) REFERENCES memberships(workspace_id, user_id)
    owner_user_id uuid NOT NULL,

    -- Tên hiển thị do người dùng đặt cho tài nguyên; không dùng làm identity, quyền hoặc khóa chống lặp.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    name text NOT NULL,

    -- Mô tả bổ sung để người dùng hiểu tài nguyên; NULL nghĩa chưa cung cấp mô tả, không mang authority vận hành.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    description text,

    -- Mã model phần cứng/template theo registry đã duyệt, dùng kiểm tương thích; không suy model từ tên hiển thị.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    model text NOT NULL,

    -- Revision phần cứng từ authenticated hello/status; NULL khi registry chưa có observation, không lấy từ input đăng
    -- ký. Dùng kiểm tương thích firmware, không thuộc identity cloud bất biến.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    hardware_revision text,

    -- Phiên bản firmware được thiết bị báo hoặc manifest khai; không tự chứng minh artifact đã được xác minh/chạy
    -- khỏe.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    firmware_version text,

    -- SHA-256 32 byte của image firmware được xác thực từ thiết bị; NULL khi chưa có identity image đáng tin cậy.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành devices_firmware_digest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(firmware_digest) = 32))
    firmware_digest bytea,

    -- Trạng thái vòng đời quản lý tài nguyên, tách khỏi presence hoặc tiến độ của job đang chạy.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'REGISTERED'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không
    -- tự áp lại khi UPDATE.
    -- Ràng buộc hiện hành ck_device_lifecycle: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((lifecycle_status = ANY (ARRAY['REGISTERED'::text, 'ACTIVE'::text, 'SUSPENDED'::text,
    -- 'ARCHIVED'::text])))
    lifecycle_status text DEFAULT 'REGISTERED'::text NOT NULL,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành devices_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Mốc phiên bản quyền hiện hành; bên ghi phải tăng khi quyền thay đổi để ticket/job/cache phát hiện ngữ cảnh quyền
    -- cũ.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành devices_authorization_version_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((authorization_version > 0))
    authorization_version bigint DEFAULT 1 NOT NULL,

    -- Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy
    -- định.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Thời điểm cập nhật gần nhất do đường ghi quản lý; không mặc định SQL tự cập nhật nếu không có trigger tương ứng.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_device_lifecycle CHECK ((lifecycle_status = ANY (ARRAY['REGISTERED'::text, 'ACTIVE'::text, 'SUSPENDED'::text, 'ARCHIVED'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_device_serial CHECK ((serial_number ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,63}$'::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT devices_authorization_version_check CHECK ((authorization_version > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT devices_firmware_digest_check CHECK ((octet_length(firmware_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT devices_revision_check CHECK ((revision > 0))
);


--
-- Name: TABLE devices; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.devices IS 'Registry thiết bị: identity MQTT toàn cục, serial, workspace, owner và template version đã pin. Quản lý lifecycle/metadata; trạng thái kết nối và bộ đếm runtime tách sang device_runtime.';


--
-- Name: COLUMN devices.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN devices.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN devices.serial_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.serial_number IS 'Serial phần cứng duy nhất toàn cục, phân biệt hoa/thường theo contract registry; dùng lookup đăng ký/onboarding.';


--
-- Name: COLUMN devices.template_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.template_version_id IS 'Identity snapshot template cụ thể, dùng pin schema và kiểm đúng definition trong workspace.';


--
-- Name: COLUMN devices.owner_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.owner_user_id IS 'Tài khoản sở hữu tài nguyên trong workspace; backend phải kiểm membership và quyền hiện hành khi đọc/ghi.';


--
-- Name: COLUMN devices.name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.name IS 'Tên hiển thị do người dùng đặt cho tài nguyên; không dùng làm identity, quyền hoặc khóa chống lặp.';


--
-- Name: COLUMN devices.description; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.description IS 'Mô tả bổ sung để người dùng hiểu tài nguyên; NULL nghĩa chưa cung cấp mô tả, không mang authority vận hành.';


--
-- Name: COLUMN devices.model; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.model IS 'Mã model phần cứng/template theo registry đã duyệt, dùng kiểm tương thích; không suy model từ tên hiển thị.';


--
-- Name: COLUMN devices.hardware_revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.hardware_revision IS 'Revision phần cứng từ authenticated hello/status; NULL khi registry chưa có observation, không lấy từ input đăng ký. Dùng kiểm tương thích firmware, không thuộc identity cloud bất biến.';


--
-- Name: COLUMN devices.firmware_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.firmware_version IS 'Phiên bản firmware được thiết bị báo hoặc manifest khai; không tự chứng minh artifact đã được xác minh/chạy khỏe.';


--
-- Name: COLUMN devices.firmware_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.firmware_digest IS 'SHA-256 32 byte của image firmware được xác thực từ thiết bị; NULL khi chưa có identity image đáng tin cậy.';


--
-- Name: COLUMN devices.lifecycle_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.lifecycle_status IS 'Trạng thái vòng đời quản lý tài nguyên, tách khỏi presence hoặc tiến độ của job đang chạy.';


--
-- Name: COLUMN devices.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: COLUMN devices.authorization_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.authorization_version IS 'Mốc phiên bản quyền hiện hành; bên ghi phải tăng khi quyền thay đổi để ticket/job/cache phát hiện ngữ cảnh quyền cũ.';


--
-- Name: COLUMN devices.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.created_at IS 'Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy định.';


--
-- Name: COLUMN devices.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.devices.updated_at IS 'Thời điểm cập nhật gần nhất do đường ghi quản lý; không mặc định SQL tự cập nhật nếu không có trigger tương ứng.';


--
-- Name: enrollment_cleanup_operations; Type: TABLE; Schema: public; Owner: -
--

/* public.enrollment_cleanup_operations
 * Công việc cleanup enrollment cùng bằng chứng revoke/disconnect. Tách khỏi TTL của phiên để expiry
 * không bị hiểu nhầm là cloud cleanup đã hoàn tất.
 */
-- Bảng enrollment_cleanup_operations: Công việc cleanup enrollment cùng bằng chứng revoke/disconnect. Tách khỏi
-- TTL của phiên để expiry không bị hiểu nhầm là cloud cleanup đã hoàn tất.
CREATE TABLE public.enrollment_cleanup_operations (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_cleanup_operations_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, enrollment_cleanup_operation_id)
    -- Ràng buộc hiện hành enrollment_cleanup_operations_workspace_id_enrollment_sess_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, enrollment_session_id, device_id) REFERENCES enrollment_sessions(workspace_id,
    -- enrollment_session_id, device_id)
    -- Ràng buộc hiện hành enrollment_cleanup_operations_workspace_id_enrollment_sessi_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, enrollment_session_id)
    workspace_id uuid NOT NULL,

    -- Identity công việc cleanup của enrollment, dùng theo dõi proof và settlement độc lập TTL phiên.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_cleanup_operations_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, enrollment_cleanup_operation_id)
    enrollment_cleanup_operation_id uuid NOT NULL,

    -- Identity ý định onboarding/đổi Wi-Fi, dùng polling, proof binding và liên kết cleanup/guard.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_cleanup_operations_workspace_id_enrollment_sess_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, enrollment_session_id, device_id) REFERENCES enrollment_sessions(workspace_id,
    -- enrollment_session_id, device_id)
    -- Ràng buộc hiện hành enrollment_cleanup_operations_workspace_id_enrollment_sessi_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, enrollment_session_id)
    enrollment_session_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_cleanup_operations_workspace_id_enrollment_sess_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, enrollment_session_id, device_id) REFERENCES enrollment_sessions(workspace_id,
    -- enrollment_session_id, device_id)
    device_id uuid NOT NULL,

    -- Trạng thái xử lý bền vững của ledger/job/operation; không suy rằng enum hợp lệ tự chứng minh transition hợp lệ.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_cleanup_operations_state_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text,
    -- 'NEEDS_ATTENTION'::text])))
    state text NOT NULL,

    -- Thời điểm lưu ý định trước side effect bên ngoài DB; dùng tính ngân sách/expiry và phục hồi khi mất ACK.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    intent_at timestamp with time zone NOT NULL,

    -- Bằng chứng đã redact về broker xác nhận thu hồi; không suy chỉ ghi trạng thái DB là broker đã chặn credential.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    broker_revoke_receipt jsonb,

    -- Bằng chứng đã redact về kết nối thiết bị bị ngắt theo cleanup/lifecycle protocol; cần giữ để settlement có căn
    -- cứ.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    disconnect_receipt jsonb,

    -- Thời điểm nghĩa vụ vận hành được đối soát xong và có thể nhả guard/quota; NULL tiếp tục giữ nghĩa vụ chưa giải
    -- quyết.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    settled_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_cleanup_operations_state_check CHECK ((state = ANY (ARRAY['PENDING'::text, 'RUNNING'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'NEEDS_ATTENTION'::text])))
);


--
-- Name: TABLE enrollment_cleanup_operations; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.enrollment_cleanup_operations IS 'Công việc cleanup enrollment cùng bằng chứng revoke/disconnect. Tách khỏi TTL của phiên để expiry không bị hiểu nhầm là cloud cleanup đã hoàn tất.';


--
-- Name: COLUMN enrollment_cleanup_operations.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN enrollment_cleanup_operations.enrollment_cleanup_operation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.enrollment_cleanup_operation_id IS 'Identity công việc cleanup của enrollment, dùng theo dõi proof và settlement độc lập TTL phiên.';


--
-- Name: COLUMN enrollment_cleanup_operations.enrollment_session_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.enrollment_session_id IS 'Identity ý định onboarding/đổi Wi-Fi, dùng polling, proof binding và liên kết cleanup/guard.';


--
-- Name: COLUMN enrollment_cleanup_operations.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN enrollment_cleanup_operations.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.state IS 'Trạng thái xử lý bền vững của ledger/job/operation; không suy rằng enum hợp lệ tự chứng minh transition hợp lệ.';


--
-- Name: COLUMN enrollment_cleanup_operations.intent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.intent_at IS 'Thời điểm lưu ý định trước side effect bên ngoài DB; dùng tính ngân sách/expiry và phục hồi khi mất ACK.';


--
-- Name: COLUMN enrollment_cleanup_operations.broker_revoke_receipt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.broker_revoke_receipt IS 'Bằng chứng đã redact về broker xác nhận thu hồi; không suy chỉ ghi trạng thái DB là broker đã chặn credential.';


--
-- Name: COLUMN enrollment_cleanup_operations.disconnect_receipt; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.disconnect_receipt IS 'Bằng chứng đã redact về kết nối thiết bị bị ngắt theo cleanup/lifecycle protocol; cần giữ để settlement có căn cứ.';


--
-- Name: COLUMN enrollment_cleanup_operations.settled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_cleanup_operations.settled_at IS 'Thời điểm nghĩa vụ vận hành được đối soát xong và có thể nhả guard/quota; NULL tiếp tục giữ nghĩa vụ chưa giải quyết.';


--
-- Name: enrollment_sessions; Type: TABLE; Schema: public; Owner: -
--

/* public.enrollment_sessions
 * Ý định onboarding/đổi Wi-Fi gắn device, actor grant, installation và proof, hạn 10 phút. Không lưu
 * PoP/SSID/mật khẩu Wi-Fi và không phụ thuộc quyền nhận push.
 */
-- Bảng enrollment_sessions: Ý định onboarding/đổi Wi-Fi gắn device, actor grant, installation và proof, hạn 10
-- phút. Không lưu PoP/SSID/mật khẩu Wi-Fi và không phụ thuộc quyền nhận push.
CREATE TABLE public.enrollment_sessions (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, enrollment_session_id)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_actor_user_id_actor_grant_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, actor_user_id, actor_grant_generation) REFERENCES membership_grants(workspace_id,
    -- user_id, grant_generation)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_enrollment_session_id_devi_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, enrollment_session_id, device_id)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_provisioning_operation_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, provisioning_operation_id, device_id) REFERENCES
    -- provisioning_operations(workspace_id, provisioning_operation_id, device_id)
    workspace_id uuid NOT NULL,

    -- Identity ý định onboarding/đổi Wi-Fi, dùng polling, proof binding và liên kết cleanup/guard.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, enrollment_session_id)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_enrollment_session_id_devi_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, enrollment_session_id, device_id)
    enrollment_session_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_enrollment_session_id_devi_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, enrollment_session_id, device_id)
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_provisioning_operation_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, provisioning_operation_id, device_id) REFERENCES
    -- provisioning_operations(workspace_id, provisioning_operation_id, device_id)
    device_id uuid NOT NULL,

    -- Tài khoản thực hiện hoặc khởi tạo thao tác, phục vụ kiểm quyền và truy vết; không lấy authority chỉ từ ID client
    -- gửi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_actor_user_id_actor_grant_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, actor_user_id, actor_grant_generation) REFERENCES membership_grants(workspace_id,
    -- user_id, grant_generation)
    actor_user_id uuid NOT NULL,

    -- Grant actor được chụp lúc tạo enrollment, giúp kiểm tác vụ cũ sau remove/rejoin.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_actor_user_id_actor_grant_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, actor_user_id, actor_grant_generation) REFERENCES membership_grants(workspace_id,
    -- user_id, grant_generation)
    actor_grant_generation bigint NOT NULL,

    -- Installation mà enrollment gắn với; cố ý không FK tới push_installations vì onboarding không đòi quyền push.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    client_installation_id uuid NOT NULL,

    -- Digest 32 byte của proof enrollment do installation nắm, dùng chứng minh quyền thao tác phiên; không thay QR PoP
    -- hoặc physical proof.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_enrollment_proof_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(enrollment_proof_digest) = 32))
    enrollment_proof_digest bytea NOT NULL,

    -- Chế độ enrollment INITIAL/WIFI_RECONFIGURE; đổi Wi-Fi không tự tạo/thu hồi MQTT credential hiện hành.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((mode <> 'WIFI_RECONFIGURE'::text) OR (provisioning_operation_id IS NULL)))
    -- Ràng buộc hiện hành enrollment_sessions_mode_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((mode = ANY (ARRAY['INITIAL'::text, 'WIFI_RECONFIGURE'::text])))
    mode text NOT NULL,

    -- CREATED→BLE_CONNECTED→WIFI_JOINED→CLOUD_CONNECTING→COMPLETED hoặc FAILED/CANCELLED/EXPIRED; chỉ trusted cloud
    -- evidence mới được xác nhận COMPLETED.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'CREATED'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự
    -- áp lại khi UPDATE.
    -- Ràng buộc hiện hành enrollment_sessions_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((state = 'COMPLETED'::text) = (completed_at IS NOT NULL)))
    -- Ràng buộc hiện hành enrollment_sessions_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['CREATED'::text, 'BLE_CONNECTED'::text, 'WIFI_JOINED'::text,
    -- 'CLOUD_CONNECTING'::text, 'COMPLETED'::text, 'FAILED'::text, 'CANCELLED'::text, 'EXPIRED'::text])))
    state text DEFAULT 'CREATED'::text NOT NULL,

    -- Thời điểm bắt đầu boot/enrollment/action hoặc hoạt động tương ứng, tùy ngữ nghĩa bảng.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at = (started_at + '00:10:00'::interval)))
    started_at timestamp with time zone NOT NULL,

    -- Hạn phiên started_at + 10 phút; expiry không tự xóa guard khi broker cleanup còn thiếu proof.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành enrollment_sessions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at = (started_at + '00:10:00'::interval)))
    expires_at timestamp with time zone NOT NULL,

    -- Identity công việc cấp credential, dùng claim một lần và gắn enrollment đúng device/generation.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành enrollment_sessions_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((mode <> 'WIFI_RECONFIGURE'::text) OR (provisioning_operation_id IS NULL)))
    -- Ràng buộc hiện hành enrollment_sessions_workspace_id_provisioning_operation_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, provisioning_operation_id, device_id) REFERENCES
    -- provisioning_operations(workspace_id, provisioning_operation_id, device_id)
    provisioning_operation_id uuid,

    -- Thời điểm tác vụ hoặc enrollment được ghi nhận hoàn tất theo điều kiện của bảng; không lấy timer client làm bằng
    -- chứng.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành enrollment_sessions_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((state = 'COMPLETED'::text) = (completed_at IS NOT NULL)))
    completed_at timestamp with time zone,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành enrollment_sessions_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_check CHECK ((expires_at = (started_at + '00:10:00'::interval))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_check1 CHECK (((state = 'COMPLETED'::text) = (completed_at IS NOT NULL))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_check2 CHECK (((mode <> 'WIFI_RECONFIGURE'::text) OR (provisioning_operation_id IS NULL))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_enrollment_proof_digest_check CHECK ((octet_length(enrollment_proof_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_mode_check CHECK ((mode = ANY (ARRAY['INITIAL'::text, 'WIFI_RECONFIGURE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_revision_check CHECK ((revision > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT enrollment_sessions_state_check CHECK ((state = ANY (ARRAY['CREATED'::text, 'BLE_CONNECTED'::text, 'WIFI_JOINED'::text, 'CLOUD_CONNECTING'::text, 'COMPLETED'::text, 'FAILED'::text, 'CANCELLED'::text, 'EXPIRED'::text])))
);


--
-- Name: TABLE enrollment_sessions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.enrollment_sessions IS 'Ý định onboarding/đổi Wi-Fi gắn device, actor grant, installation và proof, hạn 10 phút. Không lưu PoP/SSID/mật khẩu Wi-Fi và không phụ thuộc quyền nhận push.';


--
-- Name: COLUMN enrollment_sessions.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN enrollment_sessions.enrollment_session_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.enrollment_session_id IS 'Identity ý định onboarding/đổi Wi-Fi, dùng polling, proof binding và liên kết cleanup/guard.';


--
-- Name: COLUMN enrollment_sessions.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN enrollment_sessions.actor_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.actor_user_id IS 'Tài khoản thực hiện hoặc khởi tạo thao tác, phục vụ kiểm quyền và truy vết; không lấy authority chỉ từ ID client gửi.';


--
-- Name: COLUMN enrollment_sessions.actor_grant_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.actor_grant_generation IS 'Grant actor được chụp lúc tạo enrollment, giúp kiểm tác vụ cũ sau remove/rejoin.';


--
-- Name: COLUMN enrollment_sessions.client_installation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.client_installation_id IS 'Installation mà enrollment gắn với; cố ý không FK tới push_installations vì onboarding không đòi quyền push.';


--
-- Name: COLUMN enrollment_sessions.enrollment_proof_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.enrollment_proof_digest IS 'Digest 32 byte của proof enrollment do installation nắm, dùng chứng minh quyền thao tác phiên; không thay QR PoP hoặc physical proof.';


--
-- Name: COLUMN enrollment_sessions.mode; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.mode IS 'Chế độ enrollment INITIAL/WIFI_RECONFIGURE; đổi Wi-Fi không tự tạo/thu hồi MQTT credential hiện hành.';


--
-- Name: COLUMN enrollment_sessions.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.state IS 'CREATED→BLE_CONNECTED→WIFI_JOINED→CLOUD_CONNECTING→COMPLETED hoặc FAILED/CANCELLED/EXPIRED; chỉ trusted cloud evidence mới được xác nhận COMPLETED.';


--
-- Name: COLUMN enrollment_sessions.started_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.started_at IS 'Thời điểm bắt đầu boot/enrollment/action hoặc hoạt động tương ứng, tùy ngữ nghĩa bảng.';


--
-- Name: COLUMN enrollment_sessions.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.expires_at IS 'Hạn phiên started_at + 10 phút; expiry không tự xóa guard khi broker cleanup còn thiếu proof.';


--
-- Name: COLUMN enrollment_sessions.provisioning_operation_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.provisioning_operation_id IS 'Identity công việc cấp credential, dùng claim một lần và gắn enrollment đúng device/generation.';


--
-- Name: COLUMN enrollment_sessions.completed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.completed_at IS 'Thời điểm tác vụ hoặc enrollment được ghi nhận hoàn tất theo điều kiện của bảng; không lấy timer client làm bằng chứng.';


--
-- Name: COLUMN enrollment_sessions.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.enrollment_sessions.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: event_occurrences; Type: TABLE; Schema: public; Owner: -
--

/* public.event_occurrences
 * Journal từng transition đã commit của Event, command hoặc connectivity. Identity occurrence dùng cho
 * webhook, khác Event nghiệp vụ; nhánh typed/XOR tránh tạo Event giả.
 */
-- Bảng event_occurrences: Journal từng transition đã commit của Event, command hoặc connectivity. Identity
-- occurrence dùng cho webhook, khác Event nghiệp vụ; nhánh typed/XOR tránh tạo Event giả.
CREATE TABLE public.event_occurrences (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành event_occurrences_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, occurrence_id)
    -- Ràng buộc hiện hành event_occurrences_workspace_id_command_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, command_id) REFERENCES commands(workspace_id, command_id)
    -- Ràng buộc hiện hành event_occurrences_workspace_id_connectivity_device_id_conn_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, connectivity_device_id, connectivity_transition_sequence) REFERENCES
    -- connectivity_transitions(workspace_id, device_id, transition_sequence)
    -- Ràng buộc hiện hành event_occurrences_workspace_id_event_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, event_id) REFERENCES events(workspace_id, event_id)
    -- Ràng buộc hiện hành event_occurrences_workspace_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id
    -- giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id) REFERENCES workspaces(workspace_id)
    workspace_id uuid NOT NULL,

    -- Identity một transition đã commit; wire webhook eventId ánh xạ identity này, không gộp OPEN/RESOLVED thành một
    -- Event ID.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành event_occurrences_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, occurrence_id)
    occurrence_id uuid NOT NULL,

    -- Discriminator chỉ loại nguồn typed; phải đi cùng đúng một nhánh FK, không dùng ID đa hình không kiểm chứng.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_event_occurrences_public_type: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (occurrence_type = 'CREATED'::text) AND (public_event_type IS NOT
    -- NULL) AND (public_event_type = 'event.opened'::text)) OR ((source_kind = 'EVENT'::text) AND (occurrence_type =
    -- 'RESOLVED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'event.resolved'::text)) OR
    -- ((source_kind = 'EVENT'::text) AND (occurrence_type = 'ACKNOWLEDGED'::text) AND (public_event_type IS NULL)) OR
    -- ((source_kind = 'COMMAND'::text) AND (occurrence_type = 'COMMAND_TERMINAL'::text) AND (public_event_type IS NOT
    -- NULL) AND (public_event_type = 'command.completed'::text)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (occurrence_type = 'CONNECTIVITY_CHANGED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type =
    -- 'device.connectivity'::text))))
    -- Ràng buộc hiện hành ck_event_occurrences_source_shape: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND
    -- (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) =
    -- 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision,
    -- connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND
    -- (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0))))
    -- Ràng buộc hiện hành event_occurrences_source_kind_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((source_kind = ANY (ARRAY['EVENT'::text, 'COMMAND'::text, 'CONNECTIVITY'::text])))
    source_kind text NOT NULL,

    -- Identity Event nghiệp vụ trong workspace; khác occurrence_id đại diện từng transition để giao webhook.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_event_occurrences_source_shape: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND
    -- (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) =
    -- 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision,
    -- connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND
    -- (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0))))
    -- Ràng buộc hiện hành event_occurrences_workspace_id_event_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, event_id) REFERENCES events(workspace_id, event_id)
    event_id uuid,

    -- Revision transition Event được chụp trong occurrence, lớn hơn 0; unique cùng Event tránh phát cùng transition
    -- hai lần.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_event_occurrences_source_shape: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND
    -- (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) =
    -- 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision,
    -- connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND
    -- (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0))))
    event_revision bigint,

    -- Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_event_occurrences_source_shape: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND
    -- (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) =
    -- 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision,
    -- connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND
    -- (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0))))
    -- Ràng buộc hiện hành event_occurrences_workspace_id_command_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, command_id) REFERENCES commands(workspace_id, command_id)
    command_id uuid,

    -- Device làm nguồn occurrence connectivity, chỉ có trong nhánh CONNECTIVITY.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_event_occurrences_source_shape: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND
    -- (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) =
    -- 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision,
    -- connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND
    -- (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0))))
    -- Ràng buộc hiện hành event_occurrences_workspace_id_connectivity_device_id_conn_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, connectivity_device_id, connectivity_transition_sequence) REFERENCES
    -- connectivity_transitions(workspace_id, device_id, transition_sequence)
    connectivity_device_id uuid,

    -- Transition presence cụ thể của connectivity_device_id; cùng device/sequence là nguồn chống trùng occurrence.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_event_occurrences_source_shape: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND
    -- (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) =
    -- 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision,
    -- connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND
    -- (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0))))
    -- Ràng buộc hiện hành event_occurrences_workspace_id_connectivity_device_id_conn_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc
    -- định bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, connectivity_device_id, connectivity_transition_sequence) REFERENCES
    -- connectivity_transitions(workspace_id, device_id, transition_sequence)
    connectivity_transition_sequence bigint,

    -- Loại transition nội bộ của nguồn occurrence; ACKNOWLEDGED không mặc định thành BUSINESS webhook public.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_event_occurrences_public_type: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (occurrence_type = 'CREATED'::text) AND (public_event_type IS NOT
    -- NULL) AND (public_event_type = 'event.opened'::text)) OR ((source_kind = 'EVENT'::text) AND (occurrence_type =
    -- 'RESOLVED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'event.resolved'::text)) OR
    -- ((source_kind = 'EVENT'::text) AND (occurrence_type = 'ACKNOWLEDGED'::text) AND (public_event_type IS NULL)) OR
    -- ((source_kind = 'COMMAND'::text) AND (occurrence_type = 'COMMAND_TERMINAL'::text) AND (public_event_type IS NOT
    -- NULL) AND (public_event_type = 'command.completed'::text)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (occurrence_type = 'CONNECTIVITY_CHANGED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type =
    -- 'device.connectivity'::text))))
    occurrence_type text NOT NULL,

    -- Loại event public để webhook fanout; NULL cho occurrence nội bộ không được phép phát BUSINESS webhook.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_event_occurrences_public_type: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'EVENT'::text) AND (occurrence_type = 'CREATED'::text) AND (public_event_type IS NOT
    -- NULL) AND (public_event_type = 'event.opened'::text)) OR ((source_kind = 'EVENT'::text) AND (occurrence_type =
    -- 'RESOLVED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'event.resolved'::text)) OR
    -- ((source_kind = 'EVENT'::text) AND (occurrence_type = 'ACKNOWLEDGED'::text) AND (public_event_type IS NULL)) OR
    -- ((source_kind = 'COMMAND'::text) AND (occurrence_type = 'COMMAND_TERMINAL'::text) AND (public_event_type IS NOT
    -- NULL) AND (public_event_type = 'command.completed'::text)) OR ((source_kind = 'CONNECTIVITY'::text) AND
    -- (occurrence_type = 'CONNECTIVITY_CHANGED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type =
    -- 'device.connectivity'::text))))
    public_event_type text,

    -- Thời điểm nghiệp vụ/sự kiện diễn ra để sắp xếp timeline; không mặc định bằng thời điểm fanout hoặc provider phản
    -- hồi.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    occurred_at timestamp with time zone NOT NULL,

    -- Mốc thời gian producer ghi cho occurrence trong transaction đã commit thành công; không phải physical commit
    -- timestamp biết trước commit.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    committed_at timestamp with time zone NOT NULL,

    -- Snapshot payload occurrence đã commit, giữ nguyên để fanout/retry không đọc lại resource mutable rồi đổi sự thật
    -- lịch sử.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành event_occurrences_immutable_payload_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((jsonb_typeof(immutable_payload) = 'object'::text))
    immutable_payload jsonb NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_event_occurrences_public_type CHECK ((((source_kind = 'EVENT'::text) AND (occurrence_type = 'CREATED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'event.opened'::text)) OR ((source_kind = 'EVENT'::text) AND (occurrence_type = 'RESOLVED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'event.resolved'::text)) OR ((source_kind = 'EVENT'::text) AND (occurrence_type = 'ACKNOWLEDGED'::text) AND (public_event_type IS NULL)) OR ((source_kind = 'COMMAND'::text) AND (occurrence_type = 'COMMAND_TERMINAL'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'command.completed'::text)) OR ((source_kind = 'CONNECTIVITY'::text) AND (occurrence_type = 'CONNECTIVITY_CHANGED'::text) AND (public_event_type IS NOT NULL) AND (public_event_type = 'device.connectivity'::text)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_event_occurrences_source_shape CHECK ((((source_kind = 'EVENT'::text) AND (event_id IS NOT NULL) AND (event_revision IS NOT NULL) AND (event_revision > 0) AND (num_nonnulls(command_id, connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'COMMAND'::text) AND (command_id IS NOT NULL) AND (num_nonnulls(event_id, event_revision, connectivity_device_id, connectivity_transition_sequence) = 0)) OR ((source_kind = 'CONNECTIVITY'::text) AND (connectivity_device_id IS NOT NULL) AND (connectivity_transition_sequence IS NOT NULL) AND (connectivity_transition_sequence > 0) AND (num_nonnulls(event_id, event_revision, command_id) = 0)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT event_occurrences_immutable_payload_check CHECK ((jsonb_typeof(immutable_payload) = 'object'::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT event_occurrences_source_kind_check CHECK ((source_kind = ANY (ARRAY['EVENT'::text, 'COMMAND'::text, 'CONNECTIVITY'::text])))
);


--
-- Name: TABLE event_occurrences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.event_occurrences IS 'Journal từng transition đã commit của Event, command hoặc connectivity. Identity occurrence dùng cho webhook, khác Event nghiệp vụ; nhánh typed/XOR tránh tạo Event giả.';


--
-- Name: COLUMN event_occurrences.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN event_occurrences.occurrence_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.occurrence_id IS 'Identity một transition đã commit; wire webhook eventId ánh xạ identity này, không gộp OPEN/RESOLVED thành một Event ID.';


--
-- Name: COLUMN event_occurrences.source_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.source_kind IS 'Discriminator chỉ loại nguồn typed; phải đi cùng đúng một nhánh FK, không dùng ID đa hình không kiểm chứng.';


--
-- Name: COLUMN event_occurrences.event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.event_id IS 'Identity Event nghiệp vụ trong workspace; khác occurrence_id đại diện từng transition để giao webhook.';


--
-- Name: COLUMN event_occurrences.event_revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.event_revision IS 'Revision transition Event được chụp trong occurrence, lớn hơn 0; unique cùng Event tránh phát cùng transition hai lần.';


--
-- Name: COLUMN event_occurrences.command_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.command_id IS 'Identity command ổn định qua retry/result/reconciliation; không tạo command mới chỉ vì mất response.';


--
-- Name: COLUMN event_occurrences.connectivity_device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.connectivity_device_id IS 'Device làm nguồn occurrence connectivity, chỉ có trong nhánh CONNECTIVITY.';


--
-- Name: COLUMN event_occurrences.connectivity_transition_sequence; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.connectivity_transition_sequence IS 'Transition presence cụ thể của connectivity_device_id; cùng device/sequence là nguồn chống trùng occurrence.';


--
-- Name: COLUMN event_occurrences.occurrence_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.occurrence_type IS 'Loại transition nội bộ của nguồn occurrence; ACKNOWLEDGED không mặc định thành BUSINESS webhook public.';


--
-- Name: COLUMN event_occurrences.public_event_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.public_event_type IS 'Loại event public để webhook fanout; NULL cho occurrence nội bộ không được phép phát BUSINESS webhook.';


--
-- Name: COLUMN event_occurrences.occurred_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.occurred_at IS 'Thời điểm nghiệp vụ/sự kiện diễn ra để sắp xếp timeline; không mặc định bằng thời điểm fanout hoặc provider phản hồi.';


--
-- Name: COLUMN event_occurrences.committed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.committed_at IS 'Mốc thời gian producer ghi cho occurrence trong transaction đã commit thành công; không phải physical commit timestamp biết trước commit.';


--
-- Name: COLUMN event_occurrences.immutable_payload; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.event_occurrences.immutable_payload IS 'Snapshot payload occurrence đã commit, giữ nguyên để fanout/retry không đọc lại resource mutable rồi đổi sự thật lịch sử.';


--
-- Name: events; Type: TABLE; Schema: public; Owner: -
--

/* public.events
 * Sự kiện nghiệp vụ theo nguồn device/rule và episode, có mức độ cùng vòng đời đọc/xác nhận/resolve.
 * Một Event có thể tạo nhiều occurrence và inbox cho từng recipient.
 */
-- Bảng events: Sự kiện nghiệp vụ theo nguồn device/rule và episode, có mức độ cùng vòng đời đọc/xác nhận/resolve.
-- Một Event có thể tạo nhiều occurrence và inbox cho từng recipient.
CREATE TABLE public.events (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành events_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng cho
    -- cả tổ hợp.
    -- PRIMARY KEY (workspace_id, event_id)
    -- Ràng buộc hiện hành events_workspace_id_acknowledged_by_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, acknowledged_by_user_id) REFERENCES memberships(workspace_id, user_id)
    -- Ràng buộc hiện hành events_workspace_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan
    -- hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id) REFERENCES workspaces(workspace_id)
    -- Ràng buộc hiện hành events_workspace_id_source_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, source_device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành events_workspace_id_source_kind_source_identity_episode_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, source_kind, source_identity, episode_key)
    -- Ràng buộc hiện hành events_workspace_id_source_rule_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, source_rule_id) REFERENCES rules(workspace_id, rule_id)
    workspace_id uuid NOT NULL,

    -- Identity Event nghiệp vụ trong workspace; khác occurrence_id đại diện từng transition để giao webhook.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành events_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng cho
    -- cả tổ hợp.
    -- PRIMARY KEY (workspace_id, event_id)
    event_id uuid NOT NULL,

    -- Discriminator chỉ loại nguồn typed; phải đi cùng đúng một nhánh FK, không dùng ID đa hình không kiểm chứng.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành events_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối hợp
    -- NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'DEVICE'::text) AND (source_device_id IS NOT NULL) AND (source_rule_id IS NULL)) OR
    -- ((source_kind = 'RULE'::text) AND (source_rule_id IS NOT NULL) AND (source_device_id IS NULL))))
    -- Ràng buộc hiện hành events_source_kind_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((source_kind = ANY (ARRAY['DEVICE'::text, 'RULE'::text])))
    -- Ràng buộc hiện hành events_workspace_id_source_kind_source_identity_episode_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, source_kind, source_identity, episode_key)
    source_kind text NOT NULL,

    -- Device làm nguồn Event khi source_kind=DEVICE; nhánh rule phải để NULL để giữ XOR nguồn.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành events_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối hợp
    -- NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'DEVICE'::text) AND (source_device_id IS NOT NULL) AND (source_rule_id IS NULL)) OR
    -- ((source_kind = 'RULE'::text) AND (source_rule_id IS NOT NULL) AND (source_device_id IS NULL))))
    -- Ràng buộc hiện hành events_workspace_id_source_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, source_device_id) REFERENCES devices(workspace_id, device_id)
    source_device_id uuid,

    -- Rule làm nguồn Event khi source_kind=RULE; nhánh device phải để NULL để giữ XOR nguồn.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành events_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối hợp
    -- NOT NULL và CHECK shape khi cần.
    -- CHECK ((((source_kind = 'DEVICE'::text) AND (source_device_id IS NOT NULL) AND (source_rule_id IS NULL)) OR
    -- ((source_kind = 'RULE'::text) AND (source_rule_id IS NOT NULL) AND (source_device_id IS NULL))))
    -- Ràng buộc hiện hành events_workspace_id_source_rule_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, source_rule_id) REFERENCES rules(workspace_id, rule_id)
    source_rule_id uuid,

    -- Identity nguồn Event được sinh từ đúng một nhánh device/rule; dùng natural dedupe cùng source_kind và
    -- episode_key.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành events_workspace_id_source_kind_source_identity_episode_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột. UNIQUE mặc định không coi các giá trị NULL là
    -- trùng nhau.
    -- UNIQUE (workspace_id, source_kind, source_identity, episode_key)
    source_identity uuid GENERATED ALWAYS AS (COALESCE(source_device_id, source_rule_id)) STORED,

    -- Identity episode nghiệp vụ của nguồn Event, dùng dedupe một sự kiện trong cùng chu kỳ lỗi/điều kiện.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành events_episode_key_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((btrim(episode_key) <> ''::text))
    -- Ràng buộc hiện hành events_workspace_id_source_kind_source_identity_episode_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, source_kind, source_identity, episode_key)
    episode_key text NOT NULL,

    -- Mức độ INFO/WARNING/CRITICAL của Event, dùng lọc hiển thị/notification; không thay trạng thái Event.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành events_severity_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text])))
    severity text NOT NULL,

    -- Vòng đời Event OPEN/ACKNOWLEDGED/RESOLVED; khác trạng thái read của inbox và outcome của command.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'OPEN'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp
    -- lại khi UPDATE.
    -- Ràng buộc hiện hành events_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((status = 'RESOLVED'::text) = (resolved_at IS NOT NULL)))
    -- Ràng buộc hiện hành events_status_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'RESOLVED'::text])))
    status text DEFAULT 'OPEN'::text NOT NULL,

    -- Tiêu đề hiển thị của dashboard hoặc sự kiện; là nội dung giao diện, không dùng thay identity tài nguyên.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    title text NOT NULL,

    -- Thông điệp Event dùng hiển thị hoặc thông báo sau validation/redaction phía producer; không là nơi cất payload
    -- bí mật.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    safe_message text NOT NULL,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành events_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy
    -- định.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    created_at timestamp with time zone NOT NULL,

    -- Thành viên đã xác nhận Event; đi cùng acknowledged_at để lưu người và thời điểm ACK.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành events_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((acknowledged_by_user_id IS NULL) = (acknowledged_at IS NULL)))
    -- Ràng buộc hiện hành events_workspace_id_acknowledged_by_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, acknowledged_by_user_id) REFERENCES memberships(workspace_id, user_id)
    acknowledged_by_user_id uuid,

    -- Thời điểm thành viên ACK Event, đi cùng acknowledged_by_user_id và độc lập read_at của inbox.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành events_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((acknowledged_by_user_id IS NULL) = (acknowledged_at IS NULL)))
    acknowledged_at timestamp with time zone,

    -- Thời điểm Event/resolution được đóng xử lý; ngữ nghĩa theo aggregate, không tự thay command UNKNOWN thành
    -- SUCCEEDED.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành events_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((status = 'RESOLVED'::text) = (resolved_at IS NOT NULL)))
    resolved_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_check CHECK ((((source_kind = 'DEVICE'::text) AND (source_device_id IS NOT NULL) AND (source_rule_id IS NULL)) OR ((source_kind = 'RULE'::text) AND (source_rule_id IS NOT NULL) AND (source_device_id IS NULL)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_check1 CHECK (((acknowledged_by_user_id IS NULL) = (acknowledged_at IS NULL))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_check2 CHECK (((status = 'RESOLVED'::text) = (resolved_at IS NOT NULL))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_episode_key_check CHECK ((btrim(episode_key) <> ''::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_revision_check CHECK ((revision > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_severity_check CHECK ((severity = ANY (ARRAY['INFO'::text, 'WARNING'::text, 'CRITICAL'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_source_kind_check CHECK ((source_kind = ANY (ARRAY['DEVICE'::text, 'RULE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT events_status_check CHECK ((status = ANY (ARRAY['OPEN'::text, 'ACKNOWLEDGED'::text, 'RESOLVED'::text])))
);


--
-- Name: TABLE events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.events IS 'Sự kiện nghiệp vụ theo nguồn device/rule và episode, có mức độ cùng vòng đời đọc/xác nhận/resolve. Một Event có thể tạo nhiều occurrence và inbox cho từng recipient.';


--
-- Name: COLUMN events.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN events.event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.event_id IS 'Identity Event nghiệp vụ trong workspace; khác occurrence_id đại diện từng transition để giao webhook.';


--
-- Name: COLUMN events.source_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.source_kind IS 'Discriminator chỉ loại nguồn typed; phải đi cùng đúng một nhánh FK, không dùng ID đa hình không kiểm chứng.';


--
-- Name: COLUMN events.source_device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.source_device_id IS 'Device làm nguồn Event khi source_kind=DEVICE; nhánh rule phải để NULL để giữ XOR nguồn.';


--
-- Name: COLUMN events.source_rule_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.source_rule_id IS 'Rule làm nguồn Event khi source_kind=RULE; nhánh device phải để NULL để giữ XOR nguồn.';


--
-- Name: COLUMN events.source_identity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.source_identity IS 'Identity nguồn Event được sinh từ đúng một nhánh device/rule; dùng natural dedupe cùng source_kind và episode_key.';


--
-- Name: COLUMN events.episode_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.episode_key IS 'Identity episode nghiệp vụ của nguồn Event, dùng dedupe một sự kiện trong cùng chu kỳ lỗi/điều kiện.';


--
-- Name: COLUMN events.severity; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.severity IS 'Mức độ INFO/WARNING/CRITICAL của Event, dùng lọc hiển thị/notification; không thay trạng thái Event.';


--
-- Name: COLUMN events.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.status IS 'Vòng đời Event OPEN/ACKNOWLEDGED/RESOLVED; khác trạng thái read của inbox và outcome của command.';


--
-- Name: COLUMN events.title; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.title IS 'Tiêu đề hiển thị của dashboard hoặc sự kiện; là nội dung giao diện, không dùng thay identity tài nguyên.';


--
-- Name: COLUMN events.safe_message; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.safe_message IS 'Thông điệp Event dùng hiển thị hoặc thông báo sau validation/redaction phía producer; không là nơi cất payload bí mật.';


--
-- Name: COLUMN events.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: COLUMN events.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.created_at IS 'Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy định.';


--
-- Name: COLUMN events.acknowledged_by_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.acknowledged_by_user_id IS 'Thành viên đã xác nhận Event; đi cùng acknowledged_at để lưu người và thời điểm ACK.';


--
-- Name: COLUMN events.acknowledged_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.acknowledged_at IS 'Thời điểm thành viên ACK Event, đi cùng acknowledged_by_user_id và độc lập read_at của inbox.';


--
-- Name: COLUMN events.resolved_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.events.resolved_at IS 'Thời điểm Event/resolution được đóng xử lý; ngữ nghĩa theo aggregate, không tự thay command UNKNOWN thành SUCCEEDED.';


--
-- Name: execution_actuator_snapshots; Type: TABLE; Schema: public; Owner: -
--

/* public.execution_actuator_snapshots
 * Manual epoch của từng actuator tại đầu execution. Giữ snapshot trước WAIT để automation phát hiện
 * người dùng đã điều khiển thủ công và không ghi đè thao tác mới.
 */
-- Bảng execution_actuator_snapshots: Manual epoch của từng actuator tại đầu execution. Giữ snapshot trước WAIT để
-- automation phát hiện người dùng đã điều khiển thủ công và không ghi đè thao tác mới.
CREATE TABLE public.execution_actuator_snapshots (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành execution_actuator_snapshots_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, rule_execution_id, device_id, stream_key)
    -- Ràng buộc hiện hành execution_actuator_snapshots_workspace_id_device_id_stream_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, stream_key) REFERENCES actuator_states(workspace_id, device_id,
    -- stream_key)
    -- Ràng buộc hiện hành execution_actuator_snapshots_workspace_id_rule_execution_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, rule_execution_id) REFERENCES rule_executions(workspace_id, rule_execution_id)
    workspace_id uuid NOT NULL,

    -- Identity một lần quyết định/chạy rule version, dùng quota, history, action chain và notification target.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành execution_actuator_snapshots_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, rule_execution_id, device_id, stream_key)
    -- Ràng buộc hiện hành execution_actuator_snapshots_workspace_id_rule_execution_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, rule_execution_id) REFERENCES rule_executions(workspace_id, rule_execution_id)
    rule_execution_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành execution_actuator_snapshots_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, rule_execution_id, device_id, stream_key)
    -- Ràng buộc hiện hành execution_actuator_snapshots_workspace_id_device_id_stream_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, stream_key) REFERENCES actuator_states(workspace_id, device_id,
    -- stream_key)
    device_id uuid NOT NULL,

    -- Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành execution_actuator_snapshots_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, rule_execution_id, device_id, stream_key)
    -- Ràng buộc hiện hành execution_actuator_snapshots_workspace_id_device_id_stream_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id, stream_key) REFERENCES actuator_states(workspace_id, device_id,
    -- stream_key)
    stream_key text NOT NULL,

    -- Manual epoch của actuator được chụp lúc execution bắt đầu, trước WAIT; không đọc lại sau WAIT rồi coi là
    -- snapshot ban đầu.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành execution_actuator_snapshots_manual_epoch_at_start_check: CHECK chỉ chặn khi biểu thức là
    -- FALSE; NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((manual_epoch_at_start >= 0))
    manual_epoch_at_start bigint NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT execution_actuator_snapshots_manual_epoch_at_start_check CHECK ((manual_epoch_at_start >= 0))
);


--
-- Name: TABLE execution_actuator_snapshots; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.execution_actuator_snapshots IS 'Manual epoch của từng actuator tại đầu execution. Giữ snapshot trước WAIT để automation phát hiện người dùng đã điều khiển thủ công và không ghi đè thao tác mới.';


--
-- Name: COLUMN execution_actuator_snapshots.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_actuator_snapshots.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN execution_actuator_snapshots.rule_execution_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_actuator_snapshots.rule_execution_id IS 'Identity một lần quyết định/chạy rule version, dùng quota, history, action chain và notification target.';


--
-- Name: COLUMN execution_actuator_snapshots.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_actuator_snapshots.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN execution_actuator_snapshots.stream_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_actuator_snapshots.stream_key IS 'Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.';


--
-- Name: COLUMN execution_actuator_snapshots.manual_epoch_at_start; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_actuator_snapshots.manual_epoch_at_start IS 'Manual epoch của actuator được chụp lúc execution bắt đầu, trước WAIT; không đọc lại sau WAIT rồi coi là snapshot ban đầu.';


--
-- Name: rule_executions; Type: TABLE; Schema: public; Owner: -
--

/* public.rule_executions
 * Mỗi lần quyết định/chạy một rule version với trigger identity ổn định và deadline 15 phút. Là ledger
 * runtime cho quota, tiến độ và outcome, tách khỏi payload lịch sử lớn.
 */
-- Bảng rule_executions: Mỗi lần quyết định/chạy một rule version với trigger identity ổn định và deadline 15 phút.
-- Là ledger runtime cho quota, tiến độ và outcome, tách khỏi payload lịch sử lớn.
CREATE TABLE public.rule_executions (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, rule_execution_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_owner_user_id_snapshot_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, owner_user_id_snapshot) REFERENCES memberships(workspace_id, user_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_execution_id_rule_version_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, rule_execution_id, rule_version_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_id_rule_version_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, rule_id, rule_version_id) REFERENCES rule_versions(workspace_id, rule_id,
    -- rule_version_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_version_id_trigger_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, rule_version_id, trigger_key)
    workspace_id uuid NOT NULL,

    -- Identity một lần quyết định/chạy rule version, dùng quota, history, action chain và notification target.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, rule_execution_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_execution_id_rule_version_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, rule_execution_id, rule_version_id)
    rule_execution_id uuid NOT NULL,

    -- Identity gốc rule trong workspace, dùng nhóm draft/version/runtime; không là identity một lần chạy.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_id_rule_version_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, rule_id, rule_version_id) REFERENCES rule_versions(workspace_id, rule_id,
    -- rule_version_id)
    rule_id uuid NOT NULL,

    -- Identity rule snapshot đã publish, dùng pin trigger/action/execution thay vì đọc draft hiện hành.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_execution_id_rule_version_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, rule_execution_id, rule_version_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_id_rule_version_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, rule_id, rule_version_id) REFERENCES rule_versions(workspace_id, rule_id,
    -- rule_version_id)
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_version_id_trigger_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, rule_version_id, trigger_key)
    rule_version_id uuid NOT NULL,

    -- Identity ổn định của trigger/episode/occurrence theo version; dùng dedupe, không sinh key mới chỉ vì worker
    -- restart.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_workspace_id_rule_version_id_trigger_key_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, rule_version_id, trigger_key)
    trigger_key text NOT NULL,

    -- Trạng thái RUNNING/WAITING hoặc kết quả SUCCEEDED/PARTIAL/FAILED/CANCELLED/NEEDS_ATTENTION/NO_MATCH;
    -- RUNNING/WAITING chiếm quota.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['RUNNING'::text, 'WAITING'::text, 'SUCCEEDED'::text, 'PARTIAL'::text, 'FAILED'::text,
    -- 'CANCELLED'::text, 'NEEDS_ATTENTION'::text, 'NO_MATCH'::text])))
    state text NOT NULL,

    -- Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((deadline_at = (admitted_at + '00:15:00'::interval)))
    admitted_at timestamp with time zone NOT NULL,

    -- Deadline admitted_at + 15 phút cho cả execution; WAIT/restart không kéo dài ngân sách toàn chuỗi.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((deadline_at = (admitted_at + '00:15:00'::interval)))
    deadline_at timestamp with time zone NOT NULL,

    -- Thời điểm execution/action kết thúc; NULL khi chưa ghi nhận kết thúc, outcome/state là trục kết quả riêng.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    ended_at timestamp with time zone,

    -- Vị trí bước kế của execution, miền 0..5; giá trị 5 có thể biểu diễn đã qua bước cuối trong chuỗi tối đa 5
    -- action.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 0: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành rule_executions_next_action_position_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((next_action_position >= 0) AND (next_action_position <= 5)))
    next_action_position integer DEFAULT 0 NOT NULL,

    -- Owner được chụp khi execution admission, dùng phân quyền lịch sử theo policy; request vẫn phải recheck
    -- membership hiện hành.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành rule_executions_workspace_id_owner_user_id_snapshot_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, owner_user_id_snapshot) REFERENCES memberships(workspace_id, user_id)
    owner_user_id_snapshot uuid NOT NULL,

    -- Nguyên nhân thất bại đã chuẩn hóa/redact cho vận hành và lịch sử; không lưu response bí mật của dịch vụ ngoài.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    failure_reason text,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT rule_executions_check CHECK ((deadline_at = (admitted_at + '00:15:00'::interval))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT rule_executions_next_action_position_check CHECK (((next_action_position >= 0) AND (next_action_position <= 5))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT rule_executions_state_check CHECK ((state = ANY (ARRAY['RUNNING'::text, 'WAITING'::text, 'SUCCEEDED'::text, 'PARTIAL'::text, 'FAILED'::text, 'CANCELLED'::text, 'NEEDS_ATTENTION'::text, 'NO_MATCH'::text])))
);


--
-- Name: TABLE rule_executions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.rule_executions IS 'Mỗi lần quyết định/chạy một rule version với trigger identity ổn định và deadline 15 phút. Là ledger runtime cho quota, tiến độ và outcome, tách khỏi payload lịch sử lớn.';


--
-- Name: COLUMN rule_executions.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN rule_executions.rule_execution_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.rule_execution_id IS 'Identity một lần quyết định/chạy rule version, dùng quota, history, action chain và notification target.';


--
-- Name: COLUMN rule_executions.rule_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.rule_id IS 'Identity gốc rule trong workspace, dùng nhóm draft/version/runtime; không là identity một lần chạy.';


--
-- Name: COLUMN rule_executions.rule_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.rule_version_id IS 'Identity rule snapshot đã publish, dùng pin trigger/action/execution thay vì đọc draft hiện hành.';


--
-- Name: COLUMN rule_executions.trigger_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.trigger_key IS 'Identity ổn định của trigger/episode/occurrence theo version; dùng dedupe, không sinh key mới chỉ vì worker restart.';


--
-- Name: COLUMN rule_executions.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.state IS 'Trạng thái RUNNING/WAITING hoặc kết quả SUCCEEDED/PARTIAL/FAILED/CANCELLED/NEEDS_ATTENTION/NO_MATCH; RUNNING/WAITING chiếm quota.';


--
-- Name: COLUMN rule_executions.admitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.admitted_at IS 'Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.';


--
-- Name: COLUMN rule_executions.deadline_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.deadline_at IS 'Deadline admitted_at + 15 phút cho cả execution; WAIT/restart không kéo dài ngân sách toàn chuỗi.';


--
-- Name: COLUMN rule_executions.ended_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.ended_at IS 'Thời điểm execution/action kết thúc; NULL khi chưa ghi nhận kết thúc, outcome/state là trục kết quả riêng.';


--
-- Name: COLUMN rule_executions.next_action_position; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.next_action_position IS 'Vị trí bước kế của execution, miền 0..5; giá trị 5 có thể biểu diễn đã qua bước cuối trong chuỗi tối đa 5 action.';


--
-- Name: COLUMN rule_executions.owner_user_id_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.owner_user_id_snapshot IS 'Owner được chụp khi execution admission, dùng phân quyền lịch sử theo policy; request vẫn phải recheck membership hiện hành.';


--
-- Name: COLUMN rule_executions.failure_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.rule_executions.failure_reason IS 'Nguyên nhân thất bại đã chuẩn hóa/redact cho vận hành và lịch sử; không lưu response bí mật của dịch vụ ngoài.';


--
-- Name: execution_history; Type: VIEW; Schema: public; Owner: -
--

/* public.execution_history
 * View lịch sử execution trong cutoff 30 ngày; operational guard chưa giải quyết vẫn giữ ở ledger gốc.
 */
CREATE VIEW public.execution_history WITH (security_invoker='true') AS
 SELECT workspace_id,
    rule_execution_id,
    rule_id,
    rule_version_id,
    trigger_key,
    state,
    admitted_at,
    deadline_at,
    ended_at,
    next_action_position,
    owner_user_id_snapshot,
    failure_reason
   FROM public.rule_executions
  WHERE (admitted_at > (statement_timestamp() - '30 days'::interval));


--
-- Name: VIEW execution_history; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.execution_history IS 'View lịch sử execution trong cutoff 30 ngày; operational guard chưa giải quyết vẫn giữ ở ledger gốc.';


--
-- Name: COLUMN execution_history.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN execution_history.rule_execution_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.rule_execution_id IS 'Identity một lần quyết định/chạy rule version, dùng quota, history, action chain và notification target.';


--
-- Name: COLUMN execution_history.rule_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.rule_id IS 'Identity gốc rule trong workspace, dùng nhóm draft/version/runtime; không là identity một lần chạy.';


--
-- Name: COLUMN execution_history.rule_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.rule_version_id IS 'Identity rule snapshot đã publish, dùng pin trigger/action/execution thay vì đọc draft hiện hành.';


--
-- Name: COLUMN execution_history.trigger_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.trigger_key IS 'Identity ổn định của trigger/episode/occurrence theo version; dùng dedupe, không sinh key mới chỉ vì worker restart.';


--
-- Name: COLUMN execution_history.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.state IS 'Trạng thái RUNNING/WAITING hoặc kết quả SUCCEEDED/PARTIAL/FAILED/CANCELLED/NEEDS_ATTENTION/NO_MATCH; RUNNING/WAITING chiếm quota.';


--
-- Name: COLUMN execution_history.admitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.admitted_at IS 'Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.';


--
-- Name: COLUMN execution_history.deadline_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.deadline_at IS 'Deadline admitted_at + 15 phút cho cả execution; WAIT/restart không kéo dài ngân sách toàn chuỗi.';


--
-- Name: COLUMN execution_history.ended_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.ended_at IS 'Thời điểm execution/action kết thúc; NULL khi chưa ghi nhận kết thúc, outcome/state là trục kết quả riêng.';


--
-- Name: COLUMN execution_history.next_action_position; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.next_action_position IS 'Vị trí bước kế của execution, miền 0..5; giá trị 5 có thể biểu diễn đã qua bước cuối trong chuỗi tối đa 5 action.';


--
-- Name: COLUMN execution_history.owner_user_id_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.owner_user_id_snapshot IS 'Owner được chụp khi execution admission, dùng phân quyền lịch sử theo policy; request vẫn phải recheck membership hiện hành.';


--
-- Name: COLUMN execution_history.failure_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.execution_history.failure_reason IS 'Nguyên nhân thất bại đã chuẩn hóa/redact cho vận hành và lịch sử; không lưu response bí mật của dịch vụ ngoài.';


--
-- Name: firmware_package_templates; Type: TABLE; Schema: public; Owner: -
--

/* public.firmware_package_templates
 * Tập template version được package khai tương thích trong signed manifest. Giữ FK tới version cụ thể,
 * không suy compatibility từ tên hoặc template root.
 */
-- Bảng firmware_package_templates: Tập template version được package khai tương thích trong signed manifest. Giữ
-- FK tới version cụ thể, không suy compatibility từ tên hoặc template root.
CREATE TABLE public.firmware_package_templates (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_package_templates_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_package_id, template_version_id)
    -- Ràng buộc hiện hành firmware_package_templates_workspace_id_firmware_package_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, firmware_package_id) REFERENCES firmware_packages(workspace_id, firmware_package_id)
    -- Ràng buộc hiện hành firmware_package_templates_workspace_id_template_version_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_version_id) REFERENCES template_versions(workspace_id, template_version_id)
    workspace_id uuid NOT NULL,

    -- Identity canonical package firmware trong workspace, dùng liên kết compatibility và OTA jobs.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_package_templates_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_package_id, template_version_id)
    -- Ràng buộc hiện hành firmware_package_templates_workspace_id_firmware_package_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, firmware_package_id) REFERENCES firmware_packages(workspace_id, firmware_package_id)
    firmware_package_id uuid NOT NULL,

    -- Identity snapshot template cụ thể, dùng pin schema và kiểm đúng definition trong workspace.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_package_templates_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_package_id, template_version_id)
    -- Ràng buộc hiện hành firmware_package_templates_workspace_id_template_version_i_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_version_id) REFERENCES template_versions(workspace_id, template_version_id)
    template_version_id uuid NOT NULL
);


--
-- Name: TABLE firmware_package_templates; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.firmware_package_templates IS 'Tập template version được package khai tương thích trong signed manifest. Giữ FK tới version cụ thể, không suy compatibility từ tên hoặc template root.';


--
-- Name: COLUMN firmware_package_templates.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_package_templates.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN firmware_package_templates.firmware_package_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_package_templates.firmware_package_id IS 'Identity canonical package firmware trong workspace, dùng liên kết compatibility và OTA jobs.';


--
-- Name: COLUMN firmware_package_templates.template_version_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_package_templates.template_version_id IS 'Identity snapshot template cụ thể, dùng pin schema và kiểm đúng definition trong workspace.';


--
-- Name: firmware_packages; Type: TABLE; Schema: public; Owner: -
--

/* public.firmware_packages
 * Metadata package firmware đã được validator xác minh, giữ exact signed manifest bytes và chữ ký.
 * Binary nằm ở artifact store; nhãn VERIFIED trong SQL không tự thực hiện kiểm chữ ký.
 */
-- Bảng firmware_packages: Metadata package firmware đã được validator xác minh, giữ exact signed manifest bytes và
-- chữ ký. Binary nằm ở artifact store; nhãn VERIFIED trong SQL không tự thực hiện kiểm chữ ký.
CREATE TABLE public.firmware_packages (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_package_id)
    -- Ràng buộc hiện hành firmware_packages_workspace_id_artifact_digest_key: không trùng tổ hợp giá trị được nêu; các
    -- cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, artifact_digest)
    -- Ràng buộc hiện hành firmware_packages_workspace_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id
    -- giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id) REFERENCES workspaces(workspace_id)
    workspace_id uuid NOT NULL,

    -- Identity canonical package firmware trong workspace, dùng liên kết compatibility và OTA jobs.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_package_id)
    firmware_package_id uuid NOT NULL,

    -- SHA-256 32 byte của artifact firmware, dùng identity nội dung và kiểm binary khớp manifest.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_artifact_digest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(artifact_digest) = 32))
    -- Ràng buộc hiện hành firmware_packages_workspace_id_artifact_digest_key: không trùng tổ hợp giá trị được nêu; các
    -- cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, artifact_digest)
    artifact_digest bytea NOT NULL,

    -- Exact signed manifest bytes làm authority kiểm chữ ký; không dựng lại từ các cột parsed rồi giả là cùng signed
    -- bytes.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_raw_manifest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(raw_manifest) > 0))
    raw_manifest bytea NOT NULL,

    -- Bytes chữ ký của exact raw_manifest theo thuật toán trong trust profile; SQL chỉ lưu bytes, validator phải kiểm
    -- chữ ký.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_signature_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(signature) > 0))
    signature bytea NOT NULL,

    -- Locator artifact trong kho đã duyệt, không là arbitrary URL cho client điều khiển hoặc private signing key.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_artifact_reference_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((btrim(artifact_reference) <> ''::text))
    artifact_reference text NOT NULL,

    -- Kích thước binary firmware tính bằng byte, dùng kiểm manifest, giới hạn download và khả năng chứa image của
    -- board.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_artifact_size_bytes_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((artifact_size_bytes > 0))
    artifact_size_bytes bigint NOT NULL,

    -- Fingerprint SHA-256 32 byte của khóa ký được tin cậy, phục vụ audit/provenance chữ ký firmware.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_signing_key_fingerprint_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(signing_key_fingerprint) = 32))
    signing_key_fingerprint bytea NOT NULL,

    -- Định danh khóa ký public/trust profile dùng kiểm firmware manifest; không lưu private signing key.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    signing_key_identifier text NOT NULL,

    -- Phiên bản cấu trúc signed manifest, hiện 1; khác firmware version hoặc revision package.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_manifest_schema_version_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((manifest_schema_version = 1))
    manifest_schema_version integer NOT NULL,

    -- Model board được signed manifest khai hỗ trợ; validator đối chiếu với device trước OTA.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    board_model text NOT NULL,

    -- Revision phần cứng để kiểm đúng biến thể board/firmware, khác firmware_version và revision chỉnh sửa metadata.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    hardware_revision text NOT NULL,

    -- Phiên bản firmware được thiết bị báo hoặc manifest khai; không tự chứng minh artifact đã được xác minh/chạy
    -- khỏe.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    firmware_version text NOT NULL,

    -- Định danh build firmware trong manifest, dùng truy vết artifact/toolchain; không thay artifact digest.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    build_identifier text NOT NULL,

    -- Nhãn package đã đi qua validator, bảng canonical hiện chỉ VERIFIED; không tự chứng minh chữ ký đúng chỉ nhờ
    -- INSERT giá trị này.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_packages_validation_state_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((validation_state = 'VERIFIED'::text))
    validation_state text NOT NULL,

    -- Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy
    -- định.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    created_at timestamp with time zone NOT NULL,

    -- XID 64 bit của transaction tạo parent; gán bởi trigger, bất biến khi UPDATE, hỗ trợ SAVEPOINT. NULL ở parent
    -- lịch sử nghĩa đã chốt, không được thêm child.
    -- xid8: transaction ID 64 bit của PostgreSQL, dùng marker nội bộ; không dùng làm định danh nghiệp vụ hoặc token
    -- bảo mật.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    publication_transaction_id xid8,

    -- Identity cluster PostgreSQL tạo publication marker; kết hợp XID ngăn authority giả khi logical restore sang
    -- cluster khác. NULL ở parent lịch sử đã chốt.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    publication_cluster_id bigint,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_artifact_digest_check CHECK ((octet_length(artifact_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_artifact_reference_check CHECK ((btrim(artifact_reference) <> ''::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_artifact_size_bytes_check CHECK ((artifact_size_bytes > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_manifest_schema_version_check CHECK ((manifest_schema_version = 1)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_raw_manifest_check CHECK ((octet_length(raw_manifest) > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_signature_check CHECK ((octet_length(signature) > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_signing_key_fingerprint_check CHECK ((octet_length(signing_key_fingerprint) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_packages_validation_state_check CHECK ((validation_state = 'VERIFIED'::text))
);


--
-- Name: TABLE firmware_packages; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.firmware_packages IS 'Metadata package firmware đã được validator xác minh, giữ exact signed manifest bytes và chữ ký. Binary nằm ở artifact store; nhãn VERIFIED trong SQL không tự thực hiện kiểm chữ ký.';


--
-- Name: COLUMN firmware_packages.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN firmware_packages.firmware_package_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.firmware_package_id IS 'Identity canonical package firmware trong workspace, dùng liên kết compatibility và OTA jobs.';


--
-- Name: COLUMN firmware_packages.artifact_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.artifact_digest IS 'SHA-256 32 byte của artifact firmware, dùng identity nội dung và kiểm binary khớp manifest.';


--
-- Name: COLUMN firmware_packages.raw_manifest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.raw_manifest IS 'Exact signed manifest bytes làm authority kiểm chữ ký; không dựng lại từ các cột parsed rồi giả là cùng signed bytes.';


--
-- Name: COLUMN firmware_packages.signature; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.signature IS 'Bytes chữ ký của exact raw_manifest theo thuật toán trong trust profile; SQL chỉ lưu bytes, validator phải kiểm chữ ký.';


--
-- Name: COLUMN firmware_packages.artifact_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.artifact_reference IS 'Locator artifact trong kho đã duyệt, không là arbitrary URL cho client điều khiển hoặc private signing key.';


--
-- Name: COLUMN firmware_packages.artifact_size_bytes; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.artifact_size_bytes IS 'Kích thước binary firmware tính bằng byte, dùng kiểm manifest, giới hạn download và khả năng chứa image của board.';


--
-- Name: COLUMN firmware_packages.signing_key_fingerprint; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.signing_key_fingerprint IS 'Fingerprint SHA-256 32 byte của khóa ký được tin cậy, phục vụ audit/provenance chữ ký firmware.';


--
-- Name: COLUMN firmware_packages.signing_key_identifier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.signing_key_identifier IS 'Định danh khóa ký public/trust profile dùng kiểm firmware manifest; không lưu private signing key.';


--
-- Name: COLUMN firmware_packages.manifest_schema_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.manifest_schema_version IS 'Phiên bản cấu trúc signed manifest, hiện 1; khác firmware version hoặc revision package.';


--
-- Name: COLUMN firmware_packages.board_model; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.board_model IS 'Model board được signed manifest khai hỗ trợ; validator đối chiếu với device trước OTA.';


--
-- Name: COLUMN firmware_packages.hardware_revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.hardware_revision IS 'Revision phần cứng để kiểm đúng biến thể board/firmware, khác firmware_version và revision chỉnh sửa metadata.';


--
-- Name: COLUMN firmware_packages.firmware_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.firmware_version IS 'Phiên bản firmware được thiết bị báo hoặc manifest khai; không tự chứng minh artifact đã được xác minh/chạy khỏe.';


--
-- Name: COLUMN firmware_packages.build_identifier; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.build_identifier IS 'Định danh build firmware trong manifest, dùng truy vết artifact/toolchain; không thay artifact digest.';


--
-- Name: COLUMN firmware_packages.validation_state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.validation_state IS 'Nhãn package đã đi qua validator, bảng canonical hiện chỉ VERIFIED; không tự chứng minh chữ ký đúng chỉ nhờ INSERT giá trị này.';


--
-- Name: COLUMN firmware_packages.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.created_at IS 'Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy định.';


--
-- Name: COLUMN firmware_packages.publication_transaction_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.publication_transaction_id IS 'XID 64 bit của transaction tạo parent; gán bởi trigger, bất biến khi UPDATE, hỗ trợ SAVEPOINT. NULL ở parent lịch sử nghĩa đã chốt, không được thêm child.';


--
-- Name: COLUMN firmware_packages.publication_cluster_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_packages.publication_cluster_id IS 'Identity cluster PostgreSQL tạo publication marker; kết hợp XID ngăn authority giả khi logical restore sang cluster khác. NULL ở parent lịch sử đã chốt.';


--
-- Name: firmware_upload_attempts; Type: TABLE; Schema: public; Owner: -
--

/* public.firmware_upload_attempts
 * Mỗi lần upload/verify firmware, kể cả lần lỗi. Tách khỏi canonical package để chữ ký sai đầu tiên
 * không chiếm identity digest của artifact hợp lệ.
 */
-- Bảng firmware_upload_attempts: Mỗi lần upload/verify firmware, kể cả lần lỗi. Tách khỏi canonical package để chữ
-- ký sai đầu tiên không chiếm identity digest của artifact hợp lệ.
CREATE TABLE public.firmware_upload_attempts (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_upload_attempts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_upload_attempt_id)
    -- Ràng buộc hiện hành firmware_upload_attempts_workspace_id_actor_user_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, actor_user_id) REFERENCES memberships(workspace_id, user_id)
    workspace_id uuid NOT NULL,

    -- Identity một lượt upload/verify, kể cả reject; không là canonical package identity.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_upload_attempts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, firmware_upload_attempt_id)
    firmware_upload_attempt_id uuid NOT NULL,

    -- Tài khoản thực hiện hoặc khởi tạo thao tác, phục vụ kiểm quyền và truy vết; không lấy authority chỉ từ ID client
    -- gửi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_upload_attempts_workspace_id_actor_user_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, actor_user_id) REFERENCES memberships(workspace_id, user_id)
    actor_user_id uuid NOT NULL,

    -- SHA-256 32 byte của artifact firmware, dùng identity nội dung và kiểm binary khớp manifest.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành firmware_upload_attempts_artifact_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(artifact_digest) = 32))
    artifact_digest bytea,

    -- Locator blob upload tạm còn cần verify/cleanup, khác artifact canonical đã được package/job tham chiếu.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    temporary_artifact_reference text,

    -- Kết quả lượt upload UPLOADED/VERIFIED/REJECTED; lần reject không chiếm canonical package identity.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_upload_attempts_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['UPLOADED'::text, 'VERIFIED'::text, 'REJECTED'::text])))
    state text NOT NULL,

    -- Nguyên nhân thất bại đã chuẩn hóa/redact cho vận hành và lịch sử; không lưu response bí mật của dịch vụ ngoài.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    failure_reason text,

    -- Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy
    -- định.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_upload_attempts_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at = (created_at + '24:00:00'::interval)))
    created_at timestamp with time zone NOT NULL,

    -- Mốc created_at + 24 giờ cho artifact upload tạm theo policy; cleanup vẫn phải kiểm reference/lease còn hoạt
    -- động.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành firmware_upload_attempts_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at = (created_at + '24:00:00'::interval)))
    expires_at timestamp with time zone NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_upload_attempts_artifact_digest_check CHECK ((octet_length(artifact_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_upload_attempts_check CHECK ((expires_at = (created_at + '24:00:00'::interval))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT firmware_upload_attempts_state_check CHECK ((state = ANY (ARRAY['UPLOADED'::text, 'VERIFIED'::text, 'REJECTED'::text])))
);


--
-- Name: TABLE firmware_upload_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.firmware_upload_attempts IS 'Mỗi lần upload/verify firmware, kể cả lần lỗi. Tách khỏi canonical package để chữ ký sai đầu tiên không chiếm identity digest của artifact hợp lệ.';


--
-- Name: COLUMN firmware_upload_attempts.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN firmware_upload_attempts.firmware_upload_attempt_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.firmware_upload_attempt_id IS 'Identity một lượt upload/verify, kể cả reject; không là canonical package identity.';


--
-- Name: COLUMN firmware_upload_attempts.actor_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.actor_user_id IS 'Tài khoản thực hiện hoặc khởi tạo thao tác, phục vụ kiểm quyền và truy vết; không lấy authority chỉ từ ID client gửi.';


--
-- Name: COLUMN firmware_upload_attempts.artifact_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.artifact_digest IS 'SHA-256 32 byte của artifact firmware, dùng identity nội dung và kiểm binary khớp manifest.';


--
-- Name: COLUMN firmware_upload_attempts.temporary_artifact_reference; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.temporary_artifact_reference IS 'Locator blob upload tạm còn cần verify/cleanup, khác artifact canonical đã được package/job tham chiếu.';


--
-- Name: COLUMN firmware_upload_attempts.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.state IS 'Kết quả lượt upload UPLOADED/VERIFIED/REJECTED; lần reject không chiếm canonical package identity.';


--
-- Name: COLUMN firmware_upload_attempts.failure_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.failure_reason IS 'Nguyên nhân thất bại đã chuẩn hóa/redact cho vận hành và lịch sử; không lưu response bí mật của dịch vụ ngoài.';


--
-- Name: COLUMN firmware_upload_attempts.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.created_at IS 'Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy định.';


--
-- Name: COLUMN firmware_upload_attempts.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.firmware_upload_attempts.expires_at IS 'Mốc created_at + 24 giờ cho artifact upload tạm theo policy; cleanup vẫn phải kiểm reference/lease còn hoạt động.';


--
-- Name: global_idempotency_records; Type: TABLE; Schema: public; Owner: -
--

/* public.global_idempotency_records
 * Biên nhận chống lặp cho request global theo tài khoản/route/key digest, không gắn workspace đang
 * chọn. Chỉ giữ kết quả đã loại secret trong cửa sổ replay 24 giờ.
 */
-- Bảng global_idempotency_records: Biên nhận chống lặp cho request global theo tài khoản/route/key digest, không
-- gắn workspace đang chọn. Chỉ giữ kết quả đã loại secret trong cửa sổ replay 24 giờ.
CREATE TABLE public.global_idempotency_records (
    -- Tài khoản principal của request global; không đưa workspace đang chọn vào namespace replay.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (user_id, route_key, key_digest)
    -- Ràng buộc hiện hành global_idempotency_records_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (user_id) REFERENCES users(user_id)
    user_id uuid NOT NULL,

    -- Namespace route canonical gồm identity resource cần thiết; không chỉ là route template khi nhiều target dùng
    -- chung idempotency key.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (user_id, route_key, key_digest)
    route_key text NOT NULL,

    -- Digest idempotency key của client; cùng namespace principal/route tạo identity replay, không chứa secret
    -- response.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_key_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(key_digest) = 32))
    -- Ràng buộc hiện hành global_idempotency_records_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (user_id, route_key, key_digest)
    key_digest bytea NOT NULL,

    -- Digest 32 byte của request/body đã canonical hóa để phát hiện cùng identity khác nội dung hoặc đối chiếu send
    -- intent.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_request_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(request_digest) = 32))
    request_digest bytea NOT NULL,

    -- Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at = (admitted_at + '24:00:00'::interval)))
    admitted_at timestamp with time zone NOT NULL,

    -- Hết cửa sổ replay sau admitted_at + 24 giờ; không replay one-time secret, chỉ sanitized_result.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at = (admitted_at + '24:00:00'::interval)))
    expires_at timestamp with time zone NOT NULL,

    -- Receipt đang IN_PROGRESS hoặc COMPLETED; lỗi mất ACK không cho tự kết luận transaction chưa commit.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành global_idempotency_records_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['IN_PROGRESS'::text, 'COMPLETED'::text])))
    state text NOT NULL,

    -- HTTP status đã ghi nhận, miền 100..599 khi có; NULL khi chưa có response đáng tin cậy.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành global_idempotency_records_response_status_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((response_status >= 100) AND (response_status <= 599)))
    response_status integer,

    -- Kết quả replay đã loại secret, không lưu one-time credential response để trả lại sau retry.
    -- jsonb: tài liệu JSON lưu dạng nhị phân; kiểm object/scalar không thay validation đầy đủ cấu trúc và tham chiếu
    -- nghiệp vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    sanitized_result jsonb,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT global_idempotency_records_check CHECK ((expires_at = (admitted_at + '24:00:00'::interval))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT global_idempotency_records_key_digest_check CHECK ((octet_length(key_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT global_idempotency_records_request_digest_check CHECK ((octet_length(request_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT global_idempotency_records_response_status_check CHECK (((response_status >= 100) AND (response_status <= 599))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT global_idempotency_records_state_check CHECK ((state = ANY (ARRAY['IN_PROGRESS'::text, 'COMPLETED'::text])))
);


--
-- Name: TABLE global_idempotency_records; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.global_idempotency_records IS 'Biên nhận chống lặp cho request global theo tài khoản/route/key digest, không gắn workspace đang chọn. Chỉ giữ kết quả đã loại secret trong cửa sổ replay 24 giờ.';


