--
-- Name: membership_grants; Type: TABLE; Schema: public; Owner: -
--

/* public.membership_grants
 * Lịch sử từng lần cấp quyền thành viên. Giữ identity theo generation để lời mời, API key hoặc tác vụ
 * dùng grant cũ không tự có quyền lại khi tài khoản tham gia lại.
 */
-- Bảng membership_grants: Lịch sử từng lần cấp quyền thành viên. Giữ identity theo generation để lời mời, API key
-- hoặc tác vụ dùng grant cũ không tự có quyền lại khi tài khoản tham gia lại.
CREATE TABLE public.membership_grants (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành membership_grants_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, user_id, grant_generation)
    -- Ràng buộc hiện hành membership_grants_workspace_id_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, user_id) REFERENCES memberships(workspace_id, user_id)
    workspace_id uuid NOT NULL,

    -- Identity tài khoản liên quan; khi đi cùng workspace_id phải tham chiếu đúng membership của workspace.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành membership_grants_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, user_id, grant_generation)
    -- Ràng buộc hiện hành membership_grants_workspace_id_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, user_id) REFERENCES memberships(workspace_id, user_id)
    user_id uuid NOT NULL,

    -- Generation của một lần cấp membership cụ thể, lớn hơn 0; không tái sử dụng identity khi remove rồi rejoin.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành membership_grants_grant_generation_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((grant_generation > 0))
    -- Ràng buộc hiện hành membership_grants_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, user_id, grant_generation)
    grant_generation bigint NOT NULL,

    -- Thời điểm phát hành phiên/grant/credential/ticket, làm gốc tính TTL theo loại bản ghi.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    issued_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Thời điểm thu hồi quyền/credential; NULL nghĩa chưa ghi nhận thu hồi, không đồng nghĩa mọi điều kiện xác thực
    -- khác còn hợp lệ.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    revoked_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT membership_grants_grant_generation_check CHECK ((grant_generation > 0))
);


--
-- Name: TABLE membership_grants; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.membership_grants IS 'Lịch sử từng lần cấp quyền thành viên. Giữ identity theo generation để lời mời, API key hoặc tác vụ dùng grant cũ không tự có quyền lại khi tài khoản tham gia lại.';


--
-- Name: COLUMN membership_grants.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.membership_grants.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN membership_grants.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.membership_grants.user_id IS 'Identity tài khoản liên quan; khi đi cùng workspace_id phải tham chiếu đúng membership của workspace.';


--
-- Name: COLUMN membership_grants.grant_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.membership_grants.grant_generation IS 'Generation của một lần cấp membership cụ thể, lớn hơn 0; không tái sử dụng identity khi remove rồi rejoin.';


--
-- Name: COLUMN membership_grants.issued_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.membership_grants.issued_at IS 'Thời điểm phát hành phiên/grant/credential/ticket, làm gốc tính TTL theo loại bản ghi.';


--
-- Name: COLUMN membership_grants.revoked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.membership_grants.revoked_at IS 'Thời điểm thu hồi quyền/credential; NULL nghĩa chưa ghi nhận thu hồi, không đồng nghĩa mọi điều kiện xác thực khác còn hợp lệ.';


--
-- Name: memberships; Type: TABLE; Schema: public; Owner: -
--

/* public.memberships
 * Quan hệ hiện hành giữa tài khoản và workspace: vai trò ADMIN/USER, trạng thái và grant đang sử dụng.
 * Đây là nguồn xác định tư cách thành viên, không sao chép vai trò vào từng thiết bị.
 */
-- Bảng memberships: Quan hệ hiện hành giữa tài khoản và workspace: vai trò ADMIN/USER, trạng thái và grant đang sử
-- dụng. Đây là nguồn xác định tư cách thành viên, không sao chép vai trò vào từng thiết bị.
CREATE TABLE public.memberships (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành fk_memberships_current_grant: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ
    -- quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, user_id, current_grant_generation) REFERENCES membership_grants(workspace_id,
    -- user_id, grant_generation) DEFERRABLE INITIALLY DEFERRED
    -- Ràng buộc hiện hành memberships_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, user_id)
    -- Ràng buộc hiện hành memberships_workspace_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ
    -- quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id) REFERENCES workspaces(workspace_id)
    workspace_id uuid NOT NULL,

    -- Identity tài khoản liên quan; khi đi cùng workspace_id phải tham chiếu đúng membership của workspace.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành fk_memberships_current_grant: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ
    -- quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, user_id, current_grant_generation) REFERENCES membership_grants(workspace_id,
    -- user_id, grant_generation) DEFERRABLE INITIALLY DEFERRED
    -- Ràng buộc hiện hành memberships_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, user_id)
    -- Ràng buộc hiện hành memberships_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ quan
    -- hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (user_id) REFERENCES users(user_id)
    user_id uuid NOT NULL,

    -- Vai trò thành viên ADMIN/USER trong workspace, không là quyền quản trị toàn bộ hệ thống.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành memberships_role_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((role = ANY (ARRAY['ADMIN'::text, 'USER'::text])))
    role text NOT NULL,

    -- Tư cách thành viên ACTIVE/SUSPENDED/REMOVED trong workspace; khác trạng thái tài khoản toàn cục.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'ACTIVE'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự
    -- áp lại khi UPDATE.
    -- Ràng buộc hiện hành memberships_status_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'REMOVED'::text])))
    status text DEFAULT 'ACTIVE'::text NOT NULL,

    -- Tên gọi của tài khoản trong workspace này, độc lập email đăng nhập hoặc tên trong workspace khác.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    alias text,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành memberships_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Phiên bản quyền của membership, chụp vào ticket/job; đường ghi phải tăng khi role/status/quyền thay đổi theo
    -- protocol.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành memberships_authorization_version_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((authorization_version > 0))
    authorization_version bigint DEFAULT 1 NOT NULL,

    -- Grant membership hiện đang dùng; phải trỏ đúng lịch sử cấp quyền, không tự bật lại grant đã revoke.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành fk_memberships_current_grant: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ
    -- quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, user_id, current_grant_generation) REFERENCES membership_grants(workspace_id,
    -- user_id, grant_generation) DEFERRABLE INITIALLY DEFERRED
    -- Ràng buộc hiện hành memberships_current_grant_generation_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((current_grant_generation > 0))
    current_grant_generation bigint NOT NULL,

    -- Thời điểm hình thành membership; lịch sử cấp quyền từng lần được giữ ở membership_grants.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    joined_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Thời điểm membership bị remove; NULL khi chưa ghi nhận remove, không thay điều kiện status/current grant.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    removed_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT memberships_authorization_version_check CHECK ((authorization_version > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT memberships_current_grant_generation_check CHECK ((current_grant_generation > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT memberships_revision_check CHECK ((revision > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT memberships_role_check CHECK ((role = ANY (ARRAY['ADMIN'::text, 'USER'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT memberships_status_check CHECK ((status = ANY (ARRAY['ACTIVE'::text, 'SUSPENDED'::text, 'REMOVED'::text])))
);


--
-- Name: TABLE memberships; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.memberships IS 'Quan hệ hiện hành giữa tài khoản và workspace: vai trò ADMIN/USER, trạng thái và grant đang sử dụng. Đây là nguồn xác định tư cách thành viên, không sao chép vai trò vào từng thiết bị.';


--
-- Name: COLUMN memberships.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN memberships.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.user_id IS 'Identity tài khoản liên quan; khi đi cùng workspace_id phải tham chiếu đúng membership của workspace.';


--
-- Name: COLUMN memberships.role; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.role IS 'Vai trò thành viên ADMIN/USER trong workspace, không là quyền quản trị toàn bộ hệ thống.';


--
-- Name: COLUMN memberships.status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.status IS 'Tư cách thành viên ACTIVE/SUSPENDED/REMOVED trong workspace; khác trạng thái tài khoản toàn cục.';


--
-- Name: COLUMN memberships.alias; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.alias IS 'Tên gọi của tài khoản trong workspace này, độc lập email đăng nhập hoặc tên trong workspace khác.';


--
-- Name: COLUMN memberships.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: COLUMN memberships.authorization_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.authorization_version IS 'Phiên bản quyền của membership, chụp vào ticket/job; đường ghi phải tăng khi role/status/quyền thay đổi theo protocol.';


--
-- Name: COLUMN memberships.current_grant_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.current_grant_generation IS 'Grant membership hiện đang dùng; phải trỏ đúng lịch sử cấp quyền, không tự bật lại grant đã revoke.';


--
-- Name: COLUMN memberships.joined_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.joined_at IS 'Thời điểm hình thành membership; lịch sử cấp quyền từng lần được giữ ở membership_grants.';


--
-- Name: COLUMN memberships.removed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.memberships.removed_at IS 'Thời điểm membership bị remove; NULL khi chưa ghi nhận remove, không thay điều kiện status/current grant.';


--
-- Name: notifications; Type: TABLE; Schema: public; Owner: -
--

/* public.notifications
 * Một mục inbox của một recipient, phân biệt EVENT và PUSH_TEST. Read state thuộc recipient; target
 * typed giữ đích deep link mà không cấp quyền đọc vượt scope hiện hành.
 */
-- Bảng notifications: Một mục inbox của một recipient, phân biệt EVENT và PUSH_TEST. Read state thuộc recipient;
-- target typed giữ đích deep link mà không cấp quyền đọc vượt scope hiện hành.
CREATE TABLE public.notifications (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành notifications_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, notification_id)
    -- Ràng buộc hiện hành notifications_workspace_id_event_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, event_id) REFERENCES events(workspace_id, event_id)
    -- Ràng buộc hiện hành notifications_workspace_id_notification_id_recipient_user_i_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, notification_id, recipient_user_id)
    -- Ràng buộc hiện hành notifications_workspace_id_recipient_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp
    -- có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, recipient_user_id) REFERENCES memberships(workspace_id, user_id)
    -- Ràng buộc hiện hành notifications_workspace_id_target_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, target_device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành notifications_workspace_id_target_rule_execution_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, target_rule_execution_id) REFERENCES rule_executions(workspace_id, rule_execution_id)
    workspace_id uuid NOT NULL,

    -- Identity mục inbox của recipient, là gốc fanout push/deep link; không thay Event source hoặc occurrence
    -- identity.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành notifications_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp
    -- dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, notification_id)
    -- Ràng buộc hiện hành notifications_workspace_id_notification_id_recipient_user_i_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, notification_id, recipient_user_id)
    notification_id uuid NOT NULL,

    -- Thành viên nhận inbox/push; chỉ chính recipient được hưởng quyền đọc và thay đổi read state của inbox.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành notifications_workspace_id_notification_id_recipient_user_i_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, notification_id, recipient_user_id)
    -- Ràng buộc hiện hành notifications_workspace_id_recipient_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp
    -- có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, recipient_user_id) REFERENCES memberships(workspace_id, user_id)
    recipient_user_id uuid NOT NULL,

    -- EVENT là inbox từ Event nghiệp vụ; PUSH_TEST là test push không tạo Event giả.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_notification_source: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((kind = 'EVENT'::text) AND (event_id IS NOT NULL)) OR ((kind = 'PUSH_TEST'::text) AND (event_id IS
    -- NULL))))
    -- Ràng buộc hiện hành ck_notification_target: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((target_type = 'EVENT'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL)) OR ((target_type = 'DEVICE'::text) AND (kind = 'EVENT'::text) AND
    -- (target_device_id IS NOT NULL) AND (target_rule_execution_id IS NULL)) OR ((target_type = 'EXECUTION'::text) AND
    -- (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NOT NULL)) OR
    -- ((target_type = 'NOTIFICATION'::text) AND (kind = 'PUSH_TEST'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL))))
    -- Ràng buộc hiện hành notifications_kind_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((kind = ANY (ARRAY['EVENT'::text, 'PUSH_TEST'::text])))
    kind text NOT NULL,

    -- Identity Event nghiệp vụ trong workspace; khác occurrence_id đại diện từng transition để giao webhook.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_notification_source: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((kind = 'EVENT'::text) AND (event_id IS NOT NULL)) OR ((kind = 'PUSH_TEST'::text) AND (event_id IS
    -- NULL))))
    -- Ràng buộc hiện hành notifications_workspace_id_event_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, event_id) REFERENCES events(workspace_id, event_id)
    event_id uuid,

    -- Loại đích deep link EVENT/EXECUTION/DEVICE/NOTIFICATION, quyết định target FK nào phải có hoặc phải NULL.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_notification_target: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((target_type = 'EVENT'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL)) OR ((target_type = 'DEVICE'::text) AND (kind = 'EVENT'::text) AND
    -- (target_device_id IS NOT NULL) AND (target_rule_execution_id IS NULL)) OR ((target_type = 'EXECUTION'::text) AND
    -- (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NOT NULL)) OR
    -- ((target_type = 'NOTIFICATION'::text) AND (kind = 'PUSH_TEST'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL))))
    -- Ràng buộc hiện hành notifications_target_type_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((target_type = ANY (ARRAY['EVENT'::text, 'EXECUTION'::text, 'DEVICE'::text, 'NOTIFICATION'::text])))
    target_type text NOT NULL,

    -- Thiết bị đích của action hoặc deep link; NULL khi nhánh không có device, nếu có phải cùng workspace và đúng pin.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_notification_target: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((target_type = 'EVENT'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL)) OR ((target_type = 'DEVICE'::text) AND (kind = 'EVENT'::text) AND
    -- (target_device_id IS NOT NULL) AND (target_rule_execution_id IS NULL)) OR ((target_type = 'EXECUTION'::text) AND
    -- (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NOT NULL)) OR
    -- ((target_type = 'NOTIFICATION'::text) AND (kind = 'PUSH_TEST'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL))))
    -- Ràng buộc hiện hành notifications_workspace_id_target_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, target_device_id) REFERENCES devices(workspace_id, device_id)
    target_device_id uuid,

    -- Execution đích của notification; giữ identity lịch sử nhưng không kéo dài quyền đọc history sau retention/mất
    -- quyền.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_notification_target: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((target_type = 'EVENT'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL)) OR ((target_type = 'DEVICE'::text) AND (kind = 'EVENT'::text) AND
    -- (target_device_id IS NOT NULL) AND (target_rule_execution_id IS NULL)) OR ((target_type = 'EXECUTION'::text) AND
    -- (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NOT NULL)) OR
    -- ((target_type = 'NOTIFICATION'::text) AND (kind = 'PUSH_TEST'::text) AND (target_device_id IS NULL) AND
    -- (target_rule_execution_id IS NULL))))
    -- Ràng buộc hiện hành notifications_workspace_id_target_rule_execution_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định
    -- bỏ kiểm khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, target_rule_execution_id) REFERENCES rule_executions(workspace_id, rule_execution_id)
    target_rule_execution_id uuid,

    -- Mốc tạo notification làm gốc expiry push +1 giờ; delivery fanout muộn không được lấy mốc worker mới làm gốc TTL.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    created_at timestamp with time zone NOT NULL,

    -- Thời điểm recipient đánh dấu mục inbox đã đọc; không ACK/resolve Event và không chứng minh provider đã giao
    -- push.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    read_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_notification_source CHECK ((((kind = 'EVENT'::text) AND (event_id IS NOT NULL)) OR ((kind = 'PUSH_TEST'::text) AND (event_id IS NULL)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_notification_target CHECK ((((target_type = 'EVENT'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NULL)) OR ((target_type = 'DEVICE'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NOT NULL) AND (target_rule_execution_id IS NULL)) OR ((target_type = 'EXECUTION'::text) AND (kind = 'EVENT'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NOT NULL)) OR ((target_type = 'NOTIFICATION'::text) AND (kind = 'PUSH_TEST'::text) AND (target_device_id IS NULL) AND (target_rule_execution_id IS NULL)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT notifications_kind_check CHECK ((kind = ANY (ARRAY['EVENT'::text, 'PUSH_TEST'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT notifications_target_type_check CHECK ((target_type = ANY (ARRAY['EVENT'::text, 'EXECUTION'::text, 'DEVICE'::text, 'NOTIFICATION'::text])))
);


--
-- Name: TABLE notifications; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.notifications IS 'Một mục inbox của một recipient, phân biệt EVENT và PUSH_TEST. Read state thuộc recipient; target typed giữ đích deep link mà không cấp quyền đọc vượt scope hiện hành.';


--
-- Name: COLUMN notifications.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN notifications.notification_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.notification_id IS 'Identity mục inbox của recipient, là gốc fanout push/deep link; không thay Event source hoặc occurrence identity.';


--
-- Name: COLUMN notifications.recipient_user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.recipient_user_id IS 'Thành viên nhận inbox/push; chỉ chính recipient được hưởng quyền đọc và thay đổi read state của inbox.';


--
-- Name: COLUMN notifications.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.kind IS 'EVENT là inbox từ Event nghiệp vụ; PUSH_TEST là test push không tạo Event giả.';


--
-- Name: COLUMN notifications.event_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.event_id IS 'Identity Event nghiệp vụ trong workspace; khác occurrence_id đại diện từng transition để giao webhook.';


--
-- Name: COLUMN notifications.target_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.target_type IS 'Loại đích deep link EVENT/EXECUTION/DEVICE/NOTIFICATION, quyết định target FK nào phải có hoặc phải NULL.';


--
-- Name: COLUMN notifications.target_device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.target_device_id IS 'Thiết bị đích của action hoặc deep link; NULL khi nhánh không có device, nếu có phải cùng workspace và đúng pin.';


--
-- Name: COLUMN notifications.target_rule_execution_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.target_rule_execution_id IS 'Execution đích của notification; giữ identity lịch sử nhưng không kéo dài quyền đọc history sau retention/mất quyền.';


--
-- Name: COLUMN notifications.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.created_at IS 'Mốc tạo notification làm gốc expiry push +1 giờ; delivery fanout muộn không được lấy mốc worker mới làm gốc TTL.';


--
-- Name: COLUMN notifications.read_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.notifications.read_at IS 'Thời điểm recipient đánh dấu mục inbox đã đọc; không ACK/resolve Event và không chứng minh provider đã giao push.';


--
-- Name: ota_download_tickets; Type: TABLE; Schema: public; Owner: -
--

/* public.ota_download_tickets
 * Bearer ticket tải artifact cho một OTA job. Lưu digest và expiry không vượt deadline job; không coi
 * ticket là device proof-of-possession.
 */
-- Bảng ota_download_tickets: Bearer ticket tải artifact cho một OTA job. Lưu digest và expiry không vượt deadline
-- job; không coi ticket là device proof-of-possession.
CREATE TABLE public.ota_download_tickets (
    -- Identity quản lý bearer ticket, không phải secret; ticket_digest dùng xác minh/consume.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_download_tickets_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (ticket_id)
    ticket_id uuid NOT NULL,

    -- Digest SHA-256 32 byte của bearer ticket, dùng lookup/consume hoặc tải artifact; raw ticket chỉ được trả qua
    -- kênh admission.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_download_tickets_ticket_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(ticket_digest) = 32))
    -- Ràng buộc hiện hành ota_download_tickets_ticket_digest_key: không trùng tổ hợp giá trị được nêu; các cột riêng
    -- lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (ticket_digest)
    ticket_digest bytea NOT NULL,

    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_download_tickets_workspace_id_ota_job_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp
    -- có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, ota_job_id) REFERENCES ota_jobs(workspace_id, ota_job_id)
    workspace_id uuid NOT NULL,

    -- Identity ý định OTA ổn định qua status/probe/recovery, dùng gắn nonce, artifact và maintenance epoch.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_download_tickets_workspace_id_ota_job_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp
    -- có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, ota_job_id) REFERENCES ota_jobs(workspace_id, ota_job_id)
    ota_job_id uuid NOT NULL,

    -- Thời điểm phát hành phiên/grant/credential/ticket, làm gốc tính TTL theo loại bản ghi.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_download_tickets_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at > issued_at))
    issued_at timestamp with time zone NOT NULL,

    -- Hạn bearer download ticket phải sau issued_at và không vượt deadline của OTA job; không reset khi tải lại.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_download_tickets_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at > issued_at))
    expires_at timestamp with time zone NOT NULL,

    -- Thời điểm thu hồi quyền/credential; NULL nghĩa chưa ghi nhận thu hồi, không đồng nghĩa mọi điều kiện xác thực
    -- khác còn hợp lệ.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    revoked_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_download_tickets_check CHECK ((expires_at > issued_at)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_download_tickets_ticket_digest_check CHECK ((octet_length(ticket_digest) = 32))
);


--
-- Name: TABLE ota_download_tickets; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ota_download_tickets IS 'Bearer ticket tải artifact cho một OTA job. Lưu digest và expiry không vượt deadline job; không coi ticket là device proof-of-possession.';


--
-- Name: COLUMN ota_download_tickets.ticket_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.ticket_id IS 'Identity quản lý bearer ticket, không phải secret; ticket_digest dùng xác minh/consume.';


--
-- Name: COLUMN ota_download_tickets.ticket_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.ticket_digest IS 'Digest SHA-256 32 byte của bearer ticket, dùng lookup/consume hoặc tải artifact; raw ticket chỉ được trả qua kênh admission.';


--
-- Name: COLUMN ota_download_tickets.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN ota_download_tickets.ota_job_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.ota_job_id IS 'Identity ý định OTA ổn định qua status/probe/recovery, dùng gắn nonce, artifact và maintenance epoch.';


--
-- Name: COLUMN ota_download_tickets.issued_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.issued_at IS 'Thời điểm phát hành phiên/grant/credential/ticket, làm gốc tính TTL theo loại bản ghi.';


--
-- Name: COLUMN ota_download_tickets.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.expires_at IS 'Hạn bearer download ticket phải sau issued_at và không vượt deadline của OTA job; không reset khi tải lại.';


--
-- Name: COLUMN ota_download_tickets.revoked_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_download_tickets.revoked_at IS 'Thời điểm thu hồi quyền/credential; NULL nghĩa chưa ghi nhận thu hồi, không đồng nghĩa mọi điều kiện xác thực khác còn hợp lệ.';


--
-- Name: ota_jobs; Type: TABLE; Schema: public; Owner: -
--

/* public.ota_jobs
 * Ý định OTA một thiết bị, chụp firmware nguồn/đích, nonce và maintenance epoch. RECOVERY_REQUIRED
 * tiếp tục giữ slot cho tới settlement có đối soát; timeout không là proof rollback.
 */
-- Bảng ota_jobs: Ý định OTA một thiết bị, chụp firmware nguồn/đích, nonce và maintenance epoch. RECOVERY_REQUIRED
-- tiếp tục giữ slot cho tới settlement có đối soát; timeout không là proof rollback.
CREATE TABLE public.ota_jobs (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng
    -- cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, ota_job_id)
    -- Ràng buộc hiện hành ota_jobs_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành ota_jobs_workspace_id_firmware_package_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, firmware_package_id) REFERENCES firmware_packages(workspace_id, firmware_package_id)
    -- Ràng buộc hiện hành ota_jobs_workspace_id_ota_job_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, ota_job_id, device_id)
    workspace_id uuid NOT NULL,

    -- Identity ý định OTA ổn định qua status/probe/recovery, dùng gắn nonce, artifact và maintenance epoch.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng
    -- cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, ota_job_id)
    -- Ràng buộc hiện hành ota_jobs_workspace_id_ota_job_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, ota_job_id, device_id)
    ota_job_id uuid NOT NULL,

    -- Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng
    -- tenant.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_workspace_id_device_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, device_id) REFERENCES devices(workspace_id, device_id)
    -- Ràng buộc hiện hành ota_jobs_workspace_id_ota_job_id_device_id_key: không trùng tổ hợp giá trị được nêu; các cột
    -- riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, ota_job_id, device_id)
    device_id uuid NOT NULL,

    -- Identity canonical package firmware trong workspace, dùng liên kết compatibility và OTA jobs.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_workspace_id_firmware_package_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, firmware_package_id) REFERENCES firmware_packages(workspace_id, firmware_package_id)
    firmware_package_id uuid NOT NULL,

    -- Firmware nguồn được chụp lúc OTA admission để đối soát upgrade/rollback sau reboot.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    source_firmware_version_snapshot text NOT NULL,

    -- SHA-256 image đích được chụp khi nhận OTA, không đổi theo package/config hiện tại.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_target_artifact_digest_snapshot_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(target_artifact_digest_snapshot) = 32))
    target_artifact_digest_snapshot bytea NOT NULL,

    -- Nonce 32 byte gắn ý định OTA, giúp board/backend phân biệt job cũ và bằng chứng của lần update khác.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_job_nonce_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(job_nonce) = 32))
    job_nonce bytea NOT NULL,

    -- Vòng đời OTA từ QUEUED tới dispatch/download/verify/reboot/health và terminal hoặc RECOVERY_REQUIRED; recovery
    -- vẫn giữ slot.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((state <> 'RECOVERY_REQUIRED'::text) OR (settled_at IS NULL)))
    -- Ràng buộc hiện hành ota_jobs_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải
    -- phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['QUEUED'::text, 'DISPATCHING'::text, 'ACCEPTED'::text, 'DOWNLOADING'::text,
    -- 'VERIFYING'::text, 'REBOOTING'::text, 'HEALTH_CHECK'::text, 'SUCCEEDED'::text, 'FAILED'::text,
    -- 'CANCELLED'::text, 'ROLLED_BACK'::text, 'RECOVERY_REQUIRED'::text])))
    state text NOT NULL,

    -- Pha kỹ thuật OTA hiện được job/status báo; khác state điều phối và phải được validator/worker kiểm theo
    -- protocol.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    phase text NOT NULL,

    -- Thế hệ khóa bảo trì, dùng phân biệt OTA/dispatch đang hiện hành với callback cũ; không reset do reconnect.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_maintenance_epoch_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((maintenance_epoch > 0))
    maintenance_epoch bigint NOT NULL,

    -- Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((deadline_at = (admitted_at + '00:10:00'::interval)))
    admitted_at timestamp with time zone NOT NULL,

    -- Deadline admitted_at + 10 phút của ý định OTA; hết deadline không tự settlement nếu chưa biết image/board state.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_jobs_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((deadline_at = (admitted_at + '00:10:00'::interval)))
    deadline_at timestamp with time zone NOT NULL,

    -- Thời điểm ghi ý định gửi START OTA trước network; có thể đã gửi khi mất ACK, không blind resend chỉ vì thiếu
    -- reply.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    start_intent_at timestamp with time zone,

    -- Thời điểm nghĩa vụ vận hành được đối soát xong và có thể nhả guard/quota; NULL tiếp tục giữ nghĩa vụ chưa giải
    -- quyết.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ota_jobs_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên phải phối
    -- hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((state <> 'RECOVERY_REQUIRED'::text) OR (settled_at IS NULL)))
    settled_at timestamp with time zone,

    -- Lý do cần recovery/đối soát OTA đã redact; không tự giải phóng maintenance hoặc kết luận rollback.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    recovery_reason text,

    -- Boot tham gia recovery được xác minh theo protocol; NULL khi chưa có bằng chứng boot phục hồi.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    recovery_boot_id text,

    -- Thời điểm backend hoàn tất bước đối soát recovery, khác deadline và thời điểm board reboot.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    reconciled_at timestamp with time zone,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành ota_jobs_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_check CHECK ((deadline_at = (admitted_at + '00:10:00'::interval))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_check1 CHECK (((state <> 'RECOVERY_REQUIRED'::text) OR (settled_at IS NULL))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_job_nonce_check CHECK ((octet_length(job_nonce) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_maintenance_epoch_check CHECK ((maintenance_epoch > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_revision_check CHECK ((revision > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_state_check CHECK ((state = ANY (ARRAY['QUEUED'::text, 'DISPATCHING'::text, 'ACCEPTED'::text, 'DOWNLOADING'::text, 'VERIFYING'::text, 'REBOOTING'::text, 'HEALTH_CHECK'::text, 'SUCCEEDED'::text, 'FAILED'::text, 'CANCELLED'::text, 'ROLLED_BACK'::text, 'RECOVERY_REQUIRED'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_jobs_target_artifact_digest_snapshot_check CHECK ((octet_length(target_artifact_digest_snapshot) = 32))
);


--
-- Name: TABLE ota_jobs; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.ota_jobs IS 'Ý định OTA một thiết bị, chụp firmware nguồn/đích, nonce và maintenance epoch. RECOVERY_REQUIRED tiếp tục giữ slot cho tới settlement có đối soát; timeout không là proof rollback.';


--
-- Name: COLUMN ota_jobs.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN ota_jobs.ota_job_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.ota_job_id IS 'Identity ý định OTA ổn định qua status/probe/recovery, dùng gắn nonce, artifact và maintenance epoch.';


--
-- Name: COLUMN ota_jobs.device_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.device_id IS 'Identity thiết bị toàn cục để resolve MQTT và registry; kết hợp workspace_id bảo vệ mọi tham chiếu trong đúng tenant.';


--
-- Name: COLUMN ota_jobs.firmware_package_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.firmware_package_id IS 'Identity canonical package firmware trong workspace, dùng liên kết compatibility và OTA jobs.';


--
-- Name: COLUMN ota_jobs.source_firmware_version_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.source_firmware_version_snapshot IS 'Firmware nguồn được chụp lúc OTA admission để đối soát upgrade/rollback sau reboot.';


--
-- Name: COLUMN ota_jobs.target_artifact_digest_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.target_artifact_digest_snapshot IS 'SHA-256 image đích được chụp khi nhận OTA, không đổi theo package/config hiện tại.';


--
-- Name: COLUMN ota_jobs.job_nonce; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.job_nonce IS 'Nonce 32 byte gắn ý định OTA, giúp board/backend phân biệt job cũ và bằng chứng của lần update khác.';


--
-- Name: COLUMN ota_jobs.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.state IS 'Vòng đời OTA từ QUEUED tới dispatch/download/verify/reboot/health và terminal hoặc RECOVERY_REQUIRED; recovery vẫn giữ slot.';


--
-- Name: COLUMN ota_jobs.phase; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.phase IS 'Pha kỹ thuật OTA hiện được job/status báo; khác state điều phối và phải được validator/worker kiểm theo protocol.';


--
-- Name: COLUMN ota_jobs.maintenance_epoch; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.maintenance_epoch IS 'Thế hệ khóa bảo trì, dùng phân biệt OTA/dispatch đang hiện hành với callback cũ; không reset do reconnect.';


--
-- Name: COLUMN ota_jobs.admitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.admitted_at IS 'Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.';


--
-- Name: COLUMN ota_jobs.deadline_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.deadline_at IS 'Deadline admitted_at + 10 phút của ý định OTA; hết deadline không tự settlement nếu chưa biết image/board state.';


--
-- Name: COLUMN ota_jobs.start_intent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.start_intent_at IS 'Thời điểm ghi ý định gửi START OTA trước network; có thể đã gửi khi mất ACK, không blind resend chỉ vì thiếu reply.';


--
-- Name: COLUMN ota_jobs.settled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.settled_at IS 'Thời điểm nghĩa vụ vận hành được đối soát xong và có thể nhả guard/quota; NULL tiếp tục giữ nghĩa vụ chưa giải quyết.';


--
-- Name: COLUMN ota_jobs.recovery_reason; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.recovery_reason IS 'Lý do cần recovery/đối soát OTA đã redact; không tự giải phóng maintenance hoặc kết luận rollback.';


--
-- Name: COLUMN ota_jobs.recovery_boot_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.recovery_boot_id IS 'Boot tham gia recovery được xác minh theo protocol; NULL khi chưa có bằng chứng boot phục hồi.';


--
-- Name: COLUMN ota_jobs.reconciled_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.reconciled_at IS 'Thời điểm backend hoàn tất bước đối soát recovery, khác deadline và thời điểm board reboot.';


--
-- Name: COLUMN ota_jobs.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.ota_jobs.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: ota_probe_intents; Type: TABLE; Schema: public; Owner: -
--

/* public.ota_probe_intents
 * Ngân sách probe bền vững theo job/recovery epoch. Mỗi ý định probe có request identity để restart
 * không reset budget hoặc tự phát lại START OTA.
 */
-- Bảng ota_probe_intents: Ngân sách probe bền vững theo job/recovery epoch. Mỗi ý định probe có request identity
-- để restart không reset budget hoặc tự phát lại START OTA.
CREATE TABLE public.ota_probe_intents (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_probe_intents_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, ota_job_id, recovery_epoch, probe_number)
    -- Ràng buộc hiện hành ota_probe_intents_workspace_id_ota_job_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, ota_job_id) REFERENCES ota_jobs(workspace_id, ota_job_id)
    workspace_id uuid NOT NULL,

    -- Identity ý định OTA ổn định qua status/probe/recovery, dùng gắn nonce, artifact và maintenance epoch.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_probe_intents_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, ota_job_id, recovery_epoch, probe_number)
    -- Ràng buộc hiện hành ota_probe_intents_workspace_id_ota_job_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, ota_job_id) REFERENCES ota_jobs(workspace_id, ota_job_id)
    ota_job_id uuid NOT NULL,

    -- Thế hệ một đợt recovery/probe của job để ngân sách probe không bị dùng lại sau restart.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_probe_intents_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, ota_job_id, recovery_epoch, probe_number)
    -- Ràng buộc hiện hành ota_probe_intents_recovery_epoch_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((recovery_epoch > 0))
    recovery_epoch bigint NOT NULL,

    -- Số thứ tự probe trong một recovery epoch, từ 1 đến 3; không reset để vượt budget bằng retry.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_probe_intents_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, ota_job_id, recovery_epoch, probe_number)
    -- Ràng buộc hiện hành ota_probe_intents_probe_number_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((probe_number >= 1) AND (probe_number <= 3)))
    probe_number integer NOT NULL,

    -- Identity duy nhất của probe request, dùng ghép reply với đúng ý định gửi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_probe_intents_request_id_key: không trùng tổ hợp giá trị được nêu; các cột riêng lẻ vẫn
    -- có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (request_id)
    request_id uuid NOT NULL,

    -- Thời điểm ghi ý định probe OTA trước network call, dùng giữ budget bền vững qua restart.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    intended_at timestamp with time zone NOT NULL,

    -- Thời điểm adapter ghi nhận đã gửi probe; NULL khi chưa có xác nhận gửi, không mặc định nghĩa là chắc chắn chưa
    -- gửi.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    sent_at timestamp with time zone,

    -- Thời điểm server ghi nhận reply probe, dùng giải thích kết quả recovery và deadline.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    reply_at timestamp with time zone,

    -- Digest 32 byte của reply probe nhận được, phục vụ đối soát cùng request mà không lưu nội dung bí mật.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ota_probe_intents_reply_digest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(reply_digest) = 32))
    reply_digest bytea,

    -- Trạng thái probe INTENT/SENT/REPLIED/UNKNOWN; missing reply không cho reset budget hoặc suy đã rollback.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ota_probe_intents_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['INTENT'::text, 'SENT'::text, 'REPLIED'::text, 'UNKNOWN'::text])))
    state text NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_probe_intents_probe_number_check CHECK (((probe_number >= 1) AND (probe_number <= 3))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_probe_intents_recovery_epoch_check CHECK ((recovery_epoch > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_probe_intents_reply_digest_check CHECK ((octet_length(reply_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ota_probe_intents_state_check CHECK ((state = ANY (ARRAY['INTENT'::text, 'SENT'::text, 'REPLIED'::text, 'UNKNOWN'::text])))
);


