-- Name: COLUMN password_reset_admissions.admission_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.password_reset_admissions.admission_id IS 'Identity một lần admission đã được ghi nhận trong ledger reset/rate; không phải token dùng xác thực.';


--
-- Name: COLUMN password_reset_admissions.workspace_id; Type: COMMENT; Schema: public; Owner: -
