-- Name: COLUMN template_draft_enum_values.template_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_enum_values.template_id IS 'Identity gốc template trong workspace, dùng nhóm các version và nội dung draft; không là identity version đã pin.';


--
-- Name: COLUMN template_draft_enum_values.stream_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_enum_values.stream_key IS 'Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.';


--
-- Name: COLUMN template_draft_enum_values.enum_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_enum_values.enum_value IS 'Một literal JSON number/string được phép của kênh ENUM; validator còn phải kiểm bộ giá trị và type theo contract.';


--
-- Name: template_draft_streams; Type: TABLE; Schema: public; Owner: -
--

/* public.template_draft_streams
 * Các kênh dữ liệu đang chỉnh sửa của một template, gồm datatype, chiều đọc/ghi và giới hạn. Cho phép
 * editor sửa draft trước khi tạo snapshot phiên bản.
 */
-- Bảng template_draft_streams: Các kênh dữ liệu đang chỉnh sửa của một template, gồm datatype, chiều đọc/ghi và
-- giới hạn. Cho phép editor sửa draft trước khi tạo snapshot phiên bản.
CREATE TABLE public.template_draft_streams (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_draft_streams_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, template_id, stream_key)
    -- Ràng buộc hiện hành template_draft_streams_workspace_id_template_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_id) REFERENCES templates(workspace_id, template_id)
    workspace_id uuid NOT NULL,

    -- Identity gốc template trong workspace, dùng nhóm các version và nội dung draft; không là identity version đã
    -- pin.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_draft_streams_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, template_id, stream_key)
    -- Ràng buộc hiện hành template_draft_streams_workspace_id_template_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ
    -- hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_id) REFERENCES templates(workspace_id, template_id)
    template_id uuid NOT NULL,

    -- Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_draft_streams_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, template_id, stream_key)
    -- Ràng buộc hiện hành template_draft_streams_stream_key_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((btrim(stream_key) <> ''::text))
    stream_key text NOT NULL,

    -- Nhãn hiển thị của kênh dữ liệu; stream_key vẫn là khóa kỹ thuật ổn định khi nhãn thay đổi.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    display_name text NOT NULL,

    -- Kiểu dữ liệu NUMBER/BOOLEAN/STRING/ENUM của definition; validator kiểm literal và giới hạn theo kiểu này.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_draft_stream_bounds: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((min_value IS NULL) OR ((data_type = 'NUMBER'::text) AND (min_value > '-Infinity'::double precision)
    -- AND (min_value < 'Infinity'::double precision))) AND ((max_value IS NULL) OR ((data_type = 'NUMBER'::text) AND
    -- (max_value > '-Infinity'::double precision) AND (max_value < 'Infinity'::double precision))) AND ((min_value IS
    -- NULL) OR (max_value IS NULL) OR (min_value <= max_value)) AND ((string_max_length IS NULL) OR (data_type =
    -- 'STRING'::text))))
    -- Ràng buộc hiện hành template_draft_streams_data_type_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((data_type = ANY (ARRAY['NUMBER'::text, 'BOOLEAN'::text, 'STRING'::text, 'ENUM'::text])))
    data_type text NOT NULL,

    -- Chiều sử dụng kênh READ/WRITE/READ_WRITE; tồn tại stream không đồng nghĩa có capability điều khiển.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_draft_streams_direction_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((direction = ANY (ARRAY['READ'::text, 'WRITE'::text, 'READ_WRITE'::text])))
    direction text NOT NULL,

    -- Đơn vị đo hiển thị của kênh, ví dụ đơn vị cảm biến; NULL khi đại lượng không có đơn vị theo schema.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    unit text,

    -- Cận dưới cho giá trị NUMBER hữu hạn; NULL nghĩa không khai cận dưới, không mặc định bằng 0.
    -- double precision: số thực dấu phẩy động 64 bit, có sai số biểu diễn; kiểm finite/range theo CHECK và validator.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_draft_stream_bounds: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((min_value IS NULL) OR ((data_type = 'NUMBER'::text) AND (min_value > '-Infinity'::double precision)
    -- AND (min_value < 'Infinity'::double precision))) AND ((max_value IS NULL) OR ((data_type = 'NUMBER'::text) AND
    -- (max_value > '-Infinity'::double precision) AND (max_value < 'Infinity'::double precision))) AND ((min_value IS
    -- NULL) OR (max_value IS NULL) OR (min_value <= max_value)) AND ((string_max_length IS NULL) OR (data_type =
    -- 'STRING'::text))))
    min_value double precision,

    -- Cận trên cho giá trị NUMBER hữu hạn; NULL nghĩa không khai cận trên, không tự đặt giới hạn phần cứng.
    -- double precision: số thực dấu phẩy động 64 bit, có sai số biểu diễn; kiểm finite/range theo CHECK và validator.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_draft_stream_bounds: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((min_value IS NULL) OR ((data_type = 'NUMBER'::text) AND (min_value > '-Infinity'::double precision)
    -- AND (min_value < 'Infinity'::double precision))) AND ((max_value IS NULL) OR ((data_type = 'NUMBER'::text) AND
    -- (max_value > '-Infinity'::double precision) AND (max_value < 'Infinity'::double precision))) AND ((min_value IS
    -- NULL) OR (max_value IS NULL) OR (min_value <= max_value)) AND ((string_max_length IS NULL) OR (data_type =
    -- 'STRING'::text))))
    max_value double precision,

    -- Độ dài tối đa của STRING tính bằng ký tự theo validation hiện hành; NULL khi schema không khai giới hạn này.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành ck_draft_stream_bounds: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((min_value IS NULL) OR ((data_type = 'NUMBER'::text) AND (min_value > '-Infinity'::double precision)
    -- AND (min_value < 'Infinity'::double precision))) AND ((max_value IS NULL) OR ((data_type = 'NUMBER'::text) AND
    -- (max_value > '-Infinity'::double precision) AND (max_value < 'Infinity'::double precision))) AND ((min_value IS
    -- NULL) OR (max_value IS NULL) OR (min_value <= max_value)) AND ((string_max_length IS NULL) OR (data_type =
    -- 'STRING'::text))))
    -- Ràng buộc hiện hành template_draft_streams_string_max_length_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((string_max_length > 0))
    string_max_length integer,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành template_draft_streams_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Loại kênh TELEMETRY cho số liệu quan sát hoặc STATE cho trạng thái; bắt buộc khai báo tường minh, độc lập với
    -- direction và không tự cấp capability hay quyền điều khiển.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành ck_draft_stream_channel_kind: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((channel_kind = ANY (ARRAY['TELEMETRY'::text, 'STATE'::text])))
    channel_kind text NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_draft_stream_bounds CHECK ((((min_value IS NULL) OR ((data_type = 'NUMBER'::text) AND (min_value > '-Infinity'::double precision) AND (min_value < 'Infinity'::double precision))) AND ((max_value IS NULL) OR ((data_type = 'NUMBER'::text) AND (max_value > '-Infinity'::double precision) AND (max_value < 'Infinity'::double precision))) AND ((min_value IS NULL) OR (max_value IS NULL) OR (min_value <= max_value)) AND ((string_max_length IS NULL) OR (data_type = 'STRING'::text)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT ck_draft_stream_channel_kind CHECK ((channel_kind = ANY (ARRAY['TELEMETRY'::text, 'STATE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_draft_streams_data_type_check CHECK ((data_type = ANY (ARRAY['NUMBER'::text, 'BOOLEAN'::text, 'STRING'::text, 'ENUM'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_draft_streams_direction_check CHECK ((direction = ANY (ARRAY['READ'::text, 'WRITE'::text, 'READ_WRITE'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_draft_streams_revision_check CHECK ((revision > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_draft_streams_stream_key_check CHECK ((btrim(stream_key) <> ''::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_draft_streams_string_max_length_check CHECK ((string_max_length > 0))
);


--
-- Name: TABLE template_draft_streams; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.template_draft_streams IS 'Các kênh dữ liệu đang chỉnh sửa của một template, gồm datatype, chiều đọc/ghi và giới hạn. Cho phép editor sửa draft trước khi tạo snapshot phiên bản.';


--
-- Name: COLUMN template_draft_streams.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN template_draft_streams.template_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.template_id IS 'Identity gốc template trong workspace, dùng nhóm các version và nội dung draft; không là identity version đã pin.';


--
-- Name: COLUMN template_draft_streams.stream_key; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.stream_key IS 'Khóa kỹ thuật ổn định của kênh trong template/version; không dùng nhãn hiển thị thay khóa schema.';


--
-- Name: COLUMN template_draft_streams.display_name; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.display_name IS 'Nhãn hiển thị của kênh dữ liệu; stream_key vẫn là khóa kỹ thuật ổn định khi nhãn thay đổi.';


--
-- Name: COLUMN template_draft_streams.data_type; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.data_type IS 'Kiểu dữ liệu NUMBER/BOOLEAN/STRING/ENUM của definition; validator kiểm literal và giới hạn theo kiểu này.';


--
-- Name: COLUMN template_draft_streams.direction; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.direction IS 'Chiều sử dụng kênh READ/WRITE/READ_WRITE; tồn tại stream không đồng nghĩa có capability điều khiển.';


--
-- Name: COLUMN template_draft_streams.unit; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.unit IS 'Đơn vị đo hiển thị của kênh, ví dụ đơn vị cảm biến; NULL khi đại lượng không có đơn vị theo schema.';


--
-- Name: COLUMN template_draft_streams.min_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.min_value IS 'Cận dưới cho giá trị NUMBER hữu hạn; NULL nghĩa không khai cận dưới, không mặc định bằng 0.';


--
-- Name: COLUMN template_draft_streams.max_value; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.max_value IS 'Cận trên cho giá trị NUMBER hữu hạn; NULL nghĩa không khai cận trên, không tự đặt giới hạn phần cứng.';


--
-- Name: COLUMN template_draft_streams.string_max_length; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.string_max_length IS 'Độ dài tối đa của STRING tính bằng ký tự theo validation hiện hành; NULL khi schema không khai giới hạn này.';


--
-- Name: COLUMN template_draft_streams.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: COLUMN template_draft_streams.channel_kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.template_draft_streams.channel_kind IS 'Loại kênh TELEMETRY cho số liệu quan sát hoặc STATE cho trạng thái; bắt buộc khai báo tường minh, độc lập với direction và không tự cấp capability hay quyền điều khiển.';


--
-- Name: template_versions; Type: TABLE; Schema: public; Owner: -
--

/* public.template_versions
 * Ảnh chụp schema và metadata template tại mỗi lần publish. Là phiên bản được thiết bị tham chiếu cố
 * định để thay đổi draft không làm lệch schema của thiết bị đang chạy.
 */
-- Bảng template_versions: Ảnh chụp schema và metadata template tại mỗi lần publish. Là phiên bản được thiết bị
-- tham chiếu cố định để thay đổi draft không làm lệch schema của thiết bị đang chạy.
CREATE TABLE public.template_versions (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_versions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, template_version_id)
    -- Ràng buộc hiện hành template_versions_workspace_id_published_by_user_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, published_by_user_id) REFERENCES memberships(workspace_id, user_id)
    -- Ràng buộc hiện hành template_versions_workspace_id_template_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_id) REFERENCES templates(workspace_id, template_id)
    -- Ràng buộc hiện hành template_versions_workspace_id_template_id_version_number_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, template_id, version_number)
    workspace_id uuid NOT NULL,

    -- Identity snapshot template cụ thể, dùng pin schema và kiểm đúng definition trong workspace.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_versions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, template_version_id)
    template_version_id uuid NOT NULL,

    -- Identity gốc template trong workspace, dùng nhóm các version và nội dung draft; không là identity version đã
    -- pin.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_versions_workspace_id_template_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có
    -- workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, template_id) REFERENCES templates(workspace_id, template_id)
    -- Ràng buộc hiện hành template_versions_workspace_id_template_id_version_number_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, template_id, version_number)
    template_id uuid NOT NULL,

    -- Số phiên bản publish tăng trong cùng template/rule, bắt đầu 1; khác revision chỉnh sửa metadata.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_versions_version_number_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((version_number > 0))
    -- Ràng buộc hiện hành template_versions_workspace_id_template_id_version_number_key: không trùng tổ hợp giá trị
    -- được nêu; các cột riêng lẻ vẫn có thể lặp khi khóa có nhiều cột.
    -- UNIQUE (workspace_id, template_id, version_number)
    version_number integer NOT NULL,

    -- Tên hiển thị do người dùng đặt cho tài nguyên; không dùng làm identity, quyền hoặc khóa chống lặp.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    name text NOT NULL,

    -- Mã model phần cứng/template theo registry đã duyệt, dùng kiểm tương thích; không suy model từ tên hiển thị.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    model text NOT NULL,

    -- Thời điểm tạo snapshot đã công bố; không thay đổi theo các lần sửa draft sau đó.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    published_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Thành viên thực hiện publish template version, giữ provenance của snapshot đã công bố.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_versions_workspace_id_published_by_user_id_fkey: khóa ngoại giữ đúng bản ghi cha;
    -- tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, published_by_user_id) REFERENCES memberships(workspace_id, user_id)
    published_by_user_id uuid NOT NULL,

    -- SHA-256 32 byte của nội dung snapshot đã publish, dùng nhận diện/đối chiếu định nghĩa thay vì hash metadata
    -- draft hiện tại.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành template_versions_content_digest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(content_digest) = 32))
    content_digest bytea NOT NULL,

    -- XID 64 bit của transaction tạo parent; gán bởi trigger, bất biến khi UPDATE, hỗ trợ SAVEPOINT. NULL ở parent
    -- lịch sử nghĩa đã chốt, không được thêm child.
    -- xid8: transaction ID 64 bit của PostgreSQL, dùng marker nội bộ; không dùng làm định danh nghiệp vụ hoặc token
    -- bảo mật.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    publication_transaction_id xid8,

    -- Identity cluster PostgreSQL tạo publication marker; kết hợp XID ngăn authority giả khi logical restore sang
    -- cluster khác. NULL ở parent lịch sử đã chốt.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    publication_cluster_id bigint,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_versions_content_digest_check CHECK ((octet_length(content_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT template_versions_version_number_check CHECK ((version_number > 0))
);


--
-- Name: TABLE template_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.template_versions IS 'Ảnh chụp schema và metadata template tại mỗi lần publish. Là phiên bản được thiết bị tham chiếu cố định để thay đổi draft không làm lệch schema của thiết bị đang chạy.';


