--
-- Name: user_preferences; Type: TABLE; Schema: public; Owner: -
--

/* public.user_preferences
 * Tùy chọn hiển thị của từng tài khoản, hiện gồm múi giờ. Tách khỏi hồ sơ xác thực để đổi giao diện
 * không làm thay đổi thông tin đăng nhập.
 */
-- Bảng user_preferences: Tùy chọn hiển thị của từng tài khoản, hiện gồm múi giờ. Tách khỏi hồ sơ xác thực để đổi
-- giao diện không làm thay đổi thông tin đăng nhập.
CREATE TABLE public.user_preferences (
    -- Identity tài khoản liên quan; khi đi cùng workspace_id phải tham chiếu đúng membership của workspace.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành user_preferences_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (user_id)
    -- Ràng buộc hiện hành user_preferences_user_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp có workspace_id giữ
    -- quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (user_id) REFERENCES users(user_id)
    user_id uuid NOT NULL,

    -- Múi giờ IANA dùng hiển thị cho user, mặc định UTC; không đổi instant lưu trong DB hay lịch rule hiện hữu.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'UTC'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp
    -- lại khi UPDATE.
    display_timezone text DEFAULT 'UTC'::text NOT NULL,

    -- Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng
    -- transaction contract.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 1: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành user_preferences_revision_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((revision > 0))
    revision bigint DEFAULT 1 NOT NULL,

    -- Thời điểm cập nhật gần nhất do đường ghi quản lý; không mặc định SQL tự cập nhật nếu không có trigger tương ứng.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    updated_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT user_preferences_revision_check CHECK ((revision > 0))
);


--
-- Name: TABLE user_preferences; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.user_preferences IS 'Tùy chọn hiển thị của từng tài khoản, hiện gồm múi giờ. Tách khỏi hồ sơ xác thực để đổi giao diện không làm thay đổi thông tin đăng nhập.';


--
-- Name: COLUMN user_preferences.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.user_preferences.user_id IS 'Identity tài khoản liên quan; khi đi cùng workspace_id phải tham chiếu đúng membership của workspace.';


--
-- Name: COLUMN user_preferences.display_timezone; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.user_preferences.display_timezone IS 'Múi giờ IANA dùng hiển thị cho user, mặc định UTC; không đổi instant lưu trong DB hay lịch rule hiện hữu.';


--
-- Name: COLUMN user_preferences.revision; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.user_preferences.revision IS 'Phiên bản chỉnh sửa bản ghi dùng cho CAS/If-Match hoặc đối soát; bên ghi chịu trách nhiệm cập nhật theo đúng transaction contract.';


--
-- Name: COLUMN user_preferences.updated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.user_preferences.updated_at IS 'Thời điểm cập nhật gần nhất do đường ghi quản lý; không mặc định SQL tự cập nhật nếu không có trigger tương ứng.';


--
-- Name: users; Type: TABLE; Schema: public; Owner: -
--

/* public.users
 * Danh tính tài khoản dùng chung toàn hệ thống: lưu email đăng nhập, bộ kiểm chứng mật khẩu và trạng
 * thái kích hoạt. Vai trò theo workspace nằm ở memberships, không gắn vai trò toàn cục vào tài khoản.
 */
-- Bảng users: Danh tính tài khoản dùng chung toàn hệ thống: lưu email đăng nhập, bộ kiểm chứng mật khẩu và trạng
-- thái kích hoạt. Vai trò theo workspace nằm ở memberships, không gắn vai trò toàn cục vào tài khoản.
CREATE TABLE public.users (
    -- Identity tài khoản toàn cục để đăng nhập và liên kết các membership; không gắn với một workspace duy nhất.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành users_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness áp dụng cho
    -- cả tổ hợp.
    -- PRIMARY KEY (user_id)
    user_id uuid NOT NULL,

    -- Email đã được lớp xác thực chuẩn hóa, dùng lookup tài khoản/lời mời; quy tắc chuẩn hóa phải thống nhất trước
    -- ghi.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành users_email_normalized_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((length(email_normalized) >= 3) AND (length(email_normalized) <= 254)))
    -- Ràng buộc hiện hành users_email_normalized_key: không trùng tổ hợp giá trị được nêu; các cột riêng lẻ vẫn có thể
    -- lặp khi khóa có nhiều cột.
    -- UNIQUE (email_normalized)
    -- CHECK length 3..254 chỉ kiểm số ký tự, không xác minh email RFC, số byte hoặc tự chuẩn hóa; backend phải
    -- validate và chuẩn hóa trước ghi.
    email_normalized text NOT NULL,

    -- Bộ kiểm chứng mật khẩu theo encoding của password hasher; không chứa mật khẩu gốc và không trả về client/log.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    password_hash text NOT NULL,

    -- Trạng thái tài khoản toàn cục ACTIVE/DISABLED; khác trạng thái membership trong một workspace.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành users_account_status_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((account_status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text])))
    account_status text NOT NULL,

    -- Đánh dấu tài khoản phải đổi mật khẩu trước thao tác thông thường; backend dùng để hạn chế admission và session.
    -- boolean: cờ logic true/false; NULL là trạng thái riêng nếu cột cho phép.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT false: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    must_change_password boolean DEFAULT false NOT NULL,

    -- Thời điểm xác nhận tài khoản đã kích hoạt; NULL không được tự suy thành tài khoản tạm nếu provenance là
    -- legacy/unknown.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    activated_at timestamp with time zone,

    -- Nguồn/bằng chứng hình thành trạng thái kích hoạt, giúp phân biệt account tạm mới với dữ liệu legacy chưa rõ lịch
    -- sử.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành users_activation_provenance_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((btrim(activation_provenance) <> ''::text))
    -- CHECK btrim(...)<>'' chặn chuỗi rỗng/chỉ khoảng trắng; không tự giới hạn thành danh sách phương thức kích hoạt
    -- hay chứng minh đã kích hoạt.
    activation_provenance text NOT NULL,

    -- Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy
    -- định.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT transaction_timestamp(): thời điểm bắt đầu transaction, giữ nguyên trong transaction; không phải đồng hồ
    -- thay đổi theo từng statement.
    created_at timestamp with time zone DEFAULT transaction_timestamp() NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT users_account_status_check CHECK ((account_status = ANY (ARRAY['ACTIVE'::text, 'DISABLED'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT users_activation_provenance_check CHECK ((btrim(activation_provenance) <> ''::text)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT users_email_normalized_check CHECK (((length(email_normalized) >= 3) AND (length(email_normalized) <= 254)))
);


--
-- Name: TABLE users; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.users IS 'Danh tính tài khoản dùng chung toàn hệ thống: lưu email đăng nhập, bộ kiểm chứng mật khẩu và trạng thái kích hoạt. Vai trò theo workspace nằm ở memberships, không gắn vai trò toàn cục vào tài khoản.';


--
-- Name: COLUMN users.user_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.user_id IS 'Identity tài khoản toàn cục để đăng nhập và liên kết các membership; không gắn với một workspace duy nhất.';


--
-- Name: COLUMN users.email_normalized; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.email_normalized IS 'Email đã được lớp xác thực chuẩn hóa, dùng lookup tài khoản/lời mời; quy tắc chuẩn hóa phải thống nhất trước ghi.';


--
-- Name: COLUMN users.password_hash; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.password_hash IS 'Bộ kiểm chứng mật khẩu theo encoding của password hasher; không chứa mật khẩu gốc và không trả về client/log.';


--
-- Name: COLUMN users.account_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.account_status IS 'Trạng thái tài khoản toàn cục ACTIVE/DISABLED; khác trạng thái membership trong một workspace.';


--
-- Name: COLUMN users.must_change_password; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.must_change_password IS 'Đánh dấu tài khoản phải đổi mật khẩu trước thao tác thông thường; backend dùng để hạn chế admission và session.';


--
-- Name: COLUMN users.activated_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.activated_at IS 'Thời điểm xác nhận tài khoản đã kích hoạt; NULL không được tự suy thành tài khoản tạm nếu provenance là legacy/unknown.';


--
-- Name: COLUMN users.activation_provenance; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.activation_provenance IS 'Nguồn/bằng chứng hình thành trạng thái kích hoạt, giúp phân biệt account tạm mới với dữ liệu legacy chưa rõ lịch sử.';


--
-- Name: COLUMN users.created_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.users.created_at IS 'Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy định.';


--
-- Name: webhook_deliveries; Type: TABLE; Schema: public; Owner: -
--

/* public.webhook_deliveries
 * Nghĩa vụ giao occurrence tới subscription hoặc một lần TEST, với exact body/endpoint/secret
 * snapshot. Retry dùng cùng delivery identity và body, không dựng lại payload từ dữ liệu hiện tại.
 */
-- Bảng webhook_deliveries: Nghĩa vụ giao occurrence tới subscription hoặc một lần TEST, với exact
-- body/endpoint/secret snapshot. Retry dùng cùng delivery identity và body, không dựng lại payload từ dữ liệu hiện
-- tại.
CREATE TABLE public.webhook_deliveries (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_delivery_id)
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_occurrence_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp
    -- có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, occurrence_id) REFERENCES event_occurrences(workspace_id, occurrence_id)
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_webhook_subscription_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id) REFERENCES webhook_subscriptions(workspace_id,
    -- webhook_subscription_id)
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_webhook_subscription_id_se_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id, secret_version) REFERENCES
    -- webhook_secret_versions(workspace_id, webhook_subscription_id, secret_version)
    workspace_id uuid NOT NULL,

    -- Identity nghĩa vụ webhook giữ nguyên khi retry, để receiver dedupe ngay cả khi response bị mất.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì uniqueness
    -- áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_delivery_id)
    webhook_delivery_id uuid NOT NULL,

    -- Identity cấu hình webhook trong workspace, dùng nhóm filter, secret versions và lịch sử delivery.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_webhook_subscription_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id) REFERENCES webhook_subscriptions(workspace_id,
    -- webhook_subscription_id)
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_webhook_subscription_id_se_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id, secret_version) REFERENCES
    -- webhook_secret_versions(workspace_id, webhook_subscription_id, secret_version)
    webhook_subscription_id uuid NOT NULL,

    -- BUSINESS có occurrence nguồn và budget 6+6; TEST không có occurrence/Event giả, chỉ một lần gửi trong 30 giây.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((kind = 'BUSINESS'::text) AND (occurrence_id IS NOT NULL)) OR ((kind = 'TEST'::text) AND (occurrence_id
    -- IS NULL) AND (manual_batch_count = 0))))
    -- Ràng buộc hiện hành webhook_deliveries_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((kind <> 'TEST'::text) OR (expires_at = (admitted_at + '00:00:30'::interval))))
    -- Ràng buộc hiện hành webhook_deliveries_kind_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((kind = ANY (ARRAY['BUSINESS'::text, 'TEST'::text])))
    kind text NOT NULL,

    -- Identity một transition đã commit; wire webhook eventId ánh xạ identity này, không gộp OPEN/RESOLVED thành một
    -- Event ID.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành webhook_deliveries_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((kind = 'BUSINESS'::text) AND (occurrence_id IS NOT NULL)) OR ((kind = 'TEST'::text) AND (occurrence_id
    -- IS NULL) AND (manual_batch_count = 0))))
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_occurrence_id_fkey: khóa ngoại giữ đúng bản ghi cha; tổ hợp
    -- có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành. FK MATCH SIMPLE mặc định bỏ kiểm
    -- khi có thành phần NULL; CHECK shape riêng vẫn phải đạt.
    -- FOREIGN KEY (workspace_id, occurrence_id) REFERENCES event_occurrences(workspace_id, occurrence_id)
    occurrence_id uuid,

    -- URL đích được chụp khi delivery admission; retry không tự đổi sang URL hiện hành khác.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    endpoint_url_snapshot text NOT NULL,

    -- Revision URL được delivery chụp, phục vụ recheck endpoint/fanout policy và giải thích lịch sử gửi.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_endpoint_revision_snapshot_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((endpoint_revision_snapshot > 0))
    endpoint_revision_snapshot bigint NOT NULL,

    -- Thế hệ secret ký webhook trong một subscription; khác endpoint_revision và được delivery giữ cố định khi retry.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_workspace_id_webhook_subscription_id_se_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id, secret_version) REFERENCES
    -- webhook_secret_versions(workspace_id, webhook_subscription_id, secret_version)
    secret_version bigint NOT NULL,

    -- Exact body bytes gửi webhook và ký HMAC, giữ nguyên khi retry/manual batch; không dựng lại từ live resource.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    raw_body bytea NOT NULL,

    -- SHA-256 32 byte của exact raw_body webhook; producer tính trước gửi và giữ nguyên khi retry.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_body_digest_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(body_digest) = 32))
    body_digest bytea NOT NULL,

    -- Tiến trình PENDING/SENDING/RETRY_WAIT hoặc ACCEPTED/FAILED/DEAD_LETTER/CANCELLED; DEAD_LETTER có thể mở đúng một
    -- manual batch đủ điều kiện.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- DEFAULT 'PENDING'::text: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự
    -- áp lại khi UPDATE.
    -- Ràng buộc hiện hành webhook_deliveries_state_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((state = ANY (ARRAY['PENDING'::text, 'SENDING'::text, 'RETRY_WAIT'::text, 'ACCEPTED'::text,
    -- 'FAILED'::text, 'DEAD_LETTER'::text, 'CANCELLED'::text])))
    state text DEFAULT 'PENDING'::text NOT NULL,

    -- Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at > admitted_at))
    -- Ràng buộc hiện hành webhook_deliveries_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((kind <> 'TEST'::text) OR (expires_at = (admitted_at + '00:00:30'::interval))))
    admitted_at timestamp with time zone NOT NULL,

    -- BUSINESS neo occurrence.committed_at +24 giờ; TEST neo admitted_at +30 giây, độc lập history retention 30 ngày.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_deliveries_check1: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((expires_at > admitted_at))
    -- Ràng buộc hiện hành webhook_deliveries_check2: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((kind <> 'TEST'::text) OR (expires_at = (admitted_at + '00:00:30'::interval))))
    expires_at timestamp with time zone NOT NULL,

    -- Thời điểm quan sát trạng thái kết thúc của command/delivery; không thay gốc expiry hoặc gốc retention.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    terminal_at timestamp with time zone,

    -- Số đợt retry thủ công webhook đã mở, chỉ 0 hoặc 1; TEST không có manual batch.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 0: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành webhook_deliveries_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua, nên
    -- phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((((kind = 'BUSINESS'::text) AND (occurrence_id IS NOT NULL)) OR ((kind = 'TEST'::text) AND (occurrence_id
    -- IS NULL) AND (manual_batch_count = 0))))
    -- Ràng buộc hiện hành webhook_deliveries_manual_batch_count_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((manual_batch_count >= 0) AND (manual_batch_count <= 1)))
    manual_batch_count integer DEFAULT 0 NOT NULL,

    -- Thời điểm sớm nhất được thử gửi tiếp; không được gửi sớm hơn mốc này hoặc vượt expiry/budget của parent.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    next_attempt_at timestamp with time zone,

    -- Hạn thuê xử lý hiện hành của worker; lease hết không chứng minh network side effect chưa xảy ra.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    lease_until timestamp with time zone,

    -- Thế hệ lease tăng khi claim/takeover, dùng CAS để worker cũ không settle kết quả của thế hệ mới.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- DEFAULT 0: giá trị dùng khi INSERT bỏ qua cột; không thay NULL được truyền tường minh và không tự áp lại khi
    -- UPDATE.
    -- Ràng buộc hiện hành webhook_deliveries_lease_generation_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((lease_generation >= 0))
    lease_generation bigint DEFAULT 0 NOT NULL,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_body_digest_check CHECK ((octet_length(body_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_check CHECK ((((kind = 'BUSINESS'::text) AND (occurrence_id IS NOT NULL)) OR ((kind = 'TEST'::text) AND (occurrence_id IS NULL) AND (manual_batch_count = 0)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_check1 CHECK ((expires_at > admitted_at)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_check2 CHECK (((kind <> 'TEST'::text) OR (expires_at = (admitted_at + '00:00:30'::interval)))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_endpoint_revision_snapshot_check CHECK ((endpoint_revision_snapshot > 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_kind_check CHECK ((kind = ANY (ARRAY['BUSINESS'::text, 'TEST'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_lease_generation_check CHECK ((lease_generation >= 0)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_manual_batch_count_check CHECK (((manual_batch_count >= 0) AND (manual_batch_count <= 1))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_deliveries_state_check CHECK ((state = ANY (ARRAY['PENDING'::text, 'SENDING'::text, 'RETRY_WAIT'::text, 'ACCEPTED'::text, 'FAILED'::text, 'DEAD_LETTER'::text, 'CANCELLED'::text])))
);


--
-- Name: TABLE webhook_deliveries; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.webhook_deliveries IS 'Nghĩa vụ giao occurrence tới subscription hoặc một lần TEST, với exact body/endpoint/secret snapshot. Retry dùng cùng delivery identity và body, không dựng lại payload từ dữ liệu hiện tại.';


--
-- Name: COLUMN webhook_deliveries.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN webhook_deliveries.webhook_delivery_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.webhook_delivery_id IS 'Identity nghĩa vụ webhook giữ nguyên khi retry, để receiver dedupe ngay cả khi response bị mất.';


--
-- Name: COLUMN webhook_deliveries.webhook_subscription_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.webhook_subscription_id IS 'Identity cấu hình webhook trong workspace, dùng nhóm filter, secret versions và lịch sử delivery.';


--
-- Name: COLUMN webhook_deliveries.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.kind IS 'BUSINESS có occurrence nguồn và budget 6+6; TEST không có occurrence/Event giả, chỉ một lần gửi trong 30 giây.';


--
-- Name: COLUMN webhook_deliveries.occurrence_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.occurrence_id IS 'Identity một transition đã commit; wire webhook eventId ánh xạ identity này, không gộp OPEN/RESOLVED thành một Event ID.';


--
-- Name: COLUMN webhook_deliveries.endpoint_url_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.endpoint_url_snapshot IS 'URL đích được chụp khi delivery admission; retry không tự đổi sang URL hiện hành khác.';


--
-- Name: COLUMN webhook_deliveries.endpoint_revision_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.endpoint_revision_snapshot IS 'Revision URL được delivery chụp, phục vụ recheck endpoint/fanout policy và giải thích lịch sử gửi.';


--
-- Name: COLUMN webhook_deliveries.secret_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.secret_version IS 'Thế hệ secret ký webhook trong một subscription; khác endpoint_revision và được delivery giữ cố định khi retry.';


--
-- Name: COLUMN webhook_deliveries.raw_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.raw_body IS 'Exact body bytes gửi webhook và ký HMAC, giữ nguyên khi retry/manual batch; không dựng lại từ live resource.';


--
-- Name: COLUMN webhook_deliveries.body_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.body_digest IS 'SHA-256 32 byte của exact raw_body webhook; producer tính trước gửi và giữ nguyên khi retry.';


--
-- Name: COLUMN webhook_deliveries.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.state IS 'Tiến trình PENDING/SENDING/RETRY_WAIT hoặc ACCEPTED/FAILED/DEAD_LETTER/CANCELLED; DEAD_LETTER có thể mở đúng một manual batch đủ điều kiện.';


--
-- Name: COLUMN webhook_deliveries.admitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.admitted_at IS 'Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.';


--
-- Name: COLUMN webhook_deliveries.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.expires_at IS 'BUSINESS neo occurrence.committed_at +24 giờ; TEST neo admitted_at +30 giây, độc lập history retention 30 ngày.';


--
-- Name: COLUMN webhook_deliveries.terminal_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.terminal_at IS 'Thời điểm quan sát trạng thái kết thúc của command/delivery; không thay gốc expiry hoặc gốc retention.';


--
-- Name: COLUMN webhook_deliveries.manual_batch_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.manual_batch_count IS 'Số đợt retry thủ công webhook đã mở, chỉ 0 hoặc 1; TEST không có manual batch.';


--
-- Name: COLUMN webhook_deliveries.next_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.next_attempt_at IS 'Thời điểm sớm nhất được thử gửi tiếp; không được gửi sớm hơn mốc này hoặc vượt expiry/budget của parent.';


--
-- Name: COLUMN webhook_deliveries.lease_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.lease_until IS 'Hạn thuê xử lý hiện hành của worker; lease hết không chứng minh network side effect chưa xảy ra.';


--
-- Name: COLUMN webhook_deliveries.lease_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_deliveries.lease_generation IS 'Thế hệ lease tăng khi claim/takeover, dùng CAS để worker cũ không settle kết quả của thế hệ mới.';


--
-- Name: webhook_delivery_attempts; Type: TABLE; Schema: public; Owner: -
--

/* public.webhook_delivery_attempts
 * Ý định HTTP outbound mỗi lần gửi delivery, với batch và outcome đã loại dữ liệu nhạy cảm. Ngân sách
 * BUSINESS 6 tự động + một batch 6 thủ công, TEST chỉ một attempt.
 */
-- Bảng webhook_delivery_attempts: Ý định HTTP outbound mỗi lần gửi delivery, với batch và outcome đã loại dữ liệu
-- nhạy cảm. Ngân sách BUSINESS 6 tự động + một batch 6 thủ công, TEST chỉ một attempt.
CREATE TABLE public.webhook_delivery_attempts (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_delivery_attempts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_delivery_id, attempt_number)
    -- Ràng buộc hiện hành webhook_delivery_attempts_workspace_id_webhook_delivery_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_delivery_id) REFERENCES webhook_deliveries(workspace_id, webhook_delivery_id)
    workspace_id uuid NOT NULL,

    -- Identity nghĩa vụ webhook giữ nguyên khi retry, để receiver dedupe ngay cả khi response bị mất.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_delivery_attempts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_delivery_id, attempt_number)
    -- Ràng buộc hiện hành webhook_delivery_attempts_workspace_id_webhook_delivery_id_fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_delivery_id) REFERENCES webhook_deliveries(workspace_id, webhook_delivery_id)
    webhook_delivery_id uuid NOT NULL,

    -- Số thứ tự send intent của một delivery, bắt đầu 1; PK và admission guard bảo vệ thứ tự/ngân sách.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_delivery_attempts_attempt_number_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((attempt_number >= 1) AND (attempt_number <= 12)))
    -- Ràng buộc hiện hành webhook_delivery_attempts_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((batch_number = ((attempt_number - 1) / 6)))
    -- Ràng buộc hiện hành webhook_delivery_attempts_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_delivery_id, attempt_number)
    attempt_number integer NOT NULL,

    -- Đợt webhook: 0 là tự động, 1 là đợt retry thủ công duy nhất; không tạo body/delivery identity mới.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_delivery_attempts_batch_number_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((batch_number >= 0) AND (batch_number <= 1)))
    -- Ràng buộc hiện hành webhook_delivery_attempts_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn
    -- qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((batch_number = ((attempt_number - 1) / 6)))
    batch_number integer NOT NULL,

    -- Thời điểm lưu ý định trước side effect bên ngoài DB; dùng tính ngân sách/expiry và phục hồi khi mất ACK.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    intent_at timestamp with time zone NOT NULL,

    -- Digest 32 byte của request/body đã canonical hóa để phát hiện cùng identity khác nội dung hoặc đối chiếu send
    -- intent.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_delivery_attempts_request_digest_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((octet_length(request_digest) = 32))
    request_digest bytea NOT NULL,

    -- HTTP status đã ghi nhận, miền 100..599 khi có; NULL khi chưa có response đáng tin cậy.
    -- integer: số nguyên có dấu 32 bit; CHECK giới hạn miền nghiệp vụ thay vì chỉ dựa phạm vi kiểu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành webhook_delivery_attempts_response_status_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((response_status >= 100) AND (response_status <= 599)))
    response_status integer,

    -- Kết quả quan sát của một HTTP send intent, không tự chứng minh receiver chưa xử lý khi response bị mất.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- NOT NULL: bắt buộc có giá trị. Chuỗi rỗng vẫn cần CHECK riêng.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_delivery_attempts_outcome_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN
    -- vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((outcome = ANY (ARRAY['INTENT'::text, 'ACCEPTED'::text, 'TRANSIENT_FAILURE'::text,
    -- 'PERMANENT_FAILURE'::text, 'UNKNOWN'::text])))
    outcome text NOT NULL,

    -- Thời điểm quan sát được dữ liệu/kết quả; nguồn và ý nghĩa được quy định theo bảng, không mặc định là thời gian
    -- commit.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    observed_at timestamp with time zone,

    -- Thời điểm sớm nhất được thử gửi tiếp; không được gửi sớm hơn mốc này hoặc vượt expiry/budget của parent.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    next_attempt_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_delivery_attempts_attempt_number_check CHECK (((attempt_number >= 1) AND (attempt_number <= 12))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_delivery_attempts_batch_number_check CHECK (((batch_number >= 0) AND (batch_number <= 1))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_delivery_attempts_check CHECK ((batch_number = ((attempt_number - 1) / 6))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_delivery_attempts_outcome_check CHECK ((outcome = ANY (ARRAY['INTENT'::text, 'ACCEPTED'::text, 'TRANSIENT_FAILURE'::text, 'PERMANENT_FAILURE'::text, 'UNKNOWN'::text]))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_delivery_attempts_request_digest_check CHECK ((octet_length(request_digest) = 32)),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_delivery_attempts_response_status_check CHECK (((response_status >= 100) AND (response_status <= 599)))
);


--
-- Name: TABLE webhook_delivery_attempts; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.webhook_delivery_attempts IS 'Ý định HTTP outbound mỗi lần gửi delivery, với batch và outcome đã loại dữ liệu nhạy cảm. Ngân sách BUSINESS 6 tự động + một batch 6 thủ công, TEST chỉ một attempt.';


--
-- Name: COLUMN webhook_delivery_attempts.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN webhook_delivery_attempts.webhook_delivery_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.webhook_delivery_id IS 'Identity nghĩa vụ webhook giữ nguyên khi retry, để receiver dedupe ngay cả khi response bị mất.';


--
-- Name: COLUMN webhook_delivery_attempts.attempt_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.attempt_number IS 'Số thứ tự send intent của một delivery, bắt đầu 1; PK và admission guard bảo vệ thứ tự/ngân sách.';


--
-- Name: COLUMN webhook_delivery_attempts.batch_number; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.batch_number IS 'Đợt webhook: 0 là tự động, 1 là đợt retry thủ công duy nhất; không tạo body/delivery identity mới.';


--
-- Name: COLUMN webhook_delivery_attempts.intent_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.intent_at IS 'Thời điểm lưu ý định trước side effect bên ngoài DB; dùng tính ngân sách/expiry và phục hồi khi mất ACK.';


--
-- Name: COLUMN webhook_delivery_attempts.request_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.request_digest IS 'Digest 32 byte của request/body đã canonical hóa để phát hiện cùng identity khác nội dung hoặc đối chiếu send intent.';


--
-- Name: COLUMN webhook_delivery_attempts.response_status; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.response_status IS 'HTTP status đã ghi nhận, miền 100..599 khi có; NULL khi chưa có response đáng tin cậy.';


--
-- Name: COLUMN webhook_delivery_attempts.outcome; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.outcome IS 'Kết quả quan sát của một HTTP send intent, không tự chứng minh receiver chưa xử lý khi response bị mất.';


--
-- Name: COLUMN webhook_delivery_attempts.observed_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.observed_at IS 'Thời điểm quan sát được dữ liệu/kết quả; nguồn và ý nghĩa được quy định theo bảng, không mặc định là thời gian commit.';


--
-- Name: COLUMN webhook_delivery_attempts.next_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_attempts.next_attempt_at IS 'Thời điểm sớm nhất được thử gửi tiếp; không được gửi sớm hơn mốc này hoặc vượt expiry/budget của parent.';


--
-- Name: webhook_delivery_history; Type: VIEW; Schema: public; Owner: -
--

/* public.webhook_delivery_history
 * View lịch sử webhook trong cutoff 30 ngày từ admitted_at, khác expiry BUSINESS/TEST.
 */
CREATE VIEW public.webhook_delivery_history WITH (security_invoker='true') AS
 SELECT workspace_id,
    webhook_delivery_id,
    webhook_subscription_id,
    kind,
    occurrence_id,
    endpoint_url_snapshot,
    endpoint_revision_snapshot,
    secret_version,
    raw_body,
    body_digest,
    state,
    admitted_at,
    expires_at,
    terminal_at,
    manual_batch_count,
    next_attempt_at,
    lease_until,
    lease_generation
   FROM public.webhook_deliveries
  WHERE (admitted_at > (statement_timestamp() - '30 days'::interval));


--
-- Name: VIEW webhook_delivery_history; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON VIEW public.webhook_delivery_history IS 'View lịch sử webhook trong cutoff 30 ngày từ admitted_at, khác expiry BUSINESS/TEST.';


--
-- Name: COLUMN webhook_delivery_history.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN webhook_delivery_history.webhook_delivery_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.webhook_delivery_id IS 'Identity nghĩa vụ webhook giữ nguyên khi retry, để receiver dedupe ngay cả khi response bị mất.';


--
-- Name: COLUMN webhook_delivery_history.webhook_subscription_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.webhook_subscription_id IS 'Identity cấu hình webhook trong workspace, dùng nhóm filter, secret versions và lịch sử delivery.';


--
-- Name: COLUMN webhook_delivery_history.kind; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.kind IS 'BUSINESS có occurrence nguồn và budget 6+6; TEST không có occurrence/Event giả, chỉ một lần gửi trong 30 giây.';


--
-- Name: COLUMN webhook_delivery_history.occurrence_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.occurrence_id IS 'Identity một transition đã commit; wire webhook eventId ánh xạ identity này, không gộp OPEN/RESOLVED thành một Event ID.';


--
-- Name: COLUMN webhook_delivery_history.endpoint_url_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.endpoint_url_snapshot IS 'URL đích được chụp khi delivery admission; retry không tự đổi sang URL hiện hành khác.';


--
-- Name: COLUMN webhook_delivery_history.endpoint_revision_snapshot; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.endpoint_revision_snapshot IS 'Revision URL được delivery chụp, phục vụ recheck endpoint/fanout policy và giải thích lịch sử gửi.';


--
-- Name: COLUMN webhook_delivery_history.secret_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.secret_version IS 'Thế hệ secret ký webhook trong một subscription; khác endpoint_revision và được delivery giữ cố định khi retry.';


--
-- Name: COLUMN webhook_delivery_history.raw_body; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.raw_body IS 'Exact body bytes gửi webhook và ký HMAC, giữ nguyên khi retry/manual batch; không dựng lại từ live resource.';


--
-- Name: COLUMN webhook_delivery_history.body_digest; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.body_digest IS 'SHA-256 32 byte của exact raw_body webhook; producer tính trước gửi và giữ nguyên khi retry.';


--
-- Name: COLUMN webhook_delivery_history.state; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.state IS 'Tiến trình PENDING/SENDING/RETRY_WAIT hoặc ACCEPTED/FAILED/DEAD_LETTER/CANCELLED; DEAD_LETTER có thể mở đúng một manual batch đủ điều kiện.';


--
-- Name: COLUMN webhook_delivery_history.admitted_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.admitted_at IS 'Thời điểm yêu cầu được backend nhận vào ledger sau kiểm điều kiện; không chứng minh side effect đã thực hiện.';


--
-- Name: COLUMN webhook_delivery_history.expires_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.expires_at IS 'BUSINESS neo occurrence.committed_at +24 giờ; TEST neo admitted_at +30 giây, độc lập history retention 30 ngày.';


--
-- Name: COLUMN webhook_delivery_history.terminal_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.terminal_at IS 'Thời điểm quan sát trạng thái kết thúc của command/delivery; không thay gốc expiry hoặc gốc retention.';


--
-- Name: COLUMN webhook_delivery_history.manual_batch_count; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.manual_batch_count IS 'Số đợt retry thủ công webhook đã mở, chỉ 0 hoặc 1; TEST không có manual batch.';


--
-- Name: COLUMN webhook_delivery_history.next_attempt_at; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.next_attempt_at IS 'Thời điểm sớm nhất được thử gửi tiếp; không được gửi sớm hơn mốc này hoặc vượt expiry/budget của parent.';


--
-- Name: COLUMN webhook_delivery_history.lease_until; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.lease_until IS 'Hạn thuê xử lý hiện hành của worker; lease hết không chứng minh network side effect chưa xảy ra.';


--
-- Name: COLUMN webhook_delivery_history.lease_generation; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_delivery_history.lease_generation IS 'Thế hệ lease tăng khi claim/takeover, dùng CAS để worker cũ không settle kết quả của thế hệ mới.';


--
-- Name: webhook_secret_versions; Type: TABLE; Schema: public; Owner: -
--

/* public.webhook_secret_versions
 * Từng generation secret ký webhook, lưu ciphertext và wrapping key reference. Giữ version còn được
 * delivery tham chiếu; metadata có thể tồn tại sau khi ciphertext được purge theo policy.
 */
-- Bảng webhook_secret_versions: Từng generation secret ký webhook, lưu ciphertext và wrapping key reference. Giữ
-- version còn được delivery tham chiếu; metadata có thể tồn tại sau khi ciphertext được purge theo policy.
CREATE TABLE public.webhook_secret_versions (
    -- Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền
    -- của người gọi.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_secret_versions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_subscription_id, secret_version)
    -- Ràng buộc hiện hành webhook_secret_versions_workspace_id_webhook_subscription__fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id) REFERENCES webhook_subscriptions(workspace_id,
    -- webhook_subscription_id)
    workspace_id uuid NOT NULL,

    -- Identity cấu hình webhook trong workspace, dùng nhóm filter, secret versions và lịch sử delivery.
    -- UUID: định danh 128 bit; kiểu dữ liệu không tự sinh ID và không tự bảo đảm khó đoán, cần cách sinh UUID phù hợp.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_secret_versions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_subscription_id, secret_version)
    -- Ràng buộc hiện hành webhook_secret_versions_workspace_id_webhook_subscription__fkey: khóa ngoại giữ đúng bản ghi
    -- cha; tổ hợp có workspace_id giữ quan hệ trong đúng tenant, không thay kiểm quyền hiện hành.
    -- FOREIGN KEY (workspace_id, webhook_subscription_id) REFERENCES webhook_subscriptions(workspace_id,
    -- webhook_subscription_id)
    webhook_subscription_id uuid NOT NULL,

    -- Thế hệ secret ký webhook trong một subscription; khác endpoint_revision và được delivery giữ cố định khi retry.
    -- bigint: số nguyên có dấu 64 bit, phù hợp bộ đếm/generation tăng lâu dài; không tự tăng nếu chưa có cơ chế cấp
    -- giá trị.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    -- Ràng buộc hiện hành webhook_secret_versions_pkey: khóa chính duy nhất và không NULL; nếu gồm nhiều cột thì
    -- uniqueness áp dụng cho cả tổ hợp.
    -- PRIMARY KEY (workspace_id, webhook_subscription_id, secret_version)
    -- Ràng buộc hiện hành webhook_secret_versions_secret_version_check: CHECK chỉ chặn khi biểu thức là FALSE;
    -- NULL/UNKNOWN vẫn qua, nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK ((secret_version > 0))
    secret_version bigint NOT NULL,

    -- Secret recoverable đã mã hóa cho escrow/ký webhook; key wrapping nằm ngoài DB và chỉ đường ghi có custody được
    -- dùng giá trị này.
    -- bytea: dãy byte nhị phân; tên digest/ciphertext mô tả mục đích, bản thân kiểu không băm hoặc mã hóa dữ liệu.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành webhook_secret_versions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((secret_ciphertext IS NULL) = (encryption_key_reference IS NULL)))
    secret_ciphertext bytea,

    -- Tham chiếu/version của khóa dùng giải mã ciphertext, không chứa key material; NULL phải đồng bộ với nhánh không
    -- có ciphertext.
    -- text: chuỗi Unicode có độ dài biến đổi; kiểu này không tự trim, đổi chữ thường hoặc xác minh định dạng nghiệp
    -- vụ.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    -- Ràng buộc hiện hành webhook_secret_versions_check: CHECK chỉ chặn khi biểu thức là FALSE; NULL/UNKNOWN vẫn qua,
    -- nên phải phối hợp NOT NULL và CHECK shape khi cần.
    -- CHECK (((secret_ciphertext IS NULL) = (encryption_key_reference IS NULL)))
    encryption_key_reference text,

    -- Thời điểm tạo bản ghi dưới dạng timestamptz; dùng provenance/sắp xếp hoặc retention khi policy của bảng quy
    -- định.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- NOT NULL: bắt buộc có giá trị.
    -- Không có DEFAULT: đường ghi phải cung cấp giá trị, trừ khi trigger được chỉ định gán trước INSERT.
    created_at timestamp with time zone NOT NULL,

    -- Thời điểm boot/secret version được retire; dữ liệu lịch sử và các nghĩa vụ còn tham chiếu có thể tiếp tục được
    -- giữ.
    -- timestamptz: lưu thời điểm tuyệt đối theo UTC, hiển thị theo TimeZone của phiên; không lưu tên múi giờ gốc.
    -- Cho phép NULL: chưa có/không áp dụng giá trị theo nghiệp vụ; không đồng nghĩa chuỗi rỗng hoặc số 0.
    retired_at timestamp with time zone,

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_secret_versions_check CHECK (((secret_ciphertext IS NULL) = (encryption_key_reference IS NULL))),

    -- Ràng buộc cấp bảng: kiểm quan hệ giữa các thuộc tính; mô tả ở từng cột dùng metadata hiện hành.
    CONSTRAINT webhook_secret_versions_secret_version_check CHECK ((secret_version > 0))
);


--
-- Name: TABLE webhook_secret_versions; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.webhook_secret_versions IS 'Từng generation secret ký webhook, lưu ciphertext và wrapping key reference. Giữ version còn được delivery tham chiếu; metadata có thể tồn tại sau khi ciphertext được purge theo policy.';


--
-- Name: COLUMN webhook_secret_versions.workspace_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_secret_versions.workspace_id IS 'Identity workspace sở hữu dữ liệu, dùng giữ phạm vi tenant trong khóa, FK và truy vấn; không tự chứng minh quyền của người gọi.';


--
-- Name: COLUMN webhook_secret_versions.webhook_subscription_id; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_secret_versions.webhook_subscription_id IS 'Identity cấu hình webhook trong workspace, dùng nhóm filter, secret versions và lịch sử delivery.';


--
-- Name: COLUMN webhook_secret_versions.secret_version; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_secret_versions.secret_version IS 'Thế hệ secret ký webhook trong một subscription; khác endpoint_revision và được delivery giữ cố định khi retry.';


--
-- Name: COLUMN webhook_secret_versions.secret_ciphertext; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON COLUMN public.webhook_secret_versions.secret_ciphertext IS 'Secret recoverable đã mã hóa cho escrow/ký webhook; key wrapping nằm ngoài DB và chỉ đường ghi có custody được dùng giá trị này.';


--
-- Name: COLUMN webhook_secret_versions.encryption_key_reference; Type: COMMENT; Schema: public; Owner: -
